.seo-card p {
  color: var(--muted);
  line-height: 1.65;
  font-weight: 650
}

.cu-replace,
.seo-compare {
  display: grid;
  grid-template-columns: .85fr 1.15fr;
  gap: 50px;
  align-items: center
}

.cu-feature-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  justify-content: flex-end
}

.cu-feature-cloud span {
  min-height: 56px;
  display: flex;
  align-items: center;
  padding: 0 20px;
  border-radius: 18px;
  background: #fff;
