}

.cu-agents h2,
.cu-agents p {
  color: #fff
}

.cu-agents .cu-section-head p {
  color: rgba(255, 255, 255, .66)
}

.cu-agent-grid {
  width: min(1220px, 100%);
  margin: 0 auto
}

.cu-agent-card {
  background: rgba(255, 255, 255, .07);
  border-color: rgba(255, 255, 255, .11);
  color: #fff
}

.cu-agent-top {
  display: flex;
  justify-content: space-between;
  margin-bottom: 44px
}

.cu-agent-top span {
  width: 56px;
  height: 56px;
  border-radius: 18px;
  background: rgba(255, 255, 255, .1);
  display: grid;
  place-items: center
}

.cu-agent-top em {
  font-style: normal;
  color: rgba(255, 255, 255, .3);
  font-size: 34px;
  font-weight: 900
}

.cu-pricing .cu-price-grid {
  grid-template-columns: repeat(3, 1fr)
}

.cu-price-grid article.featured {
  color: #fff;
  background: linear-gradient(145deg, #130b2a, #2a105d);
  transform: translateY(-14px)
}

.cu-price-badge {
  width: max-content;
  border-radius: 999px;
  padding: 8px 12px;
  color: #fff;
  background: var(--grad);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase
}

.cu-price-grid strong {
  display: block;
  font-size: 46px;
  letter-spacing: -.08em
}

.cu-price-grid ul {
  padding: 0;
  margin: 0;
  list-style: none
}

.cu-price-grid li {
  display: flex;
  gap: 8px;
  margin: 12px 0;
  color: var(--muted);
  font-weight: 800
}

.cu-price-grid .featured li,
.cu-price-grid .featured p {
  color: rgba(255, 255, 255, .75)
}

.cu-final {
  width: min(1160px, calc(100% - 36px));
  margin: 40px auto 0;
  padding: clamp(44px, 7vw, 84px);
  border-radius: 42px;
  text-align: center;
  background: #fff;
  border: 1px solid var(--line);
  box-shadow: var(--shadow)
}

.cu-final>div {
  max-width: 820px;
  margin: auto
}

.cu-footer {
  width: min(1220px, calc(100% - 36px));
  margin: auto;
  padding: 38px 0 46px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  color: var(--muted)
}

.cu-footer div {
  display: flex;
  gap: 14px;
  flex-wrap: wrap
}

.seo-page {
  min-height: 100vh;
  background: #fff;
  color: var(--ink)
}

.seo-hero {
  position: relative;
  text-align: center;
  padding: 92px 20px;
  width: min(1040px, 100%);
  margin: auto
}

.seo-hero p {
