}

.seo-actions {
  display: flex;
  justify-content: center;
  gap: 14px;
  flex-wrap: wrap
}

.seo-grid-section,
.seo-compare,
.seo-faq,
.seo-final {
  width: min(1120px, calc(100% - 36px));
  margin: auto;
  padding: 70px 0
