  .sidebar-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, .36);
    border: 0;
    z-index: 19
  }

  .sb-close-btn {
    display: block
  }

  .mobile-menu {
    display: grid;
    place-items: center;
    width: 46px;
    height: 46px;
    border: 1px solid var(--line);
    background: #fff;
    border-radius: 16px;
