  }

  .choice-grid.two,
  .launch-settings,
  .grid2,
  .grid4,
  .campaign-grid,
  .skeleton-list,
  .provider-grid-v54,
  .form-grid-v54,
  .cu-preview-metrics,
  .cu-preview-board,
  .cu-workspace-grid,
  .cu-agent-grid,
  .cu-price-grid,
  .seo-card-grid {
    grid-template-columns: 1fr
  }

  .stage-line {
    grid-template-columns: 1fr
  }

  .stage-fields .icon-btn {
    width: 100%
  }

  .pipeline-head {
    display: block
  }

  .pipeline-head>div:last-child {
    margin-top: 14px
  }

  .table-wrap {
    overflow-x: auto
  }

  .table-title,
  table {
    min-width: 760px
  }

  .map-card {
    height: 520px
  }

  .cu-nav {
    flex-wrap: wrap;
    gap: 12px;
    padding-top: 12px;
    padding-bottom: 12px
  }

  .cu-nav-links {
    order: 3;
    width: 100%;
    justify-content: center;
    overflow: auto
  }

  .cu-hero {
    padding-top: 48px
  }

  .cu-preview-body {
    grid-template-columns: 1fr
  }

  .cu-preview-side {
    display: none
  }

  .cu-price-grid article.featured {
    transform: none
  }

  .cu-footer {
    flex-direction: column;
    text-align: center
  }
