}

.rf-auth-brand {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: 12px;
  width: max-content;
  color: #fff;
  font-weight: 900;
  font-size: 20px;
}

.rf-auth-brand span {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  background: var(--grad);
  color: #fff;
  box-shadow: 0 18px 42px rgba(255, 78, 205, .24);
}

.rf-auth-copy {
  position: relative;
  z-index: 1;
}

.rf-auth-eyebrow {
  display: inline-flex;
  width: max-content;
  max-width: 100%;
  align-items: center;
  border-radius: 999px;
  padding: 9px 14px;
  color: #fff;
  background: rgba(255, 255, 255, .1);
  border: 1px solid rgba(255, 255, 255, .14);
  text-transform: uppercase;
  letter-spacing: .12em;
  font-size: 11px;
  font-weight: 900;
}

.rf-auth-copy h1 {
  max-width: 540px;
  margin: 22px 0 16px;
  color: #fff;
  font-size: clamp(42px, 5vw, 66px);
  line-height: .96;
  letter-spacing: -.078em;
  font-weight: 900;
}

.rf-auth-copy p {
  max-width: 520px;
  margin: 0;
  color: rgba(255, 255, 255, .72);
  font-size: 17px;
  line-height: 1.72;
  font-weight: 700;
}

.rf-auth-proof {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.rf-auth-proof span {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 13px;
  border-radius: 999px;
  color: rgba(255, 255, 255, .82);
  background: rgba(255, 255, 255, .09);
  border: 1px solid rgba(255, 255, 255, .12);
  font-size: 12px;
  font-weight: 850;
}

.rf-auth-panel {
  display: grid;
  align-content: center;
}

.rf-auth-card {
  background:
    radial-gradient(circle at 10% 0%, rgba(123, 66, 255, .07), transparent 18rem),
    radial-gradient(circle at 100% 12%, rgba(255, 78, 205, .06), transparent 20rem),
    rgba(255, 255, 255, .97);
  border: 1px solid var(--line);
  border-radius: 34px;
  padding: 38px;
  box-shadow: var(--shadow-lg);
  backdrop-filter: blur(16px);
}

.rf-auth-card-head {
  margin-bottom: 24px;
}

.rf-auth-card-head h2 {
  margin: 0 0 8px;
  color: #150e22;
  font-size: 32px;
  line-height: 1.08;
  letter-spacing: -.05em;
  font-weight: 900;
}

.rf-auth-card-head p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.6;
  font-weight: 750;
}

.rf-auth-form {
  display: grid;
  gap: 17px;
}

.rf-auth-stepbar {
  display: grid;
  grid-template-columns: max-content 1fr max-content;
  gap: 12px;
  align-items: center;
  margin-bottom: 4px;
}

.rf-auth-stepbar span {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--dim);
  font-size: 12px;
  font-weight: 900;
}

.rf-auth-stepbar span b {
  width: 26px;
  height: 26px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #f2eefb;
  color: var(--dim);
  font-size: 12px;
}

.rf-auth-stepbar span.active {
  color: var(--purple);
}

.rf-auth-stepbar span.active b {
  color: #fff;
  background: var(--grad);
  box-shadow: 0 10px 22px rgba(123, 66, 255, .22);
}

.rf-auth-stepbar i {
  height: 2px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(123, 66, 255, .32), rgba(255, 78, 205, .22));
}

.rf-auth-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.rf-auth-field {
  display: block;
  margin: 0;
}

.rf-auth-field > span {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
  color: #3f314f;
  font-size: 12px;
  font-weight: 900;
}

.rf-auth-field > div {
  position: relative;
}

.rf-auth-field svg {
  position: absolute;
  left: 17px;
  top: 50%;
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  color: var(--purple);
  pointer-events: none;
}

.rf-auth-field input {
  width: 100%;
  height: 58px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: #fff;
  padding: 0 18px 0 50px;
  color: var(--ink);
  font-weight: 850;
  outline: none;
  box-shadow: 0 10px 24px rgba(35, 18, 80, .04);
  transition: .2s;
}

.rf-auth-field input::placeholder {
  color: #8e849b;
  font-weight: 800;
}

.rf-auth-field input:hover {
  border-color: rgba(123, 66, 255, .24);
}

.rf-auth-field input:focus {
  border-color: rgba(123, 66, 255, .62);
  box-shadow:
    0 0 0 5px rgba(123, 66, 255, .10),
    0 14px 30px rgba(35, 18, 80, .07);
}

.rf-auth-type-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 14px;
}

.rf-auth-type-card {
  position: relative;
  min-height: 132px;
  display: grid;
  grid-template-columns: 68px 1fr;
  align-items: center;
  gap: 18px;
  border: 1px solid var(--line);
  border-radius: 26px;
  background: #fff;
  padding: 22px;
  color: var(--ink);
  text-align: left;
  box-shadow: 0 14px 34px rgba(35, 18, 80, .06);
  transition: .2s;
}

.rf-auth-type-card:hover {
  transform: translateY(-2px);
  border-color: rgba(123, 66, 255, .28);
  box-shadow: 0 24px 54px rgba(35, 18, 80, .11);
}

.rf-auth-type-card.active {
  border: 2px solid rgba(123, 66, 255, .72);
  background:
    radial-gradient(circle at 100% 0%, rgba(255, 78, 205, .12), transparent 14rem),
    rgba(246, 242, 255, .96);
  padding: 21px;
}

.rf-auth-type-icon {
  width: 68px;
  height: 68px;
  display: grid;
  place-items: center;
  border-radius: 22px;
  background: #f5f2ff;
  color: var(--purple);
}

.rf-auth-type-card.active .rf-auth-type-icon {
  background: var(--grad);
  color: #fff;
  box-shadow: 0 16px 34px rgba(123, 66, 255, .24);
}

.rf-auth-type-card b {
  display: block;
  color: #20132e;
  font-size: 20px;
  line-height: 1.1;
  letter-spacing: -.035em;
  font-weight: 950;
}

.rf-auth-type-card small {
  display: block;
  max-width: 360px;
  margin-top: 8px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
  font-weight: 750;
}

.rf-auth-type-card i {
  position: absolute;
  right: 17px;
  top: 17px;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--grad);
  color: #fff;
  box-shadow: 0 10px 22px rgba(123, 66, 255, .24);
}

.rf-auth-selected-note {
  display: grid;
  grid-template-columns: 46px 1fr;
  align-items: center;
  gap: 12px;
  padding: 14px;
  border-radius: 18px;
  background: #f7f4ff;
  border: 1px solid rgba(123, 66, 255, .13);
}

.rf-auth-selected-note > span {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 15px;
  background: var(--grad);
  color: #fff;
}

.rf-auth-selected-note b {
  display: block;
  color: #20132e;
  font-size: 14px;
  font-weight: 950;
}

.rf-auth-selected-note small {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
  font-weight: 750;
}

.rf-auth-form-actions {
  display: grid;
  grid-template-columns: 130px 1fr;
  gap: 12px;
  align-items: center;
  margin-top: 4px;
}

.rf-auth-back-btn {
  min-height: 58px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: #fff;
  color: var(--muted);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-weight: 900;
  box-shadow: 0 10px 24px rgba(35, 18, 80, .04);
  transition: .2s;
}

.rf-auth-back-btn:hover {
  color: var(--purple);
  border-color: rgba(123, 66, 255, .24);
  transform: translateY(-1px);
}

.rf-auth-row {
  display: flex;
  justify-content: flex-end;
  margin-top: -2px;
}

.rf-auth-row a,
.rf-auth-footer a {
  color: var(--purple);
  font-weight: 900;
}

.rf-auth-submit {
  min-height: 58px;
  border: 0;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  width: 100%;
  margin-top: 0;
  background: var(--grad);
  color: #fff;
  font-weight: 950;
  box-shadow:
    0 18px 42px rgba(123, 66, 255, .24),
    0 8px 22px rgba(255, 78, 205, .16);
  transition: .2s;
}

.rf-auth-submit:hover {
  transform: translateY(-1px);
  box-shadow: 0 24px 54px rgba(123, 66, 255, .32);
}

.rf-auth-submit:disabled {
  opacity: .55;
  cursor: not-allowed;
  transform: none;
  box-shadow:
    0 12px 30px rgba(123, 66, 255, .16),
    0 6px 18px rgba(255, 78, 205, .10);
}

.rf-auth-error,
.rf-auth-success,
.rf-auth-dev-link {
  margin: 0;
  padding: 13px 14px;
  border-radius: 16px;
  font-size: 13px;
  line-height: 1.5;
  font-weight: 800;
}

.rf-auth-error {
  color: #b72334;
  background: #fff1f4;
  border: 1px solid #ffd0dc;
}

.rf-auth-success {
  color: #0b8b66;
  background: #effdf7;
  border: 1px solid #c8f4df;
}

.rf-auth-dev-link {
  display: grid;
  gap: 8px;
  color: #5f420b;
  background: #fff9e8;
  border: 1px solid #f4d992;
  word-break: break-all;
}

.rf-auth-dev-link b {
  color: #3f2a08;
}

.rf-auth-dev-link a {
  color: var(--purple);
  font-weight: 900;
}

.rf-auth-footer {
  margin-top: 18px;
  text-align: center;
  color: var(--muted);
  font-weight: 800;
}

.rf-auth-field input:-webkit-autofill,
.rf-auth-field input:-webkit-autofill:hover,
.rf-auth-field input:-webkit-autofill:focus {
  -webkit-text-fill-color: var(--ink);
  box-shadow: 0 0 0 1000px #fff inset;
}

@media (max-width: 1080px) {
  .rf-auth-shell {
    grid-template-columns: 1fr;
    max-width: 760px;
  }

  .rf-auth-hero {
    min-height: 430px;
  }
}

@media (max-width: 620px) {
  .rf-auth-page {
    padding: 12px;
  }

  .rf-auth-hero,
  .rf-auth-card {
    border-radius: 26px;
    padding: 24px;
  }

  .rf-auth-copy h1 {
    font-size: 38px;
  }

  .rf-auth-grid {
    grid-template-columns: 1fr;
  }

  .rf-auth-stepbar {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .rf-auth-stepbar i {
    display: none;
  }

  .rf-auth-type-card {
    min-height: 118px;
    grid-template-columns: 56px 1fr;
    padding: 18px;
  }

  .rf-auth-type-card.active {
    padding: 17px;
  }

  .rf-auth-type-icon {
    width: 56px;
    height: 56px;
    border-radius: 18px;
  }

  .rf-auth-type-card b {
    font-size: 17px;
  }

  .rf-auth-form-actions {
    grid-template-columns: 1fr;
  }

  .rf-auth-back-btn,
  .rf-auth-field input,
  .rf-auth-submit {
    height: 54px;
    min-height: 54px;
  }
}
