/* ==========================================================
   ReachFly campaign loader
   ========================================================== */

.rf-loader-backdrop {
  position: fixed;
  inset: 0;
  z-index: 99999;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(circle at 20% 20%, rgba(123, 66, 255, .26), transparent 22rem),
    radial-gradient(circle at 80% 10%, rgba(255, 78, 205, .20), transparent 22rem),
    rgba(10, 4, 26, .72);
  backdrop-filter: blur(18px);
}

.rf-loader-card {
  width: min(560px, 100%);
  position: relative;
  overflow: hidden;
  padding: 28px;
  border-radius: 34px;
  border: 1px solid rgba(255, 255, 255, .18);
  background:
    radial-gradient(circle at 0 0, rgba(255, 255, 255, .16), transparent 18rem),
    linear-gradient(180deg, rgba(255, 255, 255, .98), rgba(248, 245, 255, .94));
  box-shadow:
    0 34px 100px rgba(0, 0, 0, .34),
    inset 0 1px 0 rgba(255, 255, 255, .9);
}

.rf-loader-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, transparent, rgba(255, 255, 255, .42), transparent);
  transform: translateX(-120%);
  animation: rfLoaderShine 2.8s ease-in-out infinite;
}

.rf-loader-visual {
  position: relative;
  height: 178px;
  display: grid;
  place-items: center;
  margin-bottom: 8px;
}

.rf-loader-orbit {
  position: absolute;
  width: 172px;
  height: 172px;
  display: grid;
  place-items: center;
}

.rf-loader-orbit i {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  border: 1px solid rgba(123, 66, 255, .18);
  animation: rfLoaderPulse 2.2s ease-in-out infinite;
}

.rf-loader-orbit i:nth-child(2) {
  inset: 18px;
  animation-delay: .22s;
}

.rf-loader-orbit i:nth-child(3) {
  inset: 36px;
  animation-delay: .44s;
}

.rf-loader-orbit > span {
  width: 11px;
  height: 11px;
  position: absolute;
  top: 18px;
  left: 50%;
  margin-left: -5.5px;
  border-radius: 999px;
  background: var(--grad);
  box-shadow: 0 0 0 10px rgba(123, 66, 255, .12);
  transform-origin: 5.5px 68px;
  animation: rfLoaderOrbit 1.35s linear infinite;
}

.rf-loader-percent-ring {
  position: relative;
  width: 132px;
  height: 132px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background:
    radial-gradient(circle at 50% 45%, rgba(255, 255, 255, .96), rgba(246, 242, 255, .95));
  box-shadow: 0 22px 55px rgba(123, 66, 255, .20);
}

.rf-loader-percent-ring svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.rf-loader-percent-ring circle {
  fill: none;
  stroke-width: 9;
  stroke-linecap: round;
}

.rf-loader-percent-ring circle:first-child {
  stroke: rgba(123, 66, 255, .12);
}

.rf-loader-percent-ring circle:last-child {
  stroke: url("#unused");
  stroke: #7b42ff;
  stroke-dasharray: 326.73;
  transition: stroke-dashoffset .35s ease;
  filter: drop-shadow(0 4px 10px rgba(123, 66, 255, .30));
}

.rf-loader-percent-ring div {
  position: relative;
  z-index: 1;
  text-align: center;
}

.rf-loader-percent-ring b {
  display: block;
  color: var(--ink);
  font-size: 28px;
  line-height: 1;
  font-weight: 950;
  letter-spacing: -.06em;
}

.rf-loader-percent-ring small {
  display: block;
  margin-top: 5px;
  color: var(--dim);
  font-size: 10px;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: .10em;
}

.rf-loader-copy {
  text-align: center;
}

.rf-loader-eyebrow {
  display: inline-flex;
  min-height: 28px;
  align-items: center;
  padding: 0 11px;
  border-radius: 999px;
  background: rgba(123, 66, 255, .10);
  color: var(--purple);
  font-size: 10px;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: .10em;
}

.rf-loader-copy h2 {
  margin: 13px 0 8px;
  color: var(--ink);
  font-size: clamp(26px, 4vw, 36px);
  line-height: 1;
  letter-spacing: -.06em;
  font-weight: 950;
}

.rf-loader-copy p {
  max-width: 430px;
  margin: 0 auto;
  color: var(--muted);
  font-size: 15px;
  line-height: 1.55;
  font-weight: 750;
}

.rf-loader-progress {
  height: 12px;
  overflow: hidden;
  margin: 24px 0 18px;
  border-radius: 999px;
  background: rgba(123, 66, 255, .11);
  box-shadow: inset 0 0 0 1px rgba(123, 66, 255, .08);
}

.rf-loader-progress span {
  height: 100%;
  display: block;
  border-radius: inherit;
  background: var(--grad);
  box-shadow: 0 10px 24px rgba(123, 66, 255, .28);
  transition: width .35s ease;
}

.rf-loader-stage-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.rf-loader-stage-grid > div {
  min-width: 0;
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  padding: 10px;
  border-radius: 18px;
  border: 1px solid rgba(123, 66, 255, .10);
  background: rgba(255, 255, 255, .68);
}

.rf-loader-stage-grid > div > span {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  color: var(--muted);
  background: rgba(123, 66, 255, .08);
  font-size: 12px;
  font-weight: 950;
}

.rf-loader-stage-grid div.current {
  border-color: rgba(123, 66, 255, .28);
  background: rgba(123, 66, 255, .07);
}

.rf-loader-stage-grid div.current > span {
  color: #fff;
  background: var(--grad);
  animation: rfLoaderCurrent 1.1s ease-in-out infinite;
}

.rf-loader-stage-grid div.done > span {
  color: #fff;
  background: linear-gradient(135deg, #16a34a, #22c55e);
}

.rf-loader-stage-grid b,
.rf-loader-stage-grid small {
  display: block;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rf-loader-stage-grid b {
  color: var(--ink);
  font-size: 12px;
  font-weight: 950;
}

.rf-loader-stage-grid small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 750;
}

.rf-loader-note {
  margin: 18px 0 0;
  padding: 12px 14px;
  border-radius: 16px;
  background: rgba(123, 66, 255, .07);
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
  font-weight: 800;
  text-align: center;
}

@keyframes rfLoaderPulse {
  0%, 100% {
    transform: scale(.92);
    opacity: .32;
  }

  50% {
    transform: scale(1.04);
    opacity: .75;
  }
}

@keyframes rfLoaderOrbit {
  to {
    transform: rotate(360deg);
  }
}

@keyframes rfLoaderCurrent {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(123, 66, 255, .28);
  }

  50% {
    box-shadow: 0 0 0 8px rgba(123, 66, 255, .10);
  }
}

@keyframes rfLoaderShine {
  0%, 65% {
    transform: translateX(-120%);
  }

  100% {
    transform: translateX(120%);
  }
}

@media (max-width: 640px) {
  .rf-loader-card {
    padding: 22px;
    border-radius: 28px;
  }

  .rf-loader-visual {
    height: 150px;
  }

  .rf-loader-orbit {
    width: 146px;
    height: 146px;
  }

  .rf-loader-percent-ring {
    width: 116px;
    height: 116px;
  }

  .rf-loader-stage-grid {
    grid-template-columns: 1fr;
  }
}
