/* ==========================================================
   External campaign message composer + AI writer
   ========================================================== */

.external-message-composer {
  padding: 20px;
  border-radius: 24px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, .84);
  box-shadow: 0 14px 36px rgba(35, 18, 80, .055);
}

.external-message-head {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  margin-bottom: 16px;
}

.external-message-head > span {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  color: var(--purple);
  background: rgba(123, 66, 255, .1);
}

.external-message-head h3 {
  margin: 0 0 5px;
  color: var(--ink);
  font-size: 20px;
  letter-spacing: -.035em;
  font-weight: 950;
}

.external-message-head p {
