  font-weight: 750;
}

.external-message-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.external-message-tabs button {
  min-height: 36px;
  padding: 0 13px;
  border-radius: 999px;
  border: 1px solid rgba(123, 66, 255, .14);
  background: #fff;
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}

.external-message-tabs button.active {
