  border: 1px solid rgba(123, 66, 255, .12);
}

.external-ai-context b {
  color: var(--purple);
}

.external-variable-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin: 12px 0 16px;
}

.external-variable-row button {
  min-height: 32px;
  padding: 0 10px;
  border-radius: 999px;
  border: 1px solid rgba(123, 66, 255, .14);
  background: rgba(123, 66, 255, .07);
  color: var(--purple);
  font-size: 12px;
  font-weight: 900;
}

.external-variable-row button:hover {
  color: #fff;
  background: var(--grad);
  border-color: transparent;
  box-shadow: 0 12px 24px rgba(123, 66, 255, .18);
}

.external-preview-message {
  margin-top: 16px;
  padding: 18px;
  border-radius: 20px;
  background: #f7f4ff;
  border: 1px solid rgba(123, 66, 255, .14);
  color: #3f314f;
  font-size: 15px;
  line-height: 1.7;
  font-weight: 750;
  white-space: pre-wrap;
