  gap: 18px;
  margin-bottom: 20px;
}

.external-card-head h2 {
  margin: 0 0 7px;
  color: var(--ink);
  font-size: 26px;
  line-height: 1.08;
  letter-spacing: -.05em;
  font-weight: 950;
}

.external-card-head h3 {
  margin: 0;
}

.external-card-head p {
  max-width: 760px;
  margin: 0;
  color: var(--muted);
  line-height: 1.58;
  font-weight: 750;
}

.external-card-head > span {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
