  padding: 18px;
  border-radius: 23px;
  border: 1px solid var(--line);
  background: #fff;
  text-align: left;
  box-shadow: 0 14px 34px rgba(35, 18, 80, .05);
}

.external-integration-grid button > span {
  width: 46px;
  height: 46px;
  border-radius: 16px;
}

.external-integration-grid b {
  color: var(--ink);
  font-weight: 950;
}

.external-integration-grid small {
  color: var(--muted);
  line-height: 1.45;
  font-weight: 750;
}

/* Uploaded sheet preview */

.external-records-panel {
  width: 100%;
  min-width: 0;
  margin-top: 22px;
  padding: 20px;
  border-radius: 28px;
  border: 1px solid rgba(123, 66, 255, .13);
  background: rgba(255, 255, 255, .78);
  box-shadow: 0 18px 48px rgba(35, 18, 80, .055);
  overflow: hidden;
}

.external-records-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 16px;
}

.external-records-head h3 {
  margin: 0 0 5px;
  color: var(--ink);
  font-size: 22px;
  letter-spacing: -.04em;
  font-weight: 950;
}

.external-records-head p {
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
  font-weight: 750;
}

.external-records-head .field {
  min-width: 220px;
  margin: 0;
}

.external-record-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.external-record-stat {
  padding: 15px;
  border-radius: 20px;
  border: 1px solid var(--line);
  background: #fff;
}

.external-record-stat span {
  display: block;
  color: var(--dim);
  font-size: 10px;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: .08em;
}

.external-record-stat b {
  display: block;
  margin-top: 7px;
  color: var(--ink);
  font-size: 24px;
  line-height: 1;
  font-weight: 950;
}

.external-table-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin: 16px 0;
}

.external-table-search {
  width: min(460px, 100%);
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 14px;
  border-radius: 999px;
  border: 1px solid rgba(123, 66, 255, .14);
  background: #fff;
  color: var(--purple);
}

.external-table-search input {
  width: 100%;
  border: 0;
  outline: 0;
  color: var(--ink);
  background: transparent;
  font-weight: 800;
}

.external-table-meta {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
  white-space: nowrap;
}

.external-column-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 14px;
}

.external-column-cloud span {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 999px;
  color: var(--purple);
  background: rgba(123, 66, 255, .09);
  font-size: 11px;
  font-weight: 900;
}

.external-column-cloud.all-columns {
  max-height: 90px;
  overflow: auto;
  padding-right: 4px;
}

.external-table-wrap {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  border-radius: 24px;
  border: 1px solid var(--line);
  background: #fff;
}

.external-table-wrap.full-sheet {
  max-width: 100%;
}

.external-preview-table {
  width: max-content;
  min-width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 13px;
}

.external-preview-table th {
  position: sticky;
  top: 0;
  z-index: 2;
  padding: 13px 15px;
  color: #8e849b;
  background: #fbf9ff;
  border-bottom: 1px solid var(--line);
  text-align: left;
  font-size: 10px;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: .08em;
  white-space: nowrap;
}

.external-preview-table td {
  max-width: 260px;
  padding: 14px 15px;
  border-top: 1px solid #f0ecf8;
  color: #544760;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.external-preview-table th:first-child,
.external-preview-table td:first-child {
  position: sticky;
  left: 0;
  z-index: 3;
  width: 58px;
  min-width: 58px;
  max-width: 58px;
  background: #fff;
  color: var(--purple);
  font-weight: 950;
}

.external-preview-table th:first-child {
  background: #fbf9ff;
}

/* Campaign setup */

.external-launch-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 350px;
  gap: 20px;
  align-items: start;
  min-width: 0;
}

.external-launch-main,
.external-launch-side {
  min-width: 0;
}

.external-launch-side {
  position: sticky;
  top: 24px;
}

.external-data-health {
  display: grid;
  gap: 10px;
}

.external-mapped-fields {
  display: grid;
  gap: 9px;
}

.external-mapped-fields div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 11px 12px;
  border-radius: 15px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, .78);
}

.external-mapped-fields span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 850;
}

.external-mapped-fields b {
  color: var(--ink);
  font-size: 12px;
  font-weight: 950;
  text-align: right;
  max-width: 170px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

/* Segments */

.external-segment-panel {
  margin-top: 20px;
  padding: 18px;
  border-radius: 26px;
  border: 1px solid rgba(123, 66, 255, .13);
  background:
    radial-gradient(circle at 0 0, rgba(123, 66, 255, .08), transparent 14rem),
    rgba(255, 255, 255, .78);
}

.external-segment-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 14px;
}

.external-segment-card {
  min-width: 0;
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  gap: 11px;
  align-items: center;
  padding: 13px;
  border-radius: 18px;
  border: 1px solid var(--line);
  background: #fff;
  text-align: left;
  transition: .2s;
}

.external-segment-card:hover,
.external-segment-card.active {
  transform: translateY(-1px);
  border-color: rgba(123, 66, 255, .34);
  box-shadow: 0 16px 38px rgba(35, 18, 80, .08);
}

.external-segment-card.active {
  background: #f7f4ff;
}

.external-segment-card > span {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 15px;
  color: var(--purple);
  background: rgba(123, 66, 255, .10);
}

.external-segment-card.active > span {
  color: #fff;
  background: var(--grad);
}

.external-segment-card b,
.external-segment-card small {
  display: block;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.external-segment-card b {
  color: var(--ink);
  font-size: 13px;
  font-weight: 950;
}

.external-segment-card small {
  margin-top: 3px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

/* Message composer */

.external-message-composer {
  margin-top: 20px;
  padding: 20px;
  border-radius: 28px;
  border: 1px solid rgba(123, 66, 255, .13);
  background: rgba(255, 255, 255, .78);
}

.external-message-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.external-message-head h3 {
  margin: 0 0 5px;
  color: var(--ink);
  font-size: 22px;
  letter-spacing: -.04em;
  font-weight: 950;
}

.external-message-head p {
  margin: 0;
  color: var(--muted);
  line-height: 1.55;
  font-size: 13px;
  font-weight: 750;
}

.external-message-tabs {
  display: inline-flex;
  align-items: center;
  padding: 5px;
  border-radius: 999px;
  background: #f4f0ff;
  border: 1px solid rgba(123, 66, 255, .12);
}

.external-message-tabs button {
  min-height: 34px;
  padding: 0 14px;
  border: 0;
  border-radius: 999px;
  color: var(--muted);
  background: transparent;
  font-size: 12px;
  font-weight: 950;
}

.external-message-tabs button.active {
  color: #fff;
  background: var(--grad);
  box-shadow: 0 10px 22px rgba(123, 66, 255, .22);
}

.external-ai-writer {
  display: grid;
  gap: 14px;
  margin-top: 18px;
  padding: 16px;
  border-radius: 22px;
  border: 1px solid rgba(123, 66, 255, .13);
  background:
    radial-gradient(circle at 100% 0, rgba(255, 78, 205, .09), transparent 12rem),
    #fbf9ff;
}

.external-ai-writer .field {
  margin: 0;
}

.external-ai-writer textarea {
  min-height: 110px;
}

.external-ai-context {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding: 13px;
  border-radius: 18px;
  border: 1px solid rgba(123, 66, 255, .12);
  background: #fff;
}

.external-ai-context > span {
  width: 48px;
  height: 48px;
  border-radius: 16px;
}

.external-ai-context b,
.external-ai-context small {
  display: block;
}

.external-ai-context b {
  color: var(--ink);
  font-weight: 950;
}

.external-ai-context small {
  margin-top: 3px;
  color: var(--muted);
  line-height: 1.45;
  font-weight: 750;
}

.external-message-field {
  margin-top: 16px;
}

.external-message-field textarea {
  min-height: 220px;
  line-height: 1.65;
}

.external-variable-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.external-variable-row button {
  min-height: 32px;
  padding: 0 11px;
  border-radius: 999px;
  border: 1px solid rgba(123, 66, 255, .14);
  color: var(--purple);
  background: rgba(123, 66, 255, .07);
  font-size: 12px;
  font-weight: 900;
}

.external-variable-row button:hover {
  color: #fff;
  background: var(--grad);
  border-color: transparent;
}

.external-preview-message,
.external-message-preview {
  margin-top: 16px;
  padding: 18px;
  border-radius: 22px;
  border: 1px solid rgba(123, 66, 255, .13);
  background: #fff;
}

.external-preview-message small,
.external-message-preview small {
  display: block;
  color: var(--dim);
  font-size: 10px;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: .09em;
}

.external-preview-message b,
.external-message-preview b {
  display: block;
  margin: 8px 0;
  color: var(--ink);
  font-weight: 950;
}

.external-preview-message p,
.external-message-preview p {
  margin: 0;
  color: var(--muted);
  line-height: 1.75;
  font-weight: 700;
  white-space: pre-wrap;
}

/* Mapped preview cards */

.external-mapped-preview {
  grid-column: 1 / -1;
}

.external-mapped-lead-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.external-mapped-lead-card {
  min-width: 0;
  display: grid;
  grid-template-columns: 54px minmax(0, 1fr);
  gap: 14px;
  padding: 17px;
  border-radius: 22px;
  border: 1px solid var(--line);
  background: #fff;
  box-shadow: 0 14px 34px rgba(35, 18, 80, .045);
}

.external-mapped-avatar {
  width: 54px;
  height: 54px;
  border-radius: 18px;
  font-weight: 950;
}

.external-mapped-lead-card h3 {
  margin: 0;
  color: var(--ink);
  font-size: 18px;
  line-height: 1.2;
  letter-spacing: -.035em;
  font-weight: 950;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.external-mapped-lead-card p {
  margin: 5px 0 12px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.external-mapped-lead-card div div {
  margin-top: 9px;
}

.external-mapped-lead-card small {
  display: block;
  color: var(--dim);
  font-size: 10px;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: .08em;
}

.external-mapped-lead-card b {
  display: block;
  margin-top: 3px;
  color: var(--ink);
  font-size: 13px;
  line-height: 1.45;
  font-weight: 850;
  word-break: break-word;
}

.external-mapped-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin-top: 0 !important;
}

.external-mapped-card-top em {
  flex: 0 0 auto;
  max-width: 160px;
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  padding: 0 9px;
  border-radius: 999px;
  color: var(--purple);
  background: rgba(123, 66, 255, .09);
  font-size: 10px;
  font-style: normal;
  font-weight: 950;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Review */

.external-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.external-summary-item {
  min-width: 0;
  padding: 16px;
  border-radius: 20px;
  border: 1px solid var(--line);
  background: #fff;
}

.external-summary-item span {
  display: block;
  color: var(--dim);
  font-size: 10px;
  font-weight: 950;
  text-transform: uppercase;
  letter-spacing: .08em;
}

.external-summary-item b {
  display: block;
  margin-top: 7px;
  color: var(--ink);
  font-size: 15px;
  line-height: 1.35;
  font-weight: 950;
  overflow: hidden;
  text-overflow: ellipsis;
}

.external-message-preview h3 {
  margin: 0 0 12px;
  color: var(--ink);
  font-size: 21px;
  letter-spacing: -.04em;
  font-weight: 950;
}

.external-warning {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 12px;
  margin-top: 16px;
  padding: 14px;
  border-radius: 18px;
  border: 1px solid #f4d992;
  background: #fff9e8;
  color: #71520b;
}

.external-warning svg {
  margin-top: 2px;
}

.external-warning b {
  display: block;
  color: #5d4212;
  font-weight: 950;
}

.external-warning p {
  margin: 4px 0 0;
  color: #765724;
  line-height: 1.55;
  font-weight: 750;
}

.external-actions {
  position: sticky;
  bottom: 18px;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 14px;
  border-radius: 999px;
  border: 1px solid rgba(123, 66, 255, .13);
  background: rgba(255, 255, 255, .86);
  box-shadow: 0 22px 60px rgba(35, 18, 80, .12);
  backdrop-filter: blur(18px);
}

.external-actions span {
  color: var(--muted);
  font-size: 13px;
  font-weight: 850;
}

.external-actions button:disabled {
  opacity: .55;
  cursor: not-allowed;
  transform: none;
}

/* Responsive */

@media (max-width: 1180px) {
  .external-launch-layout {
    grid-template-columns: 1fr;
  }

  .external-launch-side {
    position: static;
  }

  .external-segment-grid,
  .external-summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .external-integration-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  .external-campaign-hero,
  .external-card-head,
  .external-records-head,
  .external-table-toolbar,
  .external-message-head {
    flex-direction: column;
    align-items: stretch;
  }

  .external-stepper {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .external-source-grid,
  .external-field-grid,
  .external-mapped-lead-grid,
  .external-record-stats {
    grid-template-columns: 1fr;
  }

  .external-records-head .field {
    min-width: 0;
  }

  .external-table-meta {
    white-space: normal;
  }
}

@media (max-width: 640px) {
  .external-card,
  .external-records-panel,
  .external-message-composer {
    padding: 17px;
    border-radius: 24px;
  }

  .external-stepper,
  .external-segment-grid,
  .external-summary-grid,
  .external-integration-grid {
    grid-template-columns: 1fr;
  }

  .external-step {
    grid-template-columns: 38px minmax(0, 1fr);
  }

  .external-step > span {
    width: 38px;
    height: 38px;
  }

  .external-campaign-hero h1 {
    font-size: 30px;
  }

  .external-upload-box {
    min-height: 190px;
    padding: 22px;
  }

  .external-mapped-lead-card {
    grid-template-columns: 1fr;
  }

  .external-mapped-card-top {
    display: grid;
  }

  .external-actions {
    position: static;
    border-radius: 24px;
    align-items: stretch;
    flex-direction: column;
  }

  .external-actions .btn {
    width: 100%;
  }
}
.rf-inbox-toolbar-right {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.rf-inbox-campaign-select {
  min-height: 42px;
  min-width: 190px;
  padding: 0 38px 0 14px;
  border: 1px solid var(--border, #dfe3ea);
  border-radius: 12px;
  background: var(--surface, #fff);
  color: inherit;
  font: inherit;
}

.rf-campaign-email-activity {
  margin: 22px 0;
}

.rf-campaign-email-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 12px;
  margin-top: 12px;
}

.rf-campaign-email-card {
  display: grid;
  gap: 6px;
  padding: 16px;
  border: 1px solid var(--border, #e2e6ec);
  border-radius: 16px;
  background: var(--surface, #fff);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 160ms ease, transform 160ms ease;
}

.rf-campaign-email-card:hover,
.rf-campaign-email-card.active {
  border-color: var(--primary, #635bff);
  transform: translateY(-1px);
}

.rf-campaign-email-card strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-campaign-email-card span,
.rf-campaign-email-card em,
.rf-inbox-stat-card small {
  color: var(--muted, #667085);
  font-size: 0.82rem;
  font-style: normal;
}

.rf-inbox-card.sent .rf-inbox-card-icon {
  opacity: 0.82;
}

.rf-inbox-card.reply.unread {
  border-color: var(--primary, #635bff);
}

@media (max-width: 760px) {
  .rf-inbox-toolbar-right,
  .rf-inbox-search,
  .rf-inbox-campaign-select {
    width: 100%;
  }
}

/* ==========================================================
   External lead campaign — Sheet personalized pitch
   ========================================================== */

