  display: grid;
  gap: 16px;
  margin: 18px 0;
  padding: 18px;
  border-radius: 22px;
  border: 1px solid rgba(123, 66, 255, .16);
  background:
    radial-gradient(circle at 0 0, rgba(123, 66, 255, .10), transparent 14rem),
    rgba(255, 255, 255, .9);
  box-shadow: 0 14px 34px rgba(35, 18, 80, .05);
}

.external-sheet-pitch-box .external-ai-context {
  margin: 0;
}

.external-sheet-pitch-stats {
  display: inline-flex;
  width: max-content;
  max-width: 100%;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 0 13px;
  border-radius: 999px;
  color: var(--purple);
  background: rgba(123, 66, 255, .09);
  border: 1px solid rgba(123, 66, 255, .12);
  font-size: 12px;
  font-weight: 900;
}

.external-sheet-pitch-stats b {
  color: var(--ink);
  font-size: 16px;
  font-weight: 950;
}

.external-sheet-pitch-stats span {
  color: var(--muted);
  font-weight: 850;
}

.external-message-tabs {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.external-message-tabs button {
  min-height: 38px;
  padding: 0 14px;
  border-radius: 999px;
  border: 1px solid rgba(123, 66, 255, .12);
  background: rgba(255, 255, 255, .78);
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
  cursor: pointer;
  transition: .2s;
}

.external-message-tabs button:hover {
  color: var(--purple);
  border-color: rgba(123, 66, 255, .26);
  transform: translateY(-1px);
}

.external-message-tabs button.active {
  color: #fff;
  border-color: transparent;
  background: var(--grad);
  box-shadow: 0 14px 28px rgba(123, 66, 255, .22);
}

.external-preview-message p,
.external-message-preview p {
  white-space: pre-wrap;
}

@media (max-width: 640px) {
  .external-sheet-pitch-box {
    padding: 15px;
