  background: #f0fdf4;
}

.full-audit-findings > article {
  padding: 16px;
  border: 1px solid #e2e8f0;
  border-radius: 15px;
  background: #fff;
}

.full-audit-findings > article > div {
  margin-bottom: 9px;
  display: flex;
  align-items: center;
  gap: 9px;
}

.full-audit-findings h3 {
  margin: 0;
  color: #0f172a;
  font-size: 14px;
}

.full-audit-findings p {
  margin: 6px 0 0;
  color: #475569;
  font-size: 11.5px;
  line-height: 1.55;
}

.full-audit-findings .recommendation {
  padding: 10px;
  border-radius: 10px;
  color: #14532d;
  background: #f0fdf4;
}

.severity,
.review-status {
  padding: 4px 7px;
  border-radius: 999px;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.severity.critical,
.review-status.fail {
  color: #991b1b;
  background: #fee2e2;
}

.severity.high {
  color: #9a3412;
  background: #ffedd5;
}

.severity.medium,
.review-status.warning {
  color: #92400e;
  background: #fef3c7;
}

.severity.low,
.review-status.pass {
  color: #166534;
  background: #dcfce7;
}

.audit-review-table {
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  overflow: hidden;
}

.audit-review-table > div {
  padding: 12px 14px;
  display: grid;
  grid-template-columns: 68px 150px minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  border-bottom: 1px solid #e2e8f0;
}

.audit-review-table > div:last-child {
  border-bottom: 0;
}

.audit-review-table b {
  color: #1e293b;
  font-size: 11px;
}

.audit-review-table p {
  margin: 0;
  color: #64748b;
  font-size: 11px;
  line-height: 1.45;
}

.audit-roadmap > article {
  padding: 15px;
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  gap: 12px;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
}

.audit-roadmap small {
  color: #16a34a;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.audit-drawer-footer {
  min-height: 78px;
  padding: 13px 20px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  border-top: 1px solid #e2e8f0;
  background: rgba(255, 255, 255, 0.97);
  box-shadow: 0 -12px 28px rgba(15, 23, 42, 0.04);
}

.audit-secondary-action,
.audit-primary-action {
  min-height: 48px;
  padding: 11px 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border-radius: 13px;
  font: inherit;
  font-size: 12px;
  font-weight: 900;
  cursor: pointer;
  transition: transform 160ms ease, box-shadow 160ms ease, opacity 160ms ease;
}

.audit-secondary-action {
  border: 1px solid #cbd5e1;
  color: #334155;
  background: #fff;
}

.audit-primary-action {
  border: 1px solid #15803d;
  color: #fff;
  background: linear-gradient(135deg, #16a34a, #15803d);
  box-shadow: 0 10px 24px rgba(22, 163, 74, 0.2);
}

.audit-secondary-action:hover:not(:disabled),
.audit-primary-action:hover:not(:disabled) {
  transform: translateY(-1px);
}

.audit-secondary-action:disabled,
.audit-primary-action:disabled {
  opacity: 0.55;
  cursor: wait;
}

.audit-report-loader,
.audit-failed-state {
  min-height: 440px;
  display: grid;
  place-content: center;
  justify-items: center;
  text-align: center;
}

.audit-report-loader h3,
.audit-failed-state h3 {
  margin: 20px 0 7px;
  color: #0f172a;
  font-size: 20px;
}

.audit-report-loader p,
.audit-failed-state p {
  max-width: 430px;
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.55;
}

.audit-loader-orbit {
  width: 64px;
  height: 64px;
  position: relative;
  border: 2px solid #dcfce7;
  border-radius: 50%;
}

.audit-loader-orbit::before,
.audit-loader-orbit::after {
  content: "";
  position: absolute;
  inset: 8px;
  border: 2px solid transparent;
  border-top-color: #16a34a;
  border-radius: 50%;
  animation: auditSpin 900ms linear infinite;
}

.audit-loader-orbit::after {
  inset: 18px;
  border-top-color: #86efac;
  animation-duration: 620ms;
  animation-direction: reverse;
}

.audit-loader-orbit > span {
  position: absolute;
  inset: 27px;
  border-radius: 50%;
  background: #16a34a;
  box-shadow: 0 0 18px rgba(22, 163, 74, 0.45);
}

.audit-loader-lines {
  width: min(420px, 78vw);
  margin-top: 28px;
  display: grid;
  gap: 9px;
}

.audit-loader-lines i {
  height: 10px;
  border-radius: 999px;
  background: linear-gradient(90deg, #e2e8f0 0%, #f8fafc 48%, #e2e8f0 100%);
  background-size: 220% 100%;
  animation: liveSkeleton 1.3s linear infinite;
}

.audit-loader-lines i:nth-child(2) {
  width: 86%;
}

.audit-loader-lines i:nth-child(3) {
  width: 72%;
}

.audit-loader-lines i:nth-child(4) {
  width: 91%;
}

.audit-failed-state > span {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  color: #991b1b;
  background: #fee2e2;
  font-size: 22px;
  font-weight: 900;
}

@keyframes auditBackdropIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes auditDrawerIn {
  from { opacity: 0; transform: translateX(38px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes auditSpin {
  to { transform: rotate(360deg); }
}

@media (max-width: 760px) {
  .lead-audit-drawer {
    width: 100vw;
  }

  .audit-drawer-header,
  .audit-action-bar,
  .audit-report-scroll,
  .audit-drawer-footer {
    padding-left: 15px;
    padding-right: 15px;
  }

  .audit-action-bar {
    align-items: stretch;
    flex-direction: column;
  }

  .audit-download-button {
    width: 100%;
  }

  .audit-drawer-footer,
  .mini-audit-snapshot,
  .audit-highlight-grid,
  .competitor-report-grid {
    grid-template-columns: 1fr;
  }

  .mini-audit-snapshot > div:last-child {
    grid-column: auto;
  }

  .audit-review-table > div {
    grid-template-columns: 68px minmax(0, 1fr);
  }

  .audit-review-table p {
    grid-column: 1 / -1;
  }
}

@media print {
  .audit-drawer-header,
  .audit-kind-tabs,
  .audit-action-bar,
  .audit-drawer-footer,
  .audit-close-button {
    display: none !important;
  }

  .audit-drawer-backdrop,
  .lead-audit-drawer,
  .audit-report-scroll {
    position: static;
    width: auto;
    height: auto;
    overflow: visible;
    padding: 0;
    background: #fff;
    box-shadow: none;
  }

  .mini-audit-sheet,
  .expanded-audit-sheet {
    width: 100%;
    border: 0;
    border-radius: 0;
    box-shadow: none;
  }
}
