    grid-template-columns: 1fr;
  }

  .mini-audit-snapshot > div:last-child {
    grid-column: auto;
  }

  .audit-review-table > div {
    grid-template-columns: 68px minmax(0, 1fr);
  }

  .audit-review-table p {
    grid-column: 1 / -1;
  }
}

@media print {
  .audit-drawer-header,
  .audit-kind-tabs,
  .audit-action-bar,
  .audit-drawer-footer,
  .audit-close-button {
    display: none !important;
  }

  .audit-drawer-backdrop,
  .lead-audit-drawer,
  .audit-report-scroll {
    position: static;
    width: auto;
    height: auto;
    overflow: visible;
    padding: 0;
    background: #fff;
    box-shadow: none;
  }

  .mini-audit-sheet,
  .expanded-audit-sheet {
    width: 100%;
    border: 0;
    border-radius: 0;
    box-shadow: none;
  }
}

/* Vonage call workspace */
.lead-action-row { display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-top:14px; }
.lead-call-button,.mini-audit-button { min-height:42px; border-radius:13px; font-weight:800; }
.lead-call-button { display:flex; align-items:center; justify-content:center; gap:8px; border:1px solid rgba(112,54,225,.2); background:linear-gradient(135deg,#25123f,#6f2be8); color:#fff; box-shadow:0 10px 24px rgba(79,33,157,.2); cursor:pointer; }
.lead-call-button:hover:not(:disabled){ transform:translateY(-1px); box-shadow:0 14px 30px rgba(79,33,157,.27); }
.lead-call-button:disabled{ opacity:.45; cursor:not-allowed; }
.call-drawer { width:min(650px,100vw); height:100%; margin-left:auto; overflow:auto; padding:26px; background:linear-gradient(180deg,#fff 0%,#fbf8ff 100%); box-shadow:-30px 0 80px rgba(33,13,68,.2); }
.call-drawer-header{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;padding-bottom:20px;border-bottom:1px solid rgba(96,62,147,.12)}
.call-drawer-header h2{margin:7px 0 5px;font-size:28px;letter-spacing:-.035em}.call-drawer-header p{margin:0;color:#776d84}
.call-status-panel{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:14px;align-items:center;margin:22px 0;padding:18px;border:1px solid rgba(111,43,232,.14);border-radius:20px;background:radial-gradient(circle at 90% 0,rgba(239,59,164,.12),transparent 35%),#fff;box-shadow:0 16px 45px rgba(62,25,111,.08)}
.call-status-panel small,.call-status-panel span{display:block;color:#7b7188}.call-status-panel strong{display:block;margin:3px 0;text-transform:capitalize;font-size:18px}.call-status-dot{width:14px;height:14px;border-radius:50%;background:#8f7ba4;box-shadow:0 0 0 7px rgba(143,123,164,.1)}.call-status-dot.started,.call-status-dot.ringing,.call-status-dot.connecting{background:#7c2cf0;box-shadow:0 0 0 7px rgba(124,44,240,.13);animation:live-pulse 1.2s infinite}.call-status-dot.answered{background:#12a879}.call-status-dot.failed,.call-status-dot.rejected,.call-status-dot.busy{background:#db3e62}
.call-audit-preview,.call-script-card,.call-outcome-card{margin-top:16px;padding:20px;border:1px solid rgba(100,67,150,.12);border-radius:20px;background:#fff;box-shadow:0 12px 36px rgba(61,30,105,.06)}
.call-audit-preview{display:flex;align-items:center;justify-content:space-between;gap:18px}.call-audit-preview h3,.call-script-card h3{margin:7px 0}.call-audit-preview p,.call-script-card p{margin:0;color:#776d84;line-height:1.6}.call-audit-preview .mini-audit-button{width:auto;min-width:170px;margin:0}
.call-outcome-card{display:grid;gap:14px}.call-outcome-card label span{display:block;margin-bottom:7px;font-size:12px;font-weight:800;color:#5f536d}.call-outcome-card select,.call-outcome-card textarea{width:100%;border:1px solid rgba(100,67,150,.16);border-radius:13px;background:#fff;padding:12px;font:inherit;color:#21172e}.call-outcome-card textarea{min-height:110px;resize:vertical}
@media(max-width:700px){.lead-action-row{grid-template-columns:1fr}.call-status-panel{grid-template-columns:auto 1fr}.call-now-button{grid-column:1/-1;width:100%}.call-audit-preview{align-items:stretch;flex-direction:column}.call-audit-preview .mini-audit-button{width:100%}}

