.rf-telnyx-dialer {
  display: grid;
  gap: 16px;
  margin-top: 20px;
}

.rf-telnyx-dialer audio {
  display: none;
}

.rf-telnyx-dialer .flex-wrap {
  flex-wrap: wrap;
}

.rf-telnyx-dialer .btn.danger {
  background: #dc2626;
  border-color: #dc2626;
  color: #fff;
