/* =========================================================
   Telnyx Dialer
   Safe to paste into the main application stylesheet.
   All component-specific rules are scoped to .rf-telnyx-dialer.
   ========================================================= */

.rf-telnyx-dialer {
  --rf-dialer-bg: #ffffff;
  --rf-dialer-border: #e2e8f0;
  --rf-dialer-text: #0f172a;
  --rf-dialer-muted: #64748b;
  --rf-dialer-primary: #2563eb;
  --rf-dialer-primary-hover: #1d4ed8;
  --rf-dialer-danger: #dc2626;
  --rf-dialer-danger-hover: #b91c1c;
  --rf-dialer-success: #15803d;
  --rf-dialer-success-bg: #f0fdf4;
  --rf-dialer-success-border: #bbf7d0;
  --rf-dialer-error: #b91c1c;
  --rf-dialer-error-bg: #fef2f2;
  --rf-dialer-error-border: #fecaca;
  --rf-dialer-radius: 18px;

  width: 100%;
  box-sizing: border-box;
  padding: 22px;
  color: var(--rf-dialer-text);
  background: var(--rf-dialer-bg);
  border: 1px solid var(--rf-dialer-border);
  border-radius: var(--rf-dialer-radius);
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.08);
}

.rf-telnyx-dialer,
.rf-telnyx-dialer * {
  box-sizing: border-box;
}

.rf-telnyx-dialer > audio {
  display: none;
}

.rf-telnyx-dialer .section-title-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.rf-telnyx-dialer .section-title-row > div {
  min-width: 0;
}

.rf-telnyx-dialer .eyebrow {
  display: inline-block;
  margin-bottom: 7px;
  color: var(--rf-dialer-primary);
  font-size: 0.72rem;
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.rf-telnyx-dialer h3 {
  margin: 0;
  overflow-wrap: anywhere;
  color: var(--rf-dialer-text);
  font-size: clamp(1.15rem, 2vw, 1.5rem);
  font-weight: 750;
  line-height: 1.25;
}

.rf-telnyx-dialer p {
  margin: 8px 0 0;
  color: var(--rf-dialer-muted);
  line-height: 1.55;
}

.rf-telnyx-dialer p b {
  color: var(--rf-dialer-text);
  font-weight: 700;
}

.rf-telnyx-dialer .text-xs {
  font-size: 0.78rem;
}

.rf-telnyx-dialer .text-muted {
  color: var(--rf-dialer-muted);
}

.rf-telnyx-dialer .badge {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 30px;
  padding: 6px 11px;
  border: 1px solid transparent;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 800;
  line-height: 1;
  letter-spacing: 0.025em;
  white-space: nowrap;
}

.rf-telnyx-dialer .badge-green {
  color: #166534;
  background: #dcfce7;
  border-color: #bbf7d0;
}

.rf-telnyx-dialer .badge-amber {
  color: #92400e;
  background: #fef3c7;
  border-color: #fde68a;
}

.rf-telnyx-dialer .badge-red {
  color: #991b1b;
  background: #fee2e2;
  border-color: #fecaca;
}

.rf-telnyx-dialer .badge-gray {
  color: #475569;
  background: #f1f5f9;
  border-color: #e2e8f0;
}

.rf-telnyx-dialer .error-banner,
.rf-telnyx-dialer .success-banner {
  display: block;
  width: 100%;
  margin: 16px 0 0;
  padding: 12px 14px;
  border: 1px solid;
  border-radius: 12px;
  font-size: 0.88rem;
  font-weight: 600;
  line-height: 1.5;
}

.rf-telnyx-dialer .error-banner {
  color: var(--rf-dialer-error);
  background: var(--rf-dialer-error-bg);
  border-color: var(--rf-dialer-error-border);
}

.rf-telnyx-dialer .success-banner {
  color: var(--rf-dialer-success);
  background: var(--rf-dialer-success-bg);
  border-color: var(--rf-dialer-success-border);
}

.rf-telnyx-dialer .rf-telnyx-result {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 16px;
  padding: 12px 14px;
  color: #334155;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
}

.rf-telnyx-dialer .rf-telnyx-result span {
  color: var(--rf-dialer-muted);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.rf-telnyx-dialer .rf-telnyx-result b {
  color: var(--rf-dialer-text);
  font-size: 0.9rem;
}

.rf-telnyx-dialer .rf-assignment-option {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-top: 18px;
  padding: 13px 14px;
  color: #334155;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  font-size: 0.84rem;
  font-weight: 600;
  line-height: 1.5;
  cursor: pointer;
  user-select: none;
}

.rf-telnyx-dialer .rf-assignment-option:has(input:focus-visible) {
  border-color: #60a5fa;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.14);
}

.rf-telnyx-dialer .rf-assignment-option input {
  flex: 0 0 auto;
  width: 17px;
  height: 17px;
  margin: 2px 0 0;
  accent-color: var(--rf-dialer-primary);
  cursor: pointer;
}

.rf-telnyx-dialer .rf-assignment-option:has(input:disabled) {
  cursor: not-allowed;
  opacity: 0.66;
}

.rf-telnyx-dialer .flex {
  display: flex;
}

.rf-telnyx-dialer .flex-gap {
  gap: 10px;
}

.rf-telnyx-dialer .flex-wrap {
  flex-wrap: wrap;
}

.rf-telnyx-dialer .mt16 {
  margin-top: 16px;
}

.rf-telnyx-dialer .btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 42px;
  padding: 10px 17px;
  border: 1px solid transparent;
  border-radius: 11px;
  font-family: inherit;
  font-size: 0.88rem;
  font-weight: 750;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  transition:
    transform 140ms ease,
    box-shadow 140ms ease,
    background-color 140ms ease,
    border-color 140ms ease,
    color 140ms ease;
}

.rf-telnyx-dialer .btn:hover:not(:disabled) {
  transform: translateY(-1px);
}

.rf-telnyx-dialer .btn:active:not(:disabled) {
  transform: translateY(0);
}

.rf-telnyx-dialer .btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.2);
}

.rf-telnyx-dialer .btn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
  transform: none;
  box-shadow: none;
}

.rf-telnyx-dialer .btn.primary {
  color: #ffffff;
  background: var(--rf-dialer-primary);
  border-color: var(--rf-dialer-primary);
  box-shadow: 0 7px 18px rgba(37, 99, 235, 0.2);
}

.rf-telnyx-dialer .btn.primary:hover:not(:disabled) {
  background: var(--rf-dialer-primary-hover);
  border-color: var(--rf-dialer-primary-hover);
  box-shadow: 0 9px 22px rgba(37, 99, 235, 0.26);
}

.rf-telnyx-dialer .btn.light {
  color: #1e293b;
  background: #ffffff;
  border-color: #cbd5e1;
}

.rf-telnyx-dialer .btn.light:hover:not(:disabled) {
  background: #f8fafc;
  border-color: #94a3b8;
}

.rf-telnyx-dialer .btn.danger {
  color: #ffffff;
  background: var(--rf-dialer-danger);
  border-color: var(--rf-dialer-danger);
  box-shadow: 0 7px 18px rgba(220, 38, 38, 0.18);
}

.rf-telnyx-dialer .btn.danger:hover:not(:disabled) {
  background: var(--rf-dialer-danger-hover);
  border-color: var(--rf-dialer-danger-hover);
}

@media (max-width: 640px) {
  .rf-telnyx-dialer {
    padding: 17px;
    border-radius: 14px;
  }

  .rf-telnyx-dialer .section-title-row {
    flex-direction: column;
    gap: 12px;
  }

  .rf-telnyx-dialer .badge {
    align-self: flex-start;
  }

  .rf-telnyx-dialer .flex.mt16 {
    display: grid;
    grid-template-columns: 1fr;
  }

  .rf-telnyx-dialer .btn {
    width: 100%;
  }

  .rf-telnyx-dialer .rf-telnyx-result {
    align-items: flex-start;
    flex-direction: column;
    gap: 4px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .rf-telnyx-dialer .btn {
    transition: none;
  }
}

/* Optional dark-mode support. Remove this block if your app handles dark mode globally. */
@media (prefers-color-scheme: dark) {
  .rf-telnyx-dialer {
    --rf-dialer-bg: #0f172a;
    --rf-dialer-border: #273449;
    --rf-dialer-text: #f8fafc;
    --rf-dialer-muted: #94a3b8;

    box-shadow: 0 14px 34px rgba(0, 0, 0, 0.24);
  }

  .rf-telnyx-dialer .rf-telnyx-result,
  .rf-telnyx-dialer .rf-assignment-option {
    color: #cbd5e1;
    background: #111c31;
    border-color: #334155;
  }

  .rf-telnyx-dialer .btn.light {
    color: #e2e8f0;
    background: #172033;
    border-color: #475569;
  }

  .rf-telnyx-dialer .btn.light:hover:not(:disabled) {
    background: #1e293b;
    border-color: #64748b;
  }

  .rf-telnyx-dialer .badge-gray {
    color: #cbd5e1;
    background: #1e293b;
    border-color: #334155;
  }
}
.rf-call-workspace {
  --rf-page-text: #171326;
  --rf-page-muted: #6f6980;
  --rf-page-border: #e8e4f1;
  --rf-page-soft: #f8f7fc;
  --rf-page-card: rgba(255, 255, 255, 0.96);
  --rf-page-purple: #7c3aed;
  --rf-page-purple-dark: #5b21b6;
  --rf-page-pink: #db2777;
  --rf-page-success: #15803d;
  --rf-page-danger: #b42318;
  --rf-page-shadow: 0 18px 50px rgba(47, 26, 78, 0.08);

  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
  padding: 24px clamp(16px, 2.4vw, 34px) 48px;
  color: var(--rf-page-text);
}

.rf-call-workspace,
.rf-call-workspace * {
  box-sizing: border-box;
}

.rf-call-workspace > audio {
  display: none;
}

.rf-call-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 22px;
  padding: 22px 24px;
  background:
    radial-gradient(circle at 92% 10%, rgba(236, 72, 153, 0.12), transparent 34%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(249, 246, 255, 0.98));
  border: 1px solid var(--rf-page-border);
  border-radius: 22px;
  box-shadow: var(--rf-page-shadow);
}

.rf-call-header__identity {
  min-width: 0;
}

.rf-call-eyebrow,
.rf-mini-audit-eyebrow {
  margin: 0 0 7px;
  color: var(--rf-page-purple);
  font-size: 0.72rem;
  font-weight: 850;
  letter-spacing: 0.1em;
  line-height: 1.2;
  text-transform: uppercase;
}

.rf-call-header h1,
.rf-call-outcome-card h2,
.rf-call-history-card h2,
.rf-call-information-panel h2,
.rf-mini-audit-panel h2,
.rf-mini-audit-panel h3 {
  color: var(--rf-page-text);
  letter-spacing: -0.025em;
}

.rf-call-header h1 {
  margin: 0;
  font-size: clamp(1.55rem, 3vw, 2.25rem);
  line-height: 1.15;
}

.rf-call-header__identity > div > p:last-child {
  margin: 9px 0 0;
  color: var(--rf-page-muted);
  overflow-wrap: anywhere;
  line-height: 1.5;
}

.rf-call-header__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 10px;
}

.rf-call-header__actions button,
.rf-call-empty-state button,
.rf-call-outcome-card > button {
  appearance: none;
  min-height: 42px;
  padding: 10px 16px;
  border: 1px solid var(--rf-page-border);
  border-radius: 11px;
  color: #43385a;
  background: #fff;
  font: inherit;
  font-size: 0.86rem;
  font-weight: 750;
  cursor: pointer;
  transition: transform 140ms ease, box-shadow 140ms ease, border-color 140ms ease;
}

.rf-call-header__actions button:hover:not(:disabled),
.rf-call-empty-state button:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: #c4b5fd;
  box-shadow: 0 10px 24px rgba(91, 33, 182, 0.1);
}

.rf-call-header__actions button:last-child {
  color: #fff;
  border-color: transparent;
  background: linear-gradient(135deg, var(--rf-page-purple), var(--rf-page-pink));
  box-shadow: 0 10px 24px rgba(124, 58, 237, 0.22);
}

.rf-call-header__actions button:disabled,
.rf-call-outcome-card > button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.rf-workspace-alert {
  margin: 0 0 18px;
  padding: 13px 15px;
  border: 1px solid;
  border-radius: 13px;
  font-size: 0.9rem;
  font-weight: 650;
  line-height: 1.5;
}

.rf-workspace-alert--error {
  color: #9f1239;
  background: #fff1f2;
  border-color: #fecdd3;
}

.rf-workspace-alert--success {
  color: #166534;
  background: #f0fdf4;
  border-color: #bbf7d0;
}

.rf-call-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.42fr) minmax(330px, 0.78fr);
  align-items: start;
  gap: 22px;
}

.rf-call-layout__primary,
.rf-call-layout__secondary {
  display: grid;
  min-width: 0;
  gap: 22px;
}

.rf-call-outcome-card,
.rf-call-history-card,
.rf-call-information-panel,
.rf-mini-audit-panel,
.rf-call-empty-state {
  min-width: 0;
  padding: 22px;
  background: var(--rf-page-card);
  border: 1px solid var(--rf-page-border);
  border-radius: 20px;
  box-shadow: var(--rf-page-shadow);
}

.rf-call-outcome-card {
  display: grid;
  grid-template-columns: minmax(150px, 0.8fr) minmax(200px, 1.35fr) minmax(180px, 0.95fr) auto;
  align-items: end;
  gap: 14px;
}

.rf-call-outcome-card > div:first-child {
  grid-column: 1 / -1;
  margin-bottom: 2px;
}

.rf-call-outcome-card h2,
.rf-call-history-card h2,
.rf-call-information-panel h2 {
  margin: 0;
  font-size: 1.25rem;
  line-height: 1.25;
}

.rf-call-outcome-card label {
  display: grid;
  min-width: 0;
  gap: 7px;
}

.rf-call-outcome-card label > span {
  color: #554d65;
  font-size: 0.78rem;
  font-weight: 750;
}

.rf-call-outcome-card select,
.rf-call-outcome-card textarea,
.rf-call-outcome-card input {
  width: 100%;
  min-height: 44px;
  padding: 10px 12px;
  color: var(--rf-page-text);
  background: #fff;
  border: 1px solid #ddd7e8;
  border-radius: 11px;
  outline: none;
  font: inherit;
  font-size: 0.88rem;
  transition: border-color 140ms ease, box-shadow 140ms ease;
}

.rf-call-outcome-card textarea {
  min-height: 76px;
  resize: vertical;
}

.rf-call-outcome-card select:focus,
.rf-call-outcome-card textarea:focus,
.rf-call-outcome-card input:focus {
  border-color: #a78bfa;
  box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.1);
}

.rf-call-outcome-card > button {
  min-height: 44px;
  color: #fff;
  border-color: transparent;
  background: linear-gradient(135deg, var(--rf-page-purple), var(--rf-page-pink));
  box-shadow: 0 10px 22px rgba(124, 58, 237, 0.2);
}

.rf-call-history-card > div:first-child,
.rf-call-information-panel > .rf-call-eyebrow + h2 {
  margin-bottom: 4px;
}

.rf-call-history-card > p {
  margin: 16px 0 0;
  color: var(--rf-page-muted);
  line-height: 1.55;
}

.rf-call-history-list {
  display: grid;
  gap: 10px;
  margin-top: 16px;
}

.rf-call-history-list article {
  display: grid;
  grid-template-columns: minmax(120px, 1fr) minmax(150px, 1fr) auto auto;
  align-items: center;
  gap: 12px;
  padding: 13px 14px;
  background: var(--rf-page-soft);
  border: 1px solid var(--rf-page-border);
  border-radius: 12px;
}

.rf-call-history-list article strong {
  color: var(--rf-page-text);
}

.rf-call-history-list article span {
  color: var(--rf-page-muted);
  font-size: 0.82rem;
}

.rf-call-history-list article a {
  color: var(--rf-page-purple);
  font-size: 0.82rem;
  font-weight: 750;
  text-decoration: none;
}

.rf-call-information-panel dl {
  display: grid;
  grid-template-columns: minmax(90px, auto) minmax(0, 1fr);
  gap: 0;
  margin: 17px 0 0;
  overflow: hidden;
  border: 1px solid var(--rf-page-border);
  border-radius: 14px;
}

.rf-call-information-panel dt,
.rf-call-information-panel dd {
  margin: 0;
  padding: 11px 13px;
  border-bottom: 1px solid var(--rf-page-border);
}

.rf-call-information-panel dt {
  color: var(--rf-page-muted);
  background: #faf9fd;
  font-size: 0.78rem;
  font-weight: 750;
}

.rf-call-information-panel dd {
  color: var(--rf-page-text);
  font-size: 0.84rem;
  font-weight: 650;
  overflow-wrap: anywhere;
}

.rf-call-information-panel dt:nth-last-of-type(1),
.rf-call-information-panel dd:nth-last-of-type(1) {
  border-bottom: 0;
}

.rf-call-empty-state {
  display: grid;
  justify-items: center;
  gap: 10px;
  padding-block: 60px;
  text-align: center;
}

.rf-call-empty-state h1,
.rf-call-empty-state p {
  margin: 0;
}

.rf-call-empty-state p {
  max-width: 520px;
  color: var(--rf-page-muted);
  line-height: 1.55;
}

/* =========================================================
   Mini audit
   ========================================================= */

.rf-mini-audit-panel {
  display: grid;
  gap: 18px;
  overflow: hidden;
}

.rf-mini-audit-panel__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.rf-mini-audit-panel__header h2 {
  margin: 0;
  font-size: 1.35rem;
  line-height: 1.2;
}

.rf-mini-audit-panel__header > div > p:last-child {
  margin: 7px 0 0;
  color: var(--rf-page-muted);
  font-size: 0.86rem;
  line-height: 1.5;
}

.rf-mini-audit-status {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 112px;
  padding: 8px 10px;
  border: 1px solid var(--rf-page-border);
  border-radius: 999px;
  background: #faf9fd;
}

.rf-mini-audit-status > span {
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: #94a3b8;
}

.rf-mini-audit-status > div {
  display: grid;
  gap: 2px;
}

.rf-mini-audit-status strong {
  font-size: 0.72rem;
  line-height: 1;
}

.rf-mini-audit-status small {
  color: var(--rf-page-muted);
  font-size: 0.66rem;
}

.rf-mini-audit-status--completed {
  color: #166534;
  background: #f0fdf4;
  border-color: #bbf7d0;
}

.rf-mini-audit-status--completed > span {
  background: #22c55e;
}

.rf-mini-audit-status--processing {
  color: #92400e;
  background: #fffbeb;
  border-color: #fde68a;
}

.rf-mini-audit-status--processing > span {
  background: #f59e0b;
  box-shadow: 0 0 0 5px rgba(245, 158, 11, 0.12);
}

.rf-mini-audit-status--failed {
  color: #991b1b;
  background: #fef2f2;
  border-color: #fecaca;
}

.rf-mini-audit-status--failed > span {
  background: #ef4444;
}

.rf-mini-audit-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px;
  color: #fff;
  background:
    radial-gradient(circle at 85% 0%, rgba(236, 72, 153, 0.42), transparent 42%),
    linear-gradient(135deg, #28133f, #4c1d95);
  border-radius: 15px;
}

.rf-mini-audit-banner__brand {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
}

.rf-mini-audit-banner__brand > span {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  border-radius: 12px;
  color: #fff;
  background: linear-gradient(135deg, #a855f7, #ec4899);
  font-size: 0.76rem;
  font-weight: 850;
}

.rf-mini-audit-banner__brand > div,
.rf-mini-audit-banner__date {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.rf-mini-audit-banner small {
  color: rgba(255, 255, 255, 0.68);
  font-size: 0.62rem;
  font-weight: 750;
  letter-spacing: 0.05em;
}

.rf-mini-audit-banner strong {
  overflow-wrap: anywhere;
  font-size: 0.76rem;
  line-height: 1.25;
}

.rf-mini-audit-banner__date {
  flex: 0 0 auto;
  text-align: right;
}

.rf-mini-audit-section {
  display: grid;
  gap: 13px;
}

.rf-mini-audit-section__header {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
}

.rf-mini-audit-section__header > span {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  color: var(--rf-page-purple);
  background: #f3e8ff;
  font-size: 0.72rem;
  font-weight: 850;
}

.rf-mini-audit-section__header h3,
.rf-mini-audit-section__header p {
  margin: 0;
}

.rf-mini-audit-section__header h3 {
  font-size: 1rem;
}

.rf-mini-audit-section__header p {
  margin-top: 3px;
  color: var(--rf-page-muted);
  font-size: 0.76rem;
  line-height: 1.4;
}

.rf-mini-audit-section__header > b {
  color: var(--rf-page-muted);
  font-size: 0.72rem;
}

.rf-mini-audit-snapshot {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--rf-page-border);
  border-radius: 14px;
}

.rf-mini-audit-snapshot-row {
  display: grid;
  align-content: start;
  min-width: 0;
  gap: 4px;
  padding: 11px 12px;
  background: #fff;
  border-right: 1px solid var(--rf-page-border);
  border-bottom: 1px solid var(--rf-page-border);
}

.rf-mini-audit-snapshot-row:nth-child(even) {
  border-right: 0;
}

.rf-mini-audit-snapshot-row--wide {
  grid-column: 1 / -1;
  border-right: 0;
}

.rf-mini-audit-snapshot-row small {
  color: var(--rf-page-muted);
  font-size: 0.66rem;
  font-weight: 750;
  text-transform: uppercase;
  letter-spacing: 0.045em;
}

.rf-mini-audit-snapshot-row strong,
.rf-mini-audit-snapshot-row a {
  color: var(--rf-page-text);
  font-size: 0.8rem;
  font-weight: 700;
  line-height: 1.4;
  overflow-wrap: anywhere;
  text-decoration: none;
}

.rf-mini-audit-snapshot-row a:hover {
  color: var(--rf-page-purple);
}

.rf-mini-audit-issues {
  display: grid;
  gap: 10px;
}

.rf-mini-audit-issue {
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--rf-page-border);
  border-radius: 13px;
  transition: border-color 140ms ease, box-shadow 140ms ease;
}

.rf-mini-audit-issue.is-expanded {
  border-color: #c4b5fd;
  box-shadow: 0 12px 28px rgba(91, 33, 182, 0.08);
}

.rf-mini-audit-issue__summary {
  appearance: none;
  display: grid;
  grid-template-columns: 35px minmax(0, 1fr) auto 20px;
  align-items: center;
  width: 100%;
  gap: 10px;
  padding: 12px;
  color: var(--rf-page-text);
  background: #fff;
  border: 0;
  text-align: left;
  font: inherit;
  cursor: pointer;
}

.rf-mini-audit-issue__number {
  display: grid;
  place-items: center;
  width: 35px;
  height: 35px;
  border-radius: 10px;
  color: #fff;
  background: linear-gradient(135deg, var(--rf-page-purple), var(--rf-page-pink));
  font-size: 0.72rem;
  font-weight: 850;
}

.rf-mini-audit-issue__summary > div {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.rf-mini-audit-issue__summary small {
  color: var(--rf-page-muted);
  font-size: 0.64rem;
  font-weight: 750;
  text-transform: uppercase;
  letter-spacing: 0.045em;
}

.rf-mini-audit-issue__summary strong {
  font-size: 0.8rem;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.rf-mini-audit-severity {
  padding: 5px 8px;
  border-radius: 999px;
  font-size: 0.64rem;
  font-weight: 800;
  white-space: nowrap;
}

.rf-mini-audit-severity--high {
  color: #9f1239;
  background: #ffe4e6;
}

.rf-mini-audit-severity--medium {
  color: #92400e;
  background: #fef3c7;
}

.rf-mini-audit-severity--low {
  color: #166534;
  background: #dcfce7;
}

.rf-mini-audit-issue__content {
  display: none;
  gap: 11px;
  padding: 0 13px 13px 58px;
}

.rf-mini-audit-issue.is-expanded .rf-mini-audit-issue__content {
  display: grid;
}

.rf-mini-audit-issue__content > div {
  padding: 11px 12px;
  background: #faf9fd;
  border: 1px solid var(--rf-page-border);
  border-radius: 10px;
}

.rf-mini-audit-issue__content small,
.rf-mini-audit-evidence small {
  color: var(--rf-page-purple);
  font-size: 0.66rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.045em;
}

.rf-mini-audit-issue__content p,
.rf-mini-audit-evidence p {
  margin: 5px 0 0;
  color: #514a60;
  font-size: 0.8rem;
  line-height: 1.5;
  overflow-wrap: anywhere;
}

.rf-mini-audit-source-footer {
  padding: 13px 14px;
  color: #e9ddff;
  background: #241336;
  border-radius: 13px;
}

.rf-mini-audit-source-footer strong,
.rf-mini-audit-source-footer p,
.rf-mini-audit-source-footer span {
  display: block;
}

.rf-mini-audit-source-footer strong {
  color: #fff;
  font-size: 0.7rem;
  letter-spacing: 0.05em;
}

.rf-mini-audit-source-footer p {
  margin: 6px 0;
  font-size: 0.72rem;
  line-height: 1.5;
}

.rf-mini-audit-source-footer span {
  color: #c4b5fd;
  font-size: 0.7rem;
  font-weight: 750;
}

.rf-mini-audit-downloads,
.rf-mini-audit-actions {
  display: grid;
  gap: 10px;
}

.rf-mini-audit-downloads {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.rf-mini-audit-actions {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.rf-mini-audit-download-button,
.rf-mini-audit-action {
  appearance: none;
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 10px;
  padding: 11px;
  color: var(--rf-page-text);
  background: #fff;
  border: 1px solid var(--rf-page-border);
  border-radius: 12px;
  text-align: left;
  text-decoration: none;
  font: inherit;
  cursor: pointer;
  transition: transform 140ms ease, border-color 140ms ease, box-shadow 140ms ease;
}

.rf-mini-audit-download-button:hover:not(:disabled),
.rf-mini-audit-action:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: #c4b5fd;
  box-shadow: 0 10px 22px rgba(91, 33, 182, 0.08);
}

.rf-mini-audit-download-button > span,
.rf-mini-audit-action > span {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  color: var(--rf-page-purple);
  background: #f3e8ff;
  border-radius: 10px;
  font-size: 0.66rem;
  font-weight: 850;
}

.rf-mini-audit-download-button > div,
.rf-mini-audit-action > div {
  display: grid;
  min-width: 0;
  gap: 2px;
}

.rf-mini-audit-download-button strong,
.rf-mini-audit-action strong {
  font-size: 0.75rem;
  line-height: 1.3;
}

.rf-mini-audit-download-button small,
.rf-mini-audit-action small {
  color: var(--rf-page-muted);
  font-size: 0.64rem;
  line-height: 1.3;
}

.rf-mini-audit-download-button--primary,
.rf-mini-audit-action--primary {
  color: #fff;
  border-color: transparent;
  background: linear-gradient(135deg, var(--rf-page-purple), var(--rf-page-pink));
}

.rf-mini-audit-download-button--primary > span,
.rf-mini-audit-action--primary > span {
  color: #fff;
  background: rgba(255, 255, 255, 0.16);
}

.rf-mini-audit-download-button--primary small,
.rf-mini-audit-action--primary small {
  color: rgba(255, 255, 255, 0.74);
}

.rf-mini-audit-download-button--disabled,
.rf-mini-audit-download-button:disabled,
.rf-mini-audit-action:disabled {
  cursor: not-allowed;
  opacity: 0.52;
}

.rf-mini-audit-progress {
  display: grid;
  justify-items: center;
  gap: 14px;
  padding: 24px 16px;
  text-align: center;
  background: linear-gradient(145deg, #faf7ff, #fff);
  border: 1px solid #e9d5ff;
  border-radius: 15px;
}

.rf-mini-audit-progress__spinner {
  position: relative;
  display: grid;
  place-items: center;
  width: 62px;
  height: 62px;
}

.rf-mini-audit-progress__spinner > span {
  position: absolute;
  inset: 0;
  border: 3px solid #e9d5ff;
  border-top-color: var(--rf-page-purple);
  border-radius: 999px;
  animation: rf-mini-audit-spin 0.9s linear infinite;
}

.rf-mini-audit-progress__spinner > b {
  color: var(--rf-page-purple);
  font-size: 0.75rem;
}

.rf-mini-audit-progress__content h3,
.rf-mini-audit-progress__content p {
  margin: 0;
}

.rf-mini-audit-progress__content p:last-child {
  margin-top: 6px;
  color: var(--rf-page-muted);
  font-size: 0.8rem;
  line-height: 1.5;
}

.rf-mini-audit-progress__steps {
  display: grid;
  width: 100%;
  gap: 8px;
}

.rf-mini-audit-progress__steps article {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  text-align: left;
  background: #fff;
  border: 1px solid var(--rf-page-border);
  border-radius: 10px;
}

.rf-mini-audit-progress__steps article > span {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  flex: 0 0 auto;
  border-radius: 8px;
  color: var(--rf-page-muted);
  background: var(--rf-page-soft);
  font-size: 0.68rem;
  font-weight: 850;
}

.rf-mini-audit-progress__steps article.is-active {
  border-color: #c4b5fd;
}

.rf-mini-audit-progress__steps article.is-active > span {
  color: #fff;
  background: var(--rf-page-purple);
}

.rf-mini-audit-progress__steps article > div {
  display: grid;
  gap: 2px;
}

.rf-mini-audit-progress__steps strong {
  font-size: 0.75rem;
}

.rf-mini-audit-progress__steps small {
  color: var(--rf-page-muted);
  font-size: 0.65rem;
  line-height: 1.35;
}

.rf-mini-audit-empty {
  display: grid;
  justify-items: center;
  gap: 8px;
  padding: 24px 16px;
  text-align: center;
  background: #faf9fd;
  border: 1px dashed #d8d1e5;
  border-radius: 14px;
}

.rf-mini-audit-empty > span {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  color: var(--rf-page-purple);
  background: #f3e8ff;
  border-radius: 12px;
  font-size: 0.72rem;
  font-weight: 850;
}

.rf-mini-audit-empty strong {
  font-size: 0.9rem;
}

.rf-mini-audit-empty p {
  max-width: 420px;
  margin: 0;
  color: var(--rf-page-muted);
  font-size: 0.78rem;
  line-height: 1.5;
}

.rf-mini-audit-empty--compact {
  padding: 16px;
}

@keyframes rf-mini-audit-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 1180px) {
  .rf-call-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .rf-call-layout__secondary {
    grid-template-columns: minmax(280px, 0.75fr) minmax(0, 1.25fr);
    align-items: start;
  }
}

@media (max-width: 860px) {
  .rf-call-workspace {
    padding: 18px 14px 36px;
  }

  .rf-call-header {
    align-items: flex-start;
    flex-direction: column;
    padding: 18px;
  }

  .rf-call-header__actions {
    width: 100%;
    justify-content: flex-start;
  }

  .rf-call-outcome-card {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rf-call-outcome-card > button {
    width: 100%;
  }

  .rf-call-layout__secondary {
    grid-template-columns: minmax(0, 1fr);
  }

  .rf-mini-audit-actions {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 620px) {
  .rf-call-header,
  .rf-call-outcome-card,
  .rf-call-history-card,
  .rf-call-information-panel,
  .rf-mini-audit-panel,
  .rf-call-empty-state {
    padding: 16px;
    border-radius: 16px;
  }

  .rf-call-header__actions button {
    flex: 1 1 140px;
  }

  .rf-call-outcome-card {
    grid-template-columns: minmax(0, 1fr);
  }

  .rf-call-outcome-card > div:first-child {
    grid-column: auto;
  }

  .rf-call-history-list article {
    grid-template-columns: minmax(0, 1fr);
    gap: 5px;
  }

  .rf-call-information-panel dl {
    grid-template-columns: minmax(0, 1fr);
  }

  .rf-call-information-panel dt {
    padding-bottom: 3px;
    border-bottom: 0;
  }

  .rf-call-information-panel dd {
    padding-top: 3px;
  }

  .rf-mini-audit-panel__header,
  .rf-mini-audit-banner {
    align-items: flex-start;
    flex-direction: column;
  }

  .rf-mini-audit-banner__date {
    text-align: left;
  }

  .rf-mini-audit-snapshot,
  .rf-mini-audit-downloads {
    grid-template-columns: minmax(0, 1fr);
  }

  .rf-mini-audit-snapshot-row,
  .rf-mini-audit-snapshot-row:nth-child(even) {
    border-right: 0;
  }

  .rf-mini-audit-section__header {
    grid-template-columns: 34px minmax(0, 1fr);
  }

  .rf-mini-audit-section__header > b {
    grid-column: 2;
  }

  .rf-mini-audit-issue__summary {
    grid-template-columns: 35px minmax(0, 1fr) 20px;
  }

  .rf-mini-audit-severity {
    grid-column: 2;
    width: fit-content;
  }

  .rf-mini-audit-issue__content {
    padding-left: 13px;
  }
}

/* =========================================================
   REACHFLY — PROFESSIONAL CALL WORKSPACE
   Add this block at the END of your main CSS file
   ========================================================= */

.rf-call-workspace {
  --rf-primary: #6d4aff;
  --rf-primary-dark: #5533e8;
  --rf-primary-soft: #f1edff;
  --rf-primary-border: #dcd3ff;

  --rf-success: #168447;
  --rf-success-soft: #ecfaf2;
  --rf-success-border: #b8e9ca;

  --rf-warning: #b76808;
  --rf-warning-soft: #fff7e8;
  --rf-warning-border: #f3d59b;

  --rf-danger: #c53b4d;
  --rf-danger-dark: #a92839;
  --rf-danger-soft: #fff0f2;
  --rf-danger-border: #f2c2ca;

  --rf-text: #15182a;
  --rf-text-soft: #5f667c;
  --rf-text-muted: #858ba0;

  --rf-border: #e2e5ee;
  --rf-border-strong: #d3d7e3;
  --rf-surface: #ffffff;
  --rf-surface-soft: #f8f9fc;
  --rf-surface-muted: #f2f4f8;

  --rf-shadow-sm:
    0 1px 2px rgba(21, 24, 42, 0.04),
    0 5px 16px rgba(21, 24, 42, 0.04);

  --rf-shadow-md:
    0 8px 30px rgba(40, 35, 80, 0.08),
    0 2px 8px rgba(40, 35, 80, 0.04);

  --rf-shadow-lg:
    0 18px 50px rgba(38, 29, 88, 0.11),
    0 4px 12px rgba(38, 29, 88, 0.05);

  width: 100%;
  max-width: 1580px;
  min-width: 0;
  margin: 0 auto;
  padding: clamp(18px, 2.2vw, 36px);
  color: var(--rf-text);
  line-height: 1.55;
  background:
    radial-gradient(
      circle at top left,
      rgba(109, 74, 255, 0.07),
      transparent 30%
    ),
    linear-gradient(
      180deg,
      #faf9ff 0%,
      #f7f8fc 260px,
      #f7f8fc 100%
    );
}

.rf-call-workspace,
.rf-call-workspace *,
.rf-call-workspace *::before,
.rf-call-workspace *::after {
  box-sizing: border-box;
}

.rf-call-workspace button,
.rf-call-workspace input,
.rf-call-workspace select,
.rf-call-workspace textarea {
  font: inherit;
}

.rf-call-workspace button,
.rf-call-workspace a {
  -webkit-tap-highlight-color: transparent;
}

.rf-call-workspace button:focus-visible,
.rf-call-workspace a:focus-visible,
.rf-call-workspace input:focus-visible,
.rf-call-workspace select:focus-visible,
.rf-call-workspace textarea:focus-visible {
  outline: 3px solid rgba(109, 74, 255, 0.2);
  outline-offset: 2px;
}

/* =========================================================
   PAGE HEADER
   ========================================================= */

.rf-call-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
  padding: 26px 28px;
  border: 1px solid rgba(218, 213, 239, 0.95);
  border-radius: 22px;
  background:
    linear-gradient(
      135deg,
      rgba(255, 255, 255, 0.98),
      rgba(248, 245, 255, 0.98)
    );
  box-shadow: var(--rf-shadow-md);
}

.rf-call-header__identity {
  display: flex;
  align-items: center;
  min-width: 0;
}

.rf-call-header__identity > div {
  min-width: 0;
}

.rf-call-header h1 {
  margin: 4px 0 5px;
  color: var(--rf-text);
  font-size: clamp(1.6rem, 2vw, 2.3rem);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.035em;
  overflow-wrap: anywhere;
}

.rf-call-header__identity > div > p:last-child {
  max-width: 820px;
  margin: 0;
  color: var(--rf-text-soft);
  font-size: 0.95rem;
  overflow-wrap: anywhere;
}

.rf-call-eyebrow,
.rf-call-workspace .eyebrow,
.rf-mini-audit-eyebrow {
  margin: 0;
  color: var(--rf-primary);
  font-size: 0.76rem;
  font-weight: 800;
  line-height: 1.3;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.rf-call-header__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 10px;
  flex: 0 0 auto;
}

.rf-call-header__actions button {
  min-height: 42px;
  padding: 10px 16px;
  border: 1px solid var(--rf-border);
  border-radius: 11px;
  color: #3e4559;
  font-size: 0.9rem;
  font-weight: 700;
  background: #ffffff;
  box-shadow: 0 1px 2px rgba(20, 24, 40, 0.03);
  cursor: pointer;
  transition:
    border-color 160ms ease,
    color 160ms ease,
    background-color 160ms ease,
    transform 160ms ease,
    box-shadow 160ms ease;
}

.rf-call-header__actions button:hover:not(:disabled) {
  color: var(--rf-primary-dark);
  border-color: var(--rf-primary-border);
  background: var(--rf-primary-soft);
  box-shadow: 0 6px 16px rgba(109, 74, 255, 0.1);
  transform: translateY(-1px);
}

.rf-call-header__actions button:disabled {
  opacity: 0.55;
  cursor: wait;
}

/* =========================================================
   GLOBAL WORKSPACE ALERTS
   ========================================================= */

.rf-workspace-alert {
  margin: 0 0 22px;
  padding: 14px 17px;
  border: 1px solid;
  border-radius: 13px;
  font-size: 0.92rem;
  font-weight: 650;
  box-shadow: var(--rf-shadow-sm);
}

.rf-workspace-alert--error {
  color: #982e3e;
  border-color: var(--rf-danger-border);
  background: var(--rf-danger-soft);
}

.rf-workspace-alert--success {
  color: #176d3d;
  border-color: var(--rf-success-border);
  background: var(--rf-success-soft);
}

/* =========================================================
   MAIN TWO-COLUMN LAYOUT
   ========================================================= */

.rf-call-layout {
  display: grid;
  grid-template-columns:
    minmax(0, 1.42fr)
    minmax(330px, 0.88fr);
  align-items: start;
  gap: 24px;
}

.rf-call-layout__primary,
.rf-call-layout__secondary {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 24px;
}

/* =========================================================
   SHARED CARD STYLE
   ========================================================= */

.rf-call-workspace .cardish,
.rf-call-outcome-card,
.rf-call-history-card,
.rf-call-information-panel,
.rf-mini-audit-panel {
  min-width: 0;
  border: 1px solid var(--rf-border);
  border-radius: 20px;
  background: var(--rf-surface);
  box-shadow: var(--rf-shadow-md);
}

.rf-call-outcome-card,
.rf-call-history-card,
.rf-call-information-panel {
  padding: clamp(20px, 2vw, 28px);
}

.rf-call-outcome-card h2,
.rf-call-history-card h2,
.rf-call-information-panel h2,
.rf-mini-audit-panel h2 {
  margin: 5px 0 0;
  color: var(--rf-text);
  font-size: clamp(1.15rem, 1.35vw, 1.45rem);
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: -0.025em;
}

/* =========================================================
   TELNYX DIALER
   ========================================================= */

.rf-call-workspace .rf-telnyx-dialer {
  position: relative;
  overflow: hidden;
  padding: clamp(22px, 2.2vw, 30px);
  border-color: #ddd7f4;
  box-shadow: var(--rf-shadow-lg);
}

.rf-call-workspace .rf-telnyx-dialer::before {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 4px;
  background:
    linear-gradient(
      90deg,
      var(--rf-primary),
      #9a72ff,
      #c1aaff
    );
  content: "";
}

.rf-telnyx-dialer audio {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

.rf-call-workspace .section-title-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 22px;
}

.rf-call-workspace .section-title-row > div {
  min-width: 0;
}

.rf-call-workspace .section-title-row h3 {
  margin: 8px 0 7px;
  color: #14172a;
  font-size: clamp(1.45rem, 2vw, 2rem);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.035em;
  overflow-wrap: anywhere;
}

.rf-call-workspace .section-title-row p {
  margin: 5px 0 0;
  color: var(--rf-text-soft);
  font-size: 0.92rem;
}

.rf-call-workspace .section-title-row p b {
  color: var(--rf-text);
  font-weight: 800;
}

.rf-call-workspace .text-xs {
  font-size: 0.82rem;
}

.rf-call-workspace .text-muted {
  color: var(--rf-text-muted);
}

/* Dialer status badge */

.rf-call-workspace .badge {
  display: inline-flex;
  min-width: 78px;
  min-height: 36px;
  align-items: center;
  justify-content: center;
  padding: 7px 13px;
  border: 1px solid;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.025em;
  white-space: nowrap;
}

.rf-call-workspace .badge-gray {
  color: #5f6677;
  border-color: #dfe3ec;
  background: #f3f5f8;
}

.rf-call-workspace .badge-green {
  color: #176c3d;
  border-color: var(--rf-success-border);
  background: var(--rf-success-soft);
}

.rf-call-workspace .badge-amber {
  color: #9a5608;
  border-color: var(--rf-warning-border);
  background: var(--rf-warning-soft);
  animation: rf-status-pulse 1.8s ease-in-out infinite;
}

.rf-call-workspace .badge-red {
  color: #a52d40;
  border-color: var(--rf-danger-border);
  background: var(--rf-danger-soft);
}

@keyframes rf-status-pulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(183, 104, 8, 0);
  }

  50% {
    box-shadow: 0 0 0 6px rgba(183, 104, 8, 0.09);
  }
}

/* Dialer information banners */

.rf-call-workspace .success-banner,
.rf-call-workspace .error-banner {
  margin: 20px 0 0;
  padding: 14px 16px;
  border: 1px solid;
  border-radius: 13px;
  font-size: 0.9rem;
  font-weight: 650;
  line-height: 1.5;
}

.rf-call-workspace .success-banner {
  color: #246e43;
  border-color: var(--rf-success-border);
  background: var(--rf-success-soft);
}

.rf-call-workspace .error-banner {
  color: #a02c3e;
  border-color: var(--rf-danger-border);
  background: var(--rf-danger-soft);
}

.rf-telnyx-result {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: 18px;
  padding: 13px 15px;
  border: 1px solid var(--rf-primary-border);
  border-radius: 12px;
  background: var(--rf-primary-soft);
}

.rf-telnyx-result span {
  color: var(--rf-text-soft);
  font-size: 0.82rem;
  font-weight: 650;
}

.rf-telnyx-result b {
  color: var(--rf-primary-dark);
  font-size: 0.9rem;
}

/* Recording consent */

.rf-assignment-option {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-top: 20px;
  padding: 15px 16px;
  border: 1px solid var(--rf-border);
  border-radius: 13px;
  color: #4e5569;
  font-size: 0.88rem;
  font-weight: 600;
  line-height: 1.5;
  background: var(--rf-surface-soft);
  cursor: pointer;
}

.rf-assignment-option:hover {
  border-color: var(--rf-primary-border);
  background: #fbfaff;
}

.rf-assignment-option input[type="checkbox"] {
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
  margin: 1px 0 0;
  accent-color: var(--rf-primary);
  cursor: pointer;
}

.rf-assignment-option:has(input:disabled) {
  opacity: 0.68;
  cursor: not-allowed;
}

/* Dialer actions */

.rf-call-workspace .flex {
  display: flex;
}

.rf-call-workspace .flex-gap {
  gap: 10px;
}

.rf-call-workspace .flex-wrap {
  flex-wrap: wrap;
}

.rf-call-workspace .mt16 {
  margin-top: 18px;
}

.rf-call-workspace .btn {
  display: inline-flex;
  min-width: 120px;
  min-height: 46px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 11px 19px;
  border: 1px solid transparent;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 800;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  transition:
    transform 160ms ease,
    box-shadow 160ms ease,
    border-color 160ms ease,
    background-color 160ms ease;
}

.rf-call-workspace .btn:hover:not(:disabled) {
  transform: translateY(-1px);
}

.rf-call-workspace .btn:active:not(:disabled) {
  transform: translateY(0);
}

.rf-call-workspace .btn:disabled {
  opacity: 0.58;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

.rf-call-workspace .btn.primary {
  color: #ffffff;
  border-color: var(--rf-primary);
  background:
    linear-gradient(
      135deg,
      #7656ff,
      var(--rf-primary)
    );
  box-shadow: 0 9px 20px rgba(109, 74, 255, 0.24);
}

.rf-call-workspace .btn.primary:hover:not(:disabled) {
  background:
    linear-gradient(
      135deg,
      #6845f5,
      var(--rf-primary-dark)
    );
  box-shadow: 0 11px 24px rgba(109, 74, 255, 0.3);
}

.rf-call-workspace .btn.light {
  color: #454b60;
  border-color: var(--rf-border);
  background: #ffffff;
}

.rf-call-workspace .btn.light:hover:not(:disabled) {
  color: var(--rf-primary-dark);
  border-color: var(--rf-primary-border);
  background: var(--rf-primary-soft);
}

.rf-call-workspace .btn.danger {
  color: #ffffff;
  border-color: var(--rf-danger);
  background:
    linear-gradient(
      135deg,
      #dc5364,
      var(--rf-danger)
    );
  box-shadow: 0 8px 18px rgba(197, 59, 77, 0.2);
}

.rf-call-workspace .btn.danger:hover:not(:disabled) {
  background:
    linear-gradient(
      135deg,
      #c84052,
      var(--rf-danger-dark)
    );
}

/* =========================================================
   CALL OUTCOME FORM
   ========================================================= */

.rf-call-outcome-card {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.rf-call-outcome-card > div:first-child {
  grid-column: 1 / -1;
  padding-bottom: 3px;
}

.rf-call-outcome-card label {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.rf-call-outcome-card label:nth-of-type(2) {
  grid-column: 1 / -1;
}

.rf-call-outcome-card label > span {
  color: #464c60;
  font-size: 0.8rem;
  font-weight: 800;
}

.rf-call-outcome-card select,
.rf-call-outcome-card input,
.rf-call-outcome-card textarea {
  width: 100%;
  min-width: 0;
  border: 1px solid var(--rf-border-strong);
  border-radius: 11px;
  color: var(--rf-text);
  font-size: 0.9rem;
  background: #ffffff;
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    background-color 160ms ease;
}

.rf-call-outcome-card select,
.rf-call-outcome-card input {
  min-height: 45px;
  padding: 10px 13px;
}

.rf-call-outcome-card textarea {
  min-height: 112px;
  padding: 12px 13px;
  line-height: 1.5;
  resize: vertical;
}

.rf-call-outcome-card select:hover,
.rf-call-outcome-card input:hover,
.rf-call-outcome-card textarea:hover {
  border-color: #bfc3d1;
}

.rf-call-outcome-card select:focus,
.rf-call-outcome-card input:focus,
.rf-call-outcome-card textarea:focus {
  outline: none;
  border-color: var(--rf-primary);
  background: #ffffff;
  box-shadow: 0 0 0 4px rgba(109, 74, 255, 0.1);
}

.rf-call-outcome-card textarea::placeholder,
.rf-call-outcome-card input::placeholder {
  color: #9ca1b2;
}

.rf-call-outcome-card > button {
  min-height: 45px;
  align-self: end;
  justify-self: start;
  padding: 11px 20px;
  border: 1px solid var(--rf-primary);
  border-radius: 11px;
  color: #ffffff;
  font-size: 0.88rem;
  font-weight: 800;
  background:
    linear-gradient(
      135deg,
      #7656ff,
      var(--rf-primary)
    );
  box-shadow: 0 8px 18px rgba(109, 74, 255, 0.2);
  cursor: pointer;
  transition:
    transform 160ms ease,
    box-shadow 160ms ease,
    opacity 160ms ease;
}

.rf-call-outcome-card > button:hover:not(:disabled) {
  box-shadow: 0 11px 24px rgba(109, 74, 255, 0.28);
  transform: translateY(-1px);
}

.rf-call-outcome-card > button:disabled {
  opacity: 0.55;
  cursor: wait;
}

/* =========================================================
   CALL HISTORY
   ========================================================= */

.rf-call-history-card > div:first-child {
  margin-bottom: 17px;
}

.rf-call-history-card > p {
  margin: 12px 0 0;
  color: var(--rf-text-soft);
  font-size: 0.88rem;
}

.rf-call-history-list {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.rf-call-history-list article {
  display: grid;
  grid-template-columns:
    minmax(110px, 0.9fr)
    minmax(160px, 1.4fr)
    72px
    auto;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--rf-border);
  border-radius: 11px;
  background: var(--rf-surface-soft);
  transition:
    border-color 160ms ease,
    background-color 160ms ease,
    transform 160ms ease;
}

.rf-call-history-list article:hover {
  border-color: var(--rf-primary-border);
  background: #fbfaff;
  transform: translateY(-1px);
}

.rf-call-history-list article strong {
  color: var(--rf-text);
  font-size: 0.85rem;
}

.rf-call-history-list article span {
  color: var(--rf-text-soft);
  font-size: 0.8rem;
  overflow-wrap: anywhere;
}

.rf-call-history-list article a {
  color: var(--rf-primary-dark);
  font-size: 0.8rem;
  font-weight: 800;
  text-decoration: none;
}

.rf-call-history-list article a:hover {
  text-decoration: underline;
}

/* =========================================================
   LEAD INFORMATION PANEL
   ========================================================= */

.rf-call-information-panel {
  position: relative;
  overflow: hidden;
}

.rf-call-information-panel::before {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 3px;
  background:
    linear-gradient(
      90deg,
      var(--rf-primary),
      #a58aff
    );
  content: "";
}

.rf-call-information-panel h2 {
  margin-bottom: 20px;
  overflow-wrap: anywhere;
}

.rf-call-information-panel dl {
  display: grid;
  grid-template-columns: minmax(92px, 0.34fr) minmax(0, 1fr);
  gap: 0;
  margin: 0;
  overflow: hidden;
  border: 1px solid var(--rf-border);
  border-radius: 13px;
}

.rf-call-information-panel dt,
.rf-call-information-panel dd {
  margin: 0;
  padding: 12px 13px;
  border-bottom: 1px solid var(--rf-border);
  font-size: 0.82rem;
  line-height: 1.45;
}

.rf-call-information-panel dt {
  color: #71778b;
  font-weight: 750;
  background: var(--rf-surface-soft);
}

.rf-call-information-panel dd {
  min-width: 0;
  color: #31364a;
  font-weight: 650;
  overflow-wrap: anywhere;
  background: #ffffff;
}

.rf-call-information-panel dt:last-of-type,
.rf-call-information-panel dd:last-of-type {
  border-bottom: 0;
}

/* =========================================================
   MINI AUDIT PANEL
   ========================================================= */

.rf-mini-audit-panel {
  overflow: hidden;
}

.rf-mini-audit-panel__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 24px;
  border-bottom: 1px solid var(--rf-border);
}

.rf-mini-audit-panel__header > div:first-child {
  min-width: 0;
}

.rf-mini-audit-panel__header h2 {
  margin-bottom: 5px;
}

.rf-mini-audit-panel__header > div:first-child > p:last-child {
  margin: 0;
  color: var(--rf-text-soft);
  font-size: 0.85rem;
}

/* Audit status */

.rf-mini-audit-status {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 9px;
  padding: 9px 11px;
  border: 1px solid var(--rf-border);
  border-radius: 12px;
  background: var(--rf-surface-soft);
}

.rf-mini-audit-status > span {
  width: 9px;
  height: 9px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #9499a8;
  box-shadow: 0 0 0 4px rgba(148, 153, 168, 0.12);
}

.rf-mini-audit-status > div {
  display: flex;
  flex-direction: column;
}

.rf-mini-audit-status strong {
  color: #4d5367;
  font-size: 0.72rem;
  line-height: 1.3;
}

.rf-mini-audit-status small {
  margin-top: 2px;
  color: var(--rf-text-muted);
  font-size: 0.66rem;
}

.rf-mini-audit-status--completed {
  border-color: var(--rf-success-border);
  background: var(--rf-success-soft);
}

.rf-mini-audit-status--completed > span {
  background: var(--rf-success);
  box-shadow: 0 0 0 4px rgba(22, 132, 71, 0.12);
}

.rf-mini-audit-status--completed strong {
  color: #176c3d;
}

.rf-mini-audit-status--processing {
  border-color: var(--rf-warning-border);
  background: var(--rf-warning-soft);
}

.rf-mini-audit-status--processing > span {
  background: var(--rf-warning);
  animation: rf-status-pulse 1.6s ease-in-out infinite;
}

.rf-mini-audit-status--failed {
  border-color: var(--rf-danger-border);
  background: var(--rf-danger-soft);
}

.rf-mini-audit-status--failed > span {
  background: var(--rf-danger);
}

/* Audit branded banner */

.rf-mini-audit-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin: 20px 20px 0;
  padding: 16px 17px;
  border-radius: 14px;
  color: #ffffff;
  background:
    linear-gradient(
      135deg,
      #201c3e,
      #39305f
    );
  box-shadow: 0 10px 24px rgba(28, 23, 59, 0.18);
}

.rf-mini-audit-banner__brand {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 11px;
}

.rf-mini-audit-banner__brand > span {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 11px;
  font-size: 0.78rem;
  font-weight: 900;
  background: rgba(255, 255, 255, 0.12);
}

.rf-mini-audit-banner__brand > div,
.rf-mini-audit-banner__date {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.rf-mini-audit-banner small {
  color: rgba(255, 255, 255, 0.67);
  font-size: 0.61rem;
  font-weight: 700;
  letter-spacing: 0.06em;
}

.rf-mini-audit-banner strong {
  margin-top: 3px;
  color: #ffffff;
  font-size: 0.72rem;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.rf-mini-audit-banner__date {
  flex: 0 0 auto;
  text-align: right;
}

/* Audit sections */

.rf-mini-audit-section {
  padding: 23px 22px;
  border-bottom: 1px solid var(--rf-border);
}

.rf-mini-audit-section__header {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}

.rf-mini-audit-section__header > span {
  color: var(--rf-primary);
  font-size: 0.78rem;
  font-weight: 900;
}

.rf-mini-audit-section__header h3 {
  margin: 0;
  color: var(--rf-text);
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: -0.015em;
}

.rf-mini-audit-section__header p {
  margin: 3px 0 0;
  color: var(--rf-text-soft);
  font-size: 0.76rem;
  line-height: 1.4;
}

.rf-mini-audit-section__header > b {
  padding: 5px 8px;
  border-radius: 999px;
  color: var(--rf-primary-dark);
  font-size: 0.66rem;
  background: var(--rf-primary-soft);
}

/* Business snapshot */

.rf-mini-audit-snapshot {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--rf-border);
  border-radius: 13px;
  background: #ffffff;
}

.rf-mini-audit-snapshot-row {
  display: flex;
  min-width: 0;
  min-height: 78px;
  flex-direction: column;
  justify-content: center;
  gap: 6px;
  padding: 13px 14px;
  border-right: 1px solid var(--rf-border);
  border-bottom: 1px solid var(--rf-border);
}

.rf-mini-audit-snapshot-row:nth-child(2n) {
  border-right: 0;
}

.rf-mini-audit-snapshot-row--wide {
  grid-column: 1 / -1;
  border-right: 0;
}

.rf-mini-audit-snapshot-row small {
  color: var(--rf-text-muted);
  font-size: 0.68rem;
  font-weight: 750;
}

.rf-mini-audit-snapshot-row strong,
.rf-mini-audit-snapshot-row a {
  color: #292e42;
  font-size: 0.78rem;
  font-weight: 700;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.rf-mini-audit-snapshot-row a {
  color: var(--rf-primary-dark);
  text-decoration: none;
}

.rf-mini-audit-snapshot-row a:hover {
  text-decoration: underline;
}

/* Audit issues */

.rf-mini-audit-issues {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.rf-mini-audit-issue {
  overflow: hidden;
  border: 1px solid var(--rf-border);
  border-radius: 13px;
  background: #ffffff;
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease;
}

.rf-mini-audit-issue:hover,
.rf-mini-audit-issue.is-expanded {
  border-color: var(--rf-primary-border);
  box-shadow: 0 7px 20px rgba(109, 74, 255, 0.07);
}

.rf-mini-audit-issue__summary {
  display: grid;
  width: 100%;
  grid-template-columns: 34px minmax(0, 1fr) auto 22px;
  align-items: center;
  gap: 10px;
  padding: 13px;
  border: 0;
  color: inherit;
  text-align: left;
  background: transparent;
  cursor: pointer;
}

.rf-mini-audit-issue__number {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border-radius: 9px;
  color: var(--rf-primary-dark);
  font-size: 0.67rem;
  font-weight: 900;
  background: var(--rf-primary-soft);
}

.rf-mini-audit-issue__summary > div {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.rf-mini-audit-issue__summary small {
  color: var(--rf-text-muted);
  font-size: 0.64rem;
  font-weight: 700;
}

.rf-mini-audit-issue__summary strong {
  margin-top: 2px;
  color: #2b3043;
  font-size: 0.78rem;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.rf-mini-audit-issue__summary > b {
  color: var(--rf-primary);
  font-size: 1.15rem;
}

.rf-mini-audit-severity {
  padding: 5px 8px;
  border-radius: 999px;
  font-size: 0.62rem;
  font-weight: 850;
  white-space: nowrap;
}

.rf-mini-audit-severity--high,
.rf-mini-audit-severity--critical {
  color: #a42c3d;
  background: var(--rf-danger-soft);
}

.rf-mini-audit-severity--medium {
  color: #985508;
  background: var(--rf-warning-soft);
}

.rf-mini-audit-severity--low {
  color: #176c3d;
  background: var(--rf-success-soft);
}

.rf-mini-audit-issue__content {
  display: none;
  padding: 0 15px 15px 57px;
}

.rf-mini-audit-issue.is-expanded
  .rf-mini-audit-issue__content {
  display: grid;
  gap: 11px;
}

.rf-mini-audit-issue__content > div {
  padding: 12px 13px;
  border-radius: 10px;
  background: var(--rf-surface-soft);
}

.rf-mini-audit-issue__content small {
  color: var(--rf-primary);
  font-size: 0.65rem;
  font-weight: 850;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.rf-mini-audit-issue__content p {
  margin: 6px 0 0;
  color: #484e62;
  font-size: 0.76rem;
  line-height: 1.55;
}

.rf-mini-audit-evidence {
  border-left: 3px solid var(--rf-primary-border);
}

/* Audit internal footer */

.rf-mini-audit-source-footer {
  padding: 18px 22px;
  color: #d8d3ee;
  background:
    linear-gradient(
      135deg,
      #211d3e,
      #302950
    );
}

.rf-mini-audit-source-footer strong {
  color: #ffffff;
  font-size: 0.7rem;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.rf-mini-audit-source-footer p {
  margin: 7px 0;
  color: #d4d0e5;
  font-size: 0.7rem;
  line-height: 1.55;
}

.rf-mini-audit-source-footer span {
  color: #aaa2cf;
  font-size: 0.65rem;
  font-weight: 700;
}

/* Audit downloads */

.rf-mini-audit-downloads {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  padding: 20px 22px 0;
}

.rf-mini-audit-download-button {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--rf-border);
  border-radius: 12px;
  color: inherit;
  text-align: left;
  text-decoration: none;
  background: #ffffff;
  cursor: pointer;
  transition:
    border-color 160ms ease,
    background-color 160ms ease,
    transform 160ms ease,
    box-shadow 160ms ease;
}

.rf-mini-audit-download-button:hover:not(:disabled) {
  border-color: var(--rf-primary-border);
  background: #fbfaff;
  box-shadow: 0 7px 17px rgba(109, 74, 255, 0.07);
  transform: translateY(-1px);
}

.rf-mini-audit-download-button > span {
  display: grid;
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 9px;
  color: var(--rf-primary-dark);
  font-size: 0.65rem;
  font-weight: 900;
  background: var(--rf-primary-soft);
}

.rf-mini-audit-download-button > div {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.rf-mini-audit-download-button strong {
  color: #303548;
  font-size: 0.74rem;
}

.rf-mini-audit-download-button small {
  margin-top: 2px;
  color: var(--rf-text-muted);
  font-size: 0.64rem;
}

.rf-mini-audit-download-button--primary {
  border-color: var(--rf-primary-border);
  background: var(--rf-primary-soft);
}

.rf-mini-audit-download-button--disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

/* Audit action buttons */

.rf-mini-audit-actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  padding: 18px 22px 22px;
}

.rf-mini-audit-action {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 10px;
  padding: 12px 11px;
  border: 1px solid var(--rf-border);
  border-radius: 12px;
  color: inherit;
  text-align: left;
  background: var(--rf-surface-soft);
  cursor: pointer;
  transition:
    border-color 160ms ease,
    background-color 160ms ease,
    transform 160ms ease;
}

.rf-mini-audit-action:hover:not(:disabled) {
  border-color: var(--rf-primary-border);
  background: var(--rf-primary-soft);
  transform: translateY(-1px);
}

.rf-mini-audit-action:disabled {
  opacity: 0.55;
  cursor: wait;
}

.rf-mini-audit-action > span {
  display: grid;
  width: 32px;
  height: 32px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 9px;
  color: var(--rf-primary-dark);
  font-size: 0.65rem;
  font-weight: 900;
  background: #ffffff;
  box-shadow: 0 2px 7px rgba(30, 34, 55, 0.06);
}

.rf-mini-audit-action > div {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.rf-mini-audit-action strong {
  color: #33384b;
  font-size: 0.69rem;
  line-height: 1.35;
}

.rf-mini-audit-action small {
  margin-top: 2px;
  color: var(--rf-text-muted);
  font-size: 0.6rem;
  line-height: 1.35;
}

.rf-mini-audit-action--primary {
  border-color: var(--rf-primary-border);
  background: var(--rf-primary-soft);
}

/* Audit loading state */

.rf-mini-audit-progress {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 17px;
  padding: 25px;
}

.rf-mini-audit-progress__spinner {
  position: relative;
  display: grid;
  width: 54px;
  height: 54px;
  place-items: center;
  border-radius: 16px;
  background: var(--rf-primary-soft);
}

.rf-mini-audit-progress__spinner > span {
  position: absolute;
  inset: 5px;
  border: 3px solid rgba(109, 74, 255, 0.16);
  border-top-color: var(--rf-primary);
  border-radius: 50%;
  animation: rf-audit-spin 0.9s linear infinite;
}

.rf-mini-audit-progress__spinner b {
  color: var(--rf-primary-dark);
  font-size: 0.65rem;
}

@keyframes rf-audit-spin {
  to {
    transform: rotate(360deg);
  }
}

.rf-mini-audit-progress__content h3 {
  margin: 5px 0;
  font-size: 1rem;
}

.rf-mini-audit-progress__content > p:last-child {
  margin: 0;
  color: var(--rf-text-soft);
  font-size: 0.78rem;
}

.rf-mini-audit-progress__steps {
  display: grid;
  grid-column: 1 / -1;
  gap: 8px;
  margin-top: 4px;
}

.rf-mini-audit-progress__steps article {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border: 1px solid var(--rf-border);
  border-radius: 10px;
  background: var(--rf-surface-soft);
}

.rf-mini-audit-progress__steps article > span {
  display: grid;
  width: 25px;
  height: 25px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 8px;
  color: var(--rf-text-muted);
  font-size: 0.65rem;
  font-weight: 800;
  background: #ffffff;
}

.rf-mini-audit-progress__steps article > div {
  display: flex;
  flex-direction: column;
}

.rf-mini-audit-progress__steps strong {
  font-size: 0.72rem;
}

.rf-mini-audit-progress__steps small {
  color: var(--rf-text-muted);
  font-size: 0.64rem;
}

.rf-mini-audit-progress__steps article.is-active {
  border-color: var(--rf-primary-border);
  background: var(--rf-primary-soft);
}

.rf-mini-audit-progress__steps article.is-active > span {
  color: #ffffff;
  background: var(--rf-primary);
}

/* Audit empty state */

.rf-mini-audit-empty {
  display: flex;
  min-height: 240px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  padding: 30px 24px;
  text-align: center;
}

.rf-mini-audit-empty > span {
  display: grid;
  width: 50px;
  height: 50px;
  place-items: center;
  margin-bottom: 12px;
  border-radius: 15px;
  color: var(--rf-primary-dark);
  font-size: 0.75rem;
  font-weight: 900;
  background: var(--rf-primary-soft);
}

.rf-mini-audit-empty strong {
  font-size: 0.96rem;
}

.rf-mini-audit-empty p {
  max-width: 380px;
  margin: 7px 0 0;
  color: var(--rf-text-soft);
  font-size: 0.78rem;
}

.rf-mini-audit-empty--compact {
  min-height: 155px;
  border: 1px dashed var(--rf-border-strong);
  border-radius: 13px;
  background: var(--rf-surface-soft);
}

/* =========================================================
   EMPTY WORKSPACE
   ========================================================= */

.rf-call-empty-state {
  display: flex;
  min-height: 360px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  padding: 40px;
  border: 1px solid var(--rf-border);
  border-radius: 20px;
  text-align: center;
  background: #ffffff;
  box-shadow: var(--rf-shadow-md);
}

.rf-call-empty-state h1 {
  margin: 0 0 8px;
  font-size: 1.55rem;
}

.rf-call-empty-state p {
  max-width: 520px;
  margin: 0;
  color: var(--rf-text-soft);
}

.rf-call-empty-state button {
  margin-top: 20px;
  padding: 11px 18px;
  border: 0;
  border-radius: 11px;
  color: #ffffff;
  font-weight: 800;
  background: var(--rf-primary);
  cursor: pointer;
}

/* =========================================================
   RESPONSIVE — MEDIUM DESKTOP / TABLET
   ========================================================= */

@media (max-width: 1180px) {
  .rf-call-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .rf-call-layout__secondary {
    display: grid;
    grid-template-columns: minmax(280px, 0.7fr) minmax(0, 1.3fr);
    align-items: start;
  }

  .rf-mini-audit-panel {
    grid-column: 2;
    grid-row: 1;
  }

  .rf-call-information-panel {
    grid-column: 1;
    grid-row: 1;
  }
}

@media (max-width: 900px) {
  .rf-call-workspace {
    padding: 18px;
  }

  .rf-call-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .rf-call-header__actions {
    width: 100%;
    justify-content: flex-start;
  }

  .rf-call-layout__secondary {
    display: flex;
  }

  .rf-mini-audit-panel,
  .rf-call-information-panel {
    grid-column: auto;
    grid-row: auto;
  }

  .rf-mini-audit-actions {
    grid-template-columns: 1fr;
  }
}

/* =========================================================
   RESPONSIVE — MOBILE
   ========================================================= */

@media (max-width: 680px) {
  .rf-call-workspace {
    padding: 12px;
    background: #f7f8fc;
  }

  .rf-call-header {
    margin-bottom: 16px;
    padding: 20px;
    border-radius: 17px;
  }

  .rf-call-header__actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rf-call-header__actions button {
    width: 100%;
  }

  .rf-call-layout,
  .rf-call-layout__primary,
  .rf-call-layout__secondary {
    gap: 16px;
  }

  .rf-call-workspace .cardish,
  .rf-call-outcome-card,
  .rf-call-history-card,
  .rf-call-information-panel,
  .rf-mini-audit-panel {
    border-radius: 16px;
  }

  .rf-call-workspace .rf-telnyx-dialer,
  .rf-call-outcome-card,
  .rf-call-history-card,
  .rf-call-information-panel {
    padding: 19px;
  }

  .rf-call-workspace .section-title-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .rf-call-workspace .badge {
    min-width: 0;
  }

  .rf-call-workspace .flex.flex-gap {
    display: grid;
    width: 100%;
    grid-template-columns: 1fr;
  }

  .rf-call-workspace .btn {
    width: 100%;
  }

  .rf-call-outcome-card {
    grid-template-columns: 1fr;
  }

  .rf-call-outcome-card > div:first-child,
  .rf-call-outcome-card label:nth-of-type(2) {
    grid-column: auto;
  }

  .rf-call-outcome-card > button {
    width: 100%;
    justify-self: stretch;
  }

  .rf-call-history-list article {
    grid-template-columns: 1fr auto;
    gap: 5px 10px;
  }

  .rf-call-history-list article span:first-of-type {
    grid-column: 1 / -1;
  }

  .rf-call-information-panel dl {
    grid-template-columns: 1fr;
  }

  .rf-call-information-panel dt {
    padding-bottom: 4px;
    border-bottom: 0;
  }

  .rf-call-information-panel dd {
    padding-top: 3px;
  }

  .rf-mini-audit-panel__header {
    flex-direction: column;
    padding: 20px;
  }

  .rf-mini-audit-banner {
    align-items: flex-start;
    flex-direction: column;
    margin: 15px 15px 0;
  }

  .rf-mini-audit-banner__date {
    text-align: left;
  }

  .rf-mini-audit-section {
    padding: 20px 17px;
  }

  .rf-mini-audit-section__header {
    grid-template-columns: 32px minmax(0, 1fr);
  }

  .rf-mini-audit-section__header > b {
    grid-column: 2;
    justify-self: start;
  }

  .rf-mini-audit-snapshot {
    grid-template-columns: 1fr;
  }

  .rf-mini-audit-snapshot-row,
  .rf-mini-audit-snapshot-row:nth-child(2n) {
    border-right: 0;
  }

  .rf-mini-audit-snapshot-row--wide {
    grid-column: auto;
  }

  .rf-mini-audit-issue__summary {
    grid-template-columns: 32px minmax(0, 1fr) 22px;
  }

  .rf-mini-audit-severity {
    grid-column: 2;
    justify-self: start;
  }

  .rf-mini-audit-issue__summary > b {
    grid-column: 3;
    grid-row: 1 / span 2;
  }

  .rf-mini-audit-issue__content {
    padding: 0 13px 13px;
  }

  .rf-mini-audit-downloads {
    grid-template-columns: 1fr;
    padding: 17px 17px 0;
  }

  .rf-mini-audit-actions {
    padding: 15px 17px 19px;
  }

  .rf-mini-audit-source-footer {
    padding: 17px;
  }
}

/* =========================================================
   REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {
  .rf-call-workspace *,
  .rf-call-workspace *::before,
  .rf-call-workspace *::after {
    scroll-behavior: auto;
    animation-duration: 0.01ms;
    animation-iteration-count: 1;
    transition-duration: 0.01ms;
  }
}

/* =========================================================
   ReachFly Attendance Camera Enhancements
   Append to apps/web/src/styles.css
   ========================================================= */

.attendance-page {
  --attendance-primary: #6d4aff;
  --attendance-primary-soft: #f1edff;
  --attendance-border: #e1e4ec;
  --attendance-text: #171a2d;
  --attendance-muted: #687086;
  --attendance-success: #167a43;
  --attendance-danger: #b93246;
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
}

.attendance-camera-card {
  min-width: 0;
}

.attendance-camera-card .text-muted {
  margin: 6px 0 0;
  color: var(--attendance-muted);
  font-size: 0.9rem;
  line-height: 1.5;
}

.attendance-camera-selector {
  display: grid;
  gap: 7px;
  margin: 0 0 14px;
}

.attendance-camera-selector > span {
  color: #444b60;
  font-size: 0.78rem;
  font-weight: 800;
}

.attendance-camera-selector select {
  width: 100%;
  min-height: 44px;
  padding: 9px 12px;
  border: 1px solid var(--attendance-border);
  border-radius: 11px;
  color: var(--attendance-text);
  background: #fff;
}

.attendance-camera-selector select:focus {
  outline: none;
  border-color: var(--attendance-primary);
  box-shadow: 0 0 0 4px rgba(109, 74, 255, 0.1);
}

.attendance-camera-frame {
  position: relative;
  min-height: 310px;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  border: 1px solid #dfe2eb;
  border-radius: 16px;
  background: #12131a;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.04),
    0 12px 30px rgba(20, 23, 39, 0.1);
}

.attendance-camera-frame video,
.attendance-camera-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.attendance-camera-placeholder,
.attendance-camera-loading {
  font-size: 0.9rem;
  font-weight: 700;
  line-height: 1.45;
}

.attendance-camera-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px 14px;
  margin: 11px 0 0;
  color: var(--attendance-muted);
}

.attendance-camera-meta small {
  font-size: 0.74rem;
  line-height: 1.4;
}

.attendance-camera-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 16px;
}

.attendance-camera-actions .btn {
  min-height: 42px;
}

.attendance-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 34px;
  padding: 7px 12px;
  border: 1px solid #dce0e9;
  border-radius: 999px;
  color: #61687a;
  font-size: 0.75rem;
  font-weight: 800;
  white-space: nowrap;
  background: #f5f6f9;
}

.attendance-status.active {
  color: #176b3d;
  border-color: #b9e5c9;
  background: #edf9f2;
}

.attendance-status.complete {
  color: #4b5265;
  border-color: #d9dde6;
  background: #f0f2f6;
}

.attendance-page .error-banner,
.attendance-page .success-banner {
  display: grid;
  gap: 4px;
  padding: 13px 15px;
  border: 1px solid;
  border-radius: 12px;
}

.attendance-page .error-banner {
  color: #9f3042;
  border-color: #efc3ca;
  background: #fff1f3;
}

.attendance-page .success-banner {
  color: #176b3d;
  border-color: #b9e5c9;
  background: #edf9f2;
}

.attendance-page .error-banner strong,
.attendance-page .success-banner strong {
  font-size: 0.86rem;
}

.attendance-page .error-banner span,
.attendance-page .success-banner span {
  font-size: 0.82rem;
  line-height: 1.45;
}

.attendance-page .error-banner small,
.attendance-page .success-banner small {
  opacity: 0.8;
  font-size: 0.7rem;
  overflow-wrap: anywhere;
}

.attendance-page .btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

@media (max-width: 700px) {
  .attendance-camera-frame {
    min-height: 250px;
  }

  .attendance-camera-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .attendance-camera-actions .btn {
    width: 100%;
  }

  .attendance-camera-meta {
    align-items: flex-start;
    flex-direction: column;
  }
}

/* Assigned-lead search and filter toolbar */
.caller-queue-toolbar.caller-queue-toolbar--filters {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) 210px 155px 175px auto;
  align-items: end;
  gap: 11px;
  padding: 14px;
  border: 1px solid #e2e5ed;
  border-radius: 14px;
  background: #fff;
}

.caller-queue-toolbar--filters label {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 6px;
}

.caller-queue-toolbar--filters label > span {
  color: #555c70;
  font-size: 0.7rem;
  font-weight: 800;
}

.caller-queue-toolbar--filters input,
.caller-queue-toolbar--filters select {
  width: 100%;
  min-height: 42px;
  padding: 9px 11px;
  border: 1px solid #d4d8e3;
  border-radius: 10px;
  color: #1b1e30;
  background: #fff;
}

.caller-queue-toolbar--filters input:focus,
.caller-queue-toolbar--filters select:focus {
  outline: none;
  border-color: #6d4aff;
  box-shadow: 0 0 0 4px rgba(109, 74, 255, 0.1);
}

.caller-filter-count {
  align-self: center;
  justify-self: end;
  color: #73798b;
  font-size: 0.72rem;
  font-weight: 750;
  white-space: nowrap;
}

@media (max-width: 1150px) {
  .caller-queue-toolbar.caller-queue-toolbar--filters {
    grid-template-columns: minmax(240px, 1fr) 1fr 1fr;
  }

  .caller-filter-search {
    grid-column: 1 / -1;
  }

  .caller-filter-count {
    justify-self: start;
  }
}

@media (max-width: 680px) {
  .caller-queue-toolbar.caller-queue-toolbar--filters {
    grid-template-columns: 1fr;
  }

  .caller-filter-search {
    grid-column: auto;
  }
}

.caller-dashboard-lead-filters {
  display: grid;
  grid-template-columns: minmax(240px, 1fr) 190px;
  gap: 10px;
  margin-bottom: 13px;
}

.caller-dashboard-lead-filters input,
.caller-dashboard-lead-filters select {
  min-height: 41px;
  padding: 9px 11px;
  border: 1px solid #d4d8e3;
  border-radius: 10px;
  color: #1b1e30;
  background: #fff;
}

.caller-dashboard-lead-filters input:focus,
.caller-dashboard-lead-filters select:focus {
  outline: none;
  border-color: #6d4aff;
  box-shadow: 0 0 0 4px rgba(109, 74, 255, 0.1);
}

@media (max-width: 680px) {
  .caller-dashboard-lead-filters {
    grid-template-columns: 1fr;
  }
}

/* =========================================================
   ReachFly manager resource whiteboard
   ========================================================= */

.rf-resource-board-page {
  --rb-primary: #6c4cf5;
  --rb-primary-dark: #5233d7;
  --rb-primary-soft: #f1edff;
  --rb-border: #e2e5ed;
  --rb-border-strong: #d2d6e2;
  --rb-text: #171a2c;
  --rb-muted: #697086;
  --rb-soft: #f7f8fb;
  --rb-success: #198754;
  --rb-warning: #b66a12;
  --rb-danger: #c43e50;
  width: 100%;
  max-width: 1700px;
  min-width: 0;
  margin: 0 auto;
  padding: clamp(18px, 2.3vw, 34px);
  color: var(--rb-text);
  background:
    radial-gradient(circle at 5% 0%, rgba(108, 76, 245, 0.09), transparent 27%),
    #f7f8fb;
}

.rf-resource-board-page *,
.rf-resource-board-page *::before,
.rf-resource-board-page *::after {
  box-sizing: border-box;
}

.rf-resource-board-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 20px;
  padding: 26px 28px;
  border: 1px solid #ddd8f2;
  border-radius: 22px;
  background: linear-gradient(135deg, #fff 0%, #faf8ff 100%);
  box-shadow: 0 14px 35px rgba(35, 30, 70, 0.08);
}

.rf-resource-board-header h1 {
  margin: 5px 0 7px;
  font-size: clamp(1.75rem, 2.4vw, 2.55rem);
  line-height: 1.08;
  letter-spacing: -0.045em;
}

.rf-resource-board-header p {
  max-width: 780px;
  margin: 0;
  color: var(--rb-muted);
}

.rf-resource-board-header__actions {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
}

.rf-resource-board-summary {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 12px;
  margin: 20px 0;
}

.rf-resource-board-summary article {
  padding: 17px 18px;
  border: 1px solid var(--rb-border);
  border-radius: 15px;
  background: #fff;
  box-shadow: 0 5px 18px rgba(25, 29, 50, 0.045);
}

.rf-resource-board-summary strong {
  display: block;
  margin-bottom: 4px;
  font-size: 1.45rem;
  line-height: 1;
}

.rf-resource-board-summary span {
  color: var(--rb-muted);
  font-size: 0.77rem;
  font-weight: 700;
}

.rf-resource-board-tabs {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  padding: 6px;
  border: 1px solid var(--rb-border);
  border-radius: 14px;
  background: #fff;
}

.rf-resource-board-tabs button {
  min-height: 40px;
  padding: 9px 15px;
  border: 0;
  border-radius: 10px;
  color: #62697c;
  font-size: 0.84rem;
  font-weight: 750;
  white-space: nowrap;
  background: transparent;
  cursor: pointer;
}

.rf-resource-board-tabs button:hover {
  color: var(--rb-primary-dark);
  background: var(--rb-primary-soft);
}

.rf-resource-board-tabs button.active {
  color: #fff;
  background: var(--rb-primary);
  box-shadow: 0 6px 15px rgba(108, 76, 245, 0.23);
}

.rf-resource-board-toolbar {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) 190px 220px auto;
  align-items: end;
  gap: 12px;
  margin: 14px 0 18px;
  padding: 15px;
  border: 1px solid var(--rb-border);
  border-radius: 14px;
  background: #fff;
}

.rf-resource-board-toolbar label,
.rf-quick-task-form label,
.rf-resource-settings-card label,
.rf-resource-dialog label {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 6px;
}

.rf-resource-board-toolbar label > span,
.rf-quick-task-form label > span,
.rf-resource-settings-card label > span,
.rf-resource-dialog label > span {
  color: #50566a;
  font-size: 0.72rem;
  font-weight: 800;
}

.rf-resource-board-toolbar input,
.rf-resource-board-toolbar select,
.rf-quick-task-form input,
.rf-quick-task-form select,
.rf-quick-task-form textarea,
.rf-resource-settings-card input,
.rf-resource-settings-card select,
.rf-resource-dialog input,
.rf-resource-dialog select {
  width: 100%;
  min-height: 42px;
  padding: 9px 11px;
  border: 1px solid var(--rb-border-strong);
  border-radius: 10px;
  color: var(--rb-text);
  background: #fff;
}

.rf-resource-board-toolbar input:focus,
.rf-resource-board-toolbar select:focus,
.rf-quick-task-form input:focus,
.rf-quick-task-form select:focus,
.rf-quick-task-form textarea:focus,
.rf-resource-settings-card input:focus,
.rf-resource-settings-card select:focus,
.rf-resource-dialog input:focus,
.rf-resource-dialog select:focus {
  outline: none;
  border-color: var(--rb-primary);
  box-shadow: 0 0 0 4px rgba(108, 76, 245, 0.1);
}

.rf-resource-board-live {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
  color: #5c6377;
  font-size: 0.75rem;
  font-weight: 750;
  white-space: nowrap;
}

.rf-resource-board-live i {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #22a862;
  box-shadow: 0 0 0 5px rgba(34, 168, 98, 0.12);
  animation: rb-live 1.7s ease-in-out infinite;
}

@keyframes rb-live {
  50% { box-shadow: 0 0 0 8px rgba(34, 168, 98, 0.04); }
}

.rf-whiteboard {
  display: grid;
  grid-auto-columns: minmax(310px, 360px);
  grid-auto-flow: column;
  align-items: start;
  gap: 14px;
  overflow-x: auto;
  padding: 2px 2px 18px;
  scroll-snap-type: x proximity;
}

.rf-board-lane {
  min-width: 0;
  min-height: 590px;
  overflow: hidden;
  border: 1px solid var(--rb-border);
  border-radius: 18px;
  background: #f2f4f8;
  box-shadow: 0 5px 18px rgba(25, 29, 50, 0.035);
  scroll-snap-align: start;
  transition: border-color 150ms ease, box-shadow 150ms ease, transform 150ms ease;
}

.rf-board-lane.is-over {
  border-color: var(--rb-primary);
  box-shadow: 0 0 0 4px rgba(108, 76, 245, 0.11), 0 12px 28px rgba(54, 42, 118, 0.1);
  transform: translateY(-2px);
}

.rf-board-lane.is-at-capacity {
  border-color: #ebc5ca;
}

.rf-board-lane__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 15px;
  border-bottom: 1px solid var(--rb-border);
  background: #fff;
}

.rf-board-lane__identity {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 10px;
}

.rf-board-lane__identity > div {
  min-width: 0;
}

.rf-board-lane h3 {
  margin: 0;
  overflow: hidden;
  font-size: 0.93rem;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-board-lane p {
  margin: 3px 0 0;
  color: var(--rb-muted);
  font-size: 0.69rem;
}

.rf-resource-avatar,
.rf-board-pool-icon {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  place-items: center;
  overflow: hidden;
  border-radius: 12px;
  color: var(--rb-primary-dark);
  font-size: 0.72rem;
  font-weight: 900;
  object-fit: cover;
  background: var(--rb-primary-soft);
}

.rf-board-pool-icon {
  color: #5e6578;
  background: #eceef3;
}

.rf-presence-badge {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 5px;
  padding: 5px 7px;
  border-radius: 999px;
  color: #73798b;
  font-size: 0.61rem;
  font-weight: 800;
  background: #f1f2f5;
}

.rf-presence-badge i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #9297a5;
}

.rf-presence-badge.online,
.rf-presence-badge.available {
  color: #176b42;
  background: #eaf8f0;
}

.rf-presence-badge.online i,
.rf-presence-badge.available i {
  background: #1c9b5b;
}

.rf-presence-badge.busy {
  color: #9f3b47;
  background: #fff0f2;
}

.rf-presence-badge.busy i {
  background: #c43e50;
}

.rf-resource-capacity {
  padding: 10px 14px 3px;
}

.rf-resource-capacity > span {
  display: block;
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: #dfe2e9;
}

.rf-resource-capacity i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #7757f5, #a17ff8);
}

.rf-resource-capacity small {
  display: block;
  margin-top: 5px;
  color: var(--rb-muted);
  font-size: 0.63rem;
}

.rf-board-lane__body {
  display: flex;
  max-height: 690px;
  flex-direction: column;
  gap: 10px;
  overflow-y: auto;
  padding: 11px;
}

.rf-board-card {
  padding: 12px;
  border: 1px solid #dfe2ea;
  border-radius: 13px;
  background: #fff;
  box-shadow: 0 4px 12px rgba(29, 33, 55, 0.045);
  cursor: grab;
  transition: border-color 140ms ease, box-shadow 140ms ease, transform 140ms ease;
}

.rf-board-card:hover {
  border-color: #cfc7f5;
  box-shadow: 0 8px 20px rgba(76, 58, 155, 0.09);
  transform: translateY(-1px);
}

.rf-board-card:active { cursor: grabbing; }
.rf-board-card.is-busy { opacity: 0.55; pointer-events: none; }

.rf-board-card--task.priority-high,
.rf-board-card--task.priority-urgent {
  border-left: 3px solid #d64b5d;
}

.rf-board-card__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.rf-drag-handle {
  color: #a0a5b4;
  font-weight: 900;
  letter-spacing: -4px;
}

.rf-board-status {
  padding: 4px 7px;
  border-radius: 999px;
  color: #606779;
  font-size: 0.58rem;
  font-weight: 850;
  background: #f0f2f5;
}

.rf-board-status.in_progress,
.rf-board-status.follow_up,
.rf-board-status.assigned {
  color: #76500d;
  background: #fff4dd;
}

.rf-board-status.qualified,
.rf-board-status.meeting_booked,
.rf-board-status.completed {
  color: #176b42;
  background: #e9f8ef;
}

.rf-board-status.blocked,
.rf-board-status.cancelled,
.rf-board-status.invalid_number {
  color: #a23241;
  background: #ffedef;
}

.rf-board-card h4 {
  margin: 0 0 5px;
  color: var(--rb-text);
  font-size: 0.84rem;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.rf-board-card > p {
  display: -webkit-box;
  margin: 0;
  overflow: hidden;
  color: var(--rb-muted);
  font-size: 0.68rem;
  line-height: 1.45;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.rf-board-card__meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 10px;
  padding-top: 9px;
  border-top: 1px solid #edf0f4;
}

.rf-board-card__meta span {
  overflow: hidden;
  color: #808698;
  font-size: 0.59rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-board-card__mobile-assign,
.rf-board-card__controls {
  display: grid;
  gap: 7px;
  margin-top: 9px;
}

.rf-board-card__controls {
  grid-template-columns: 1fr 1fr;
}

.rf-board-card select {
  width: 100%;
  min-height: 32px;
  padding: 5px 7px;
  border: 1px solid var(--rb-border);
  border-radius: 8px;
  color: #53596c;
  font-size: 0.62rem;
  background: #fafbfc;
}

.rf-task-linked-lead {
  margin-top: 8px;
  padding: 7px 8px;
  border-radius: 8px;
  color: var(--rb-primary-dark);
  font-size: 0.62rem;
  font-weight: 750;
  background: var(--rb-primary-soft);
}

.rf-lane-empty {
  display: flex;
  min-height: 110px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  border: 1px dashed #cfd3df;
  border-radius: 12px;
  color: #8b91a2;
  text-align: center;
  background: rgba(255, 255, 255, 0.45);
}

.rf-lane-empty span {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 9px;
  color: var(--rb-primary);
  font-weight: 900;
  background: var(--rb-primary-soft);
}

.rf-lane-empty p { margin: 7px 0 0; font-size: 0.68rem; }

.rf-task-board-layout {
  display: grid;
  grid-template-columns: 360px minmax(0, 1fr);
  align-items: start;
  gap: 16px;
}

.rf-quick-task-form {
  display: flex;
  flex-direction: column;
  gap: 13px;
  padding: 21px;
  border: 1px solid var(--rb-border);
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 7px 22px rgba(27, 30, 50, 0.055);
}

.rf-quick-task-form h2,
.rf-resources-panel h2,
.rf-activity-panel h2,
.rf-resource-dialog h2,
.rf-credentials-panel h2 {
  margin: 5px 0 5px;
  font-size: 1.25rem;
  letter-spacing: -0.025em;
}

.rf-quick-task-form p,
.rf-resources-panel header p,
.rf-resource-dialog header p,
.rf-credentials-panel p {
  margin: 0;
  color: var(--rb-muted);
  font-size: 0.78rem;
  line-height: 1.5;
}

.rf-quick-task-form textarea {
  min-height: 90px;
  resize: vertical;
}

.rf-quick-task-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.rf-resources-panel,
.rf-activity-panel {
  padding: 22px;
  border: 1px solid var(--rb-border);
  border-radius: 19px;
  background: #fff;
  box-shadow: 0 7px 24px rgba(27, 30, 50, 0.055);
}

.rf-resources-panel > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 18px;
}

.rf-resource-settings-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.rf-resource-settings-card {
  padding: 17px;
  border: 1px solid var(--rb-border);
  border-radius: 15px;
  background: #fafbfc;
}

.rf-resource-settings-card > header {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.rf-resource-settings-card h3 {
  margin: 0;
  overflow: hidden;
  font-size: 0.9rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-resource-settings-card header p {
  margin: 2px 0 0;
  overflow: hidden;
  color: var(--rb-muted);
  font-size: 0.65rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-resource-settings-card > label { margin-top: 11px; }

.rf-resource-performance {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  overflow: hidden;
  border: 1px solid var(--rb-border);
  border-radius: 11px;
  background: #fff;
}

.rf-resource-performance div {
  padding: 10px 7px;
  border-right: 1px solid var(--rb-border);
  text-align: center;
}

.rf-resource-performance div:last-child { border-right: 0; }
.rf-resource-performance strong { display: block; font-size: 0.95rem; }
.rf-resource-performance span { color: var(--rb-muted); font-size: 0.56rem; }
.rf-resource-settings-card .btn { margin-top: 14px; }

.rf-resource-dialog-backdrop {
  position: fixed;
  z-index: 1000;
  inset: 0;
  display: grid;
  place-items: center;
  overflow-y: auto;
  padding: 24px;
  background: rgba(18, 20, 34, 0.58);
  backdrop-filter: blur(5px);
}

.rf-resource-dialog {
  width: min(760px, 100%);
  max-height: calc(100vh - 48px);
  overflow-y: auto;
  padding: 24px;
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 24px 70px rgba(14, 16, 32, 0.25);
}

.rf-resource-dialog > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 18px;
}

.rf-dialog-close {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid var(--rb-border);
  border-radius: 11px;
  color: #676d7f;
  font-size: 1.25rem;
  background: #fff;
  cursor: pointer;
}

.rf-resource-dialog-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 13px;
}

.rf-resource-dialog footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--rb-border);
}

.rf-credentials-panel {
  display: grid;
  grid-template-columns: minmax(240px, 1fr) minmax(220px, 0.8fr) minmax(220px, 0.8fr) auto;
  align-items: center;
  gap: 14px;
  margin: 17px 0;
  padding: 17px;
  border: 1px solid #b9e4ca;
  border-radius: 15px;
  background: #effaf3;
}

.rf-credentials-panel label {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 5px 8px;
  min-width: 0;
}

.rf-credentials-panel label > span {
  grid-column: 1 / -1;
  color: #43705a;
  font-size: 0.65rem;
  font-weight: 800;
}

.rf-credentials-panel code {
  min-width: 0;
  overflow: hidden;
  padding: 8px;
  border-radius: 8px;
  color: #234d37;
  font-size: 0.72rem;
  text-overflow: ellipsis;
  background: #fff;
}

.rf-credentials-panel label button,
.rf-credentials-close {
  border: 1px solid #a9d9bc;
  border-radius: 8px;
  color: #21653f;
  font-size: 0.68rem;
  font-weight: 800;
  background: #fff;
  cursor: pointer;
}

.rf-credentials-close { min-height: 38px; padding: 8px 11px; }

.rf-activity-panel > header { margin-bottom: 15px; }
.rf-activity-list { display: flex; flex-direction: column; gap: 8px; }

.rf-activity-list article {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 11px 12px;
  border: 1px solid var(--rb-border);
  border-radius: 11px;
  background: #fafbfc;
}

.rf-activity-icon {
  display: grid;
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 10px;
  color: var(--rb-primary-dark);
  font-size: 0.61rem;
  font-weight: 900;
  background: var(--rb-primary-soft);
}

.rf-activity-list article > div { min-width: 0; }
.rf-activity-list strong { display: block; font-size: 0.78rem; overflow-wrap: anywhere; }
.rf-activity-list small { color: var(--rb-muted); font-size: 0.64rem; }

.rf-board-skeleton .rf-board-lane > header,
.rf-board-skeleton .rf-board-lane > div {
  height: 70px;
  margin: 12px;
  border-radius: 11px;
  background: linear-gradient(90deg, #eceef3 25%, #f7f8fa 50%, #eceef3 75%);
  background-size: 200% 100%;
  animation: rb-skeleton 1.25s linear infinite;
}

@keyframes rb-skeleton { to { background-position: -200% 0; } }

@media (max-width: 1350px) {
  .rf-resource-board-summary { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .rf-resource-settings-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 1050px) {
  .rf-resource-board-header { flex-direction: column; }
  .rf-resource-board-header__actions { justify-content: flex-start; }
  .rf-resource-board-toolbar { grid-template-columns: 1fr 1fr; }
  .rf-resource-board-live { justify-content: flex-start; }
  .rf-task-board-layout { grid-template-columns: 1fr; }
  .rf-credentials-panel { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 720px) {
  .rf-resource-board-page { padding: 12px; }
  .rf-resource-board-header { padding: 20px; border-radius: 17px; }
  .rf-resource-board-header__actions { display: grid; width: 100%; grid-template-columns: 1fr; }
  .rf-resource-board-header__actions .btn { width: 100%; }
  .rf-resource-board-summary { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .rf-resource-board-toolbar { grid-template-columns: 1fr; }
  .rf-whiteboard { grid-auto-columns: minmax(285px, 88vw); }
  .rf-resource-settings-grid,
  .rf-resource-dialog-grid,
  .rf-quick-task-grid,
  .rf-credentials-panel { grid-template-columns: 1fr; }
  .rf-resources-panel > header { flex-direction: column; }
  .rf-resource-dialog-backdrop { padding: 10px; }
  .rf-resource-dialog { max-height: calc(100vh - 20px); padding: 19px; }
  .rf-resource-dialog footer { display: grid; grid-template-columns: 1fr; }
  .rf-resource-dialog footer .btn { width: 100%; }
}

@media (prefers-reduced-motion: reduce) {
  .rf-resource-board-page *,
  .rf-resource-board-page *::before,
  .rf-resource-board-page *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
