  --agent-green: #087f5b;
  --agent-red: #c33245;
  --agent-amber: #b56b00;
  width: 100%;
  padding: 28px;
  color: var(--agent-ink);
}

.rf-agent-page *,
.rf-agent-page *::before,
.rf-agent-page *::after {
