  margin: 0;
  color: var(--agent-muted);
  font-size: 15px;
  line-height: 1.65;
}

.rf-agent-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.rf-agent-live-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid var(--agent-line);
  border-radius: 999px;
  background: #fff;
  font-size: 12px;
  font-weight: 800;
}

.rf-agent-live-pill i {
  width: 8px;
  height: 8px;
