/* ReachFly guided Voice Agent onboarding */
.rf-voice-wizard {
  max-width: 980px;
  margin: 0 auto 28px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 28px;
  background:
    radial-gradient(circle at top right, rgba(99, 102, 241, 0.13), transparent 32%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.98));
  box-shadow: 0 24px 70px rgba(15, 23, 42, 0.10);
  overflow: hidden;
}

.rf-voice-wizard-top {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding: 34px 38px 24px;
}

.rf-voice-wizard-top h2 {
  margin: 7px 0 8px;
  font-size: clamp(1.6rem, 3vw, 2.35rem);
  line-height: 1.12;
  letter-spacing: -0.035em;
}

.rf-voice-wizard-top p {
  max-width: 650px;
  margin: 0;
  color: #64748b;
  line-height: 1.65;
}

.rf-voice-wizard-kicker {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 11px;
  border-radius: 999px;
  background: rgba(79, 70, 229, 0.09);
  color: #4338ca;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.rf-voice-wizard-step-count {
  flex: 0 0 auto;
  height: 38px;
  padding: 0 14px;
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  background: #0f172a;
  color: white;
  font-weight: 800;
}

.rf-voice-progress {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  padding: 0 38px 28px;
}

.rf-voice-progress-item {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 7px;
  color: #94a3b8;
}

.rf-voice-progress-item::before {
  content: "";
  position: absolute;
  top: 16px;
  left: calc(-50% + 22px);
  width: calc(100% - 12px);
  height: 2px;
  background: #e2e8f0;
}

.rf-voice-progress-item:first-child::before {
  display: none;
}

.rf-voice-progress-item span {
  position: relative;
  z-index: 1;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 2px solid #e2e8f0;
  background: white;
  font-size: 0.8rem;
  font-weight: 900;
}

.rf-voice-progress-item small {
  font-size: 0.72rem;
  font-weight: 800;
}

.rf-voice-progress-item.done,
.rf-voice-progress-item.current {
  color: #4338ca;
}

.rf-voice-progress-item.done span {
  border-color: #22c55e;
  background: #22c55e;
  color: white;
}

.rf-voice-progress-item.done::before,
.rf-voice-progress-item.current::before {
  background: linear-gradient(90deg, #22c55e, #6366f1);
}

.rf-voice-progress-item.current span {
  border-color: #6366f1;
  box-shadow: 0 0 0 5px rgba(99, 102, 241, 0.10);
}

.rf-voice-wizard-body {
  border-top: 1px solid #e2e8f0;
  padding: 30px 38px 38px;
}

.rf-voice-wizard-note {
  display: grid;
  gap: 5px;
  padding: 15px 17px;
  margin-bottom: 22px;
  border: 1px solid rgba(99, 102, 241, 0.16);
  border-radius: 16px;
  background: rgba(238, 242, 255, 0.72);
}

.rf-voice-wizard-note b {
  color: #312e81;
}

.rf-voice-wizard-note span {
  color: #64748b;
  line-height: 1.5;
}

.rf-voice-essential-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.rf-voice-essential-grid.two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.rf-voice-wizard-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 22px;
}

.rf-voice-wizard-actions.end {
  justify-content: flex-end;
}

.rf-voice-wizard-actions.split {
  justify-content: space-between;
}

.rf-voice-primary-action {
  min-width: 190px;
}

.rf-voice-number-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 24px;
}

.rf-voice-number-card,
.rf-voice-credit-card {
  display: grid;
  gap: 16px;
  padding: 20px;
  border: 1px solid #e2e8f0;
  border-radius: 19px;
  background: white;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.05);
}

.rf-voice-number-card:hover,
.rf-voice-credit-card:hover {
  border-color: rgba(99, 102, 241, 0.42);
  transform: translateY(-1px);
}

.rf-voice-number-card h3,
.rf-voice-credit-card h3 {
  margin: 7px 0 3px;
  font-size: 1.18rem;
}

.rf-voice-number-card p,
.rf-voice-credit-card p {
  margin: 0;
  color: #64748b;
}

.rf-voice-number-badge {
  width: fit-content;
  padding: 5px 9px;
  border-radius: 999px;
  background: #ecfdf5;
  color: #047857;
  font-size: 0.7rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.rf-voice-number-price {
  display: grid;
  gap: 3px;
}

.rf-voice-number-price b {
  font-size: 1.35rem;
}

.rf-voice-number-price small,
.rf-voice-number-price span {
  color: #64748b;
}

.rf-voice-credit-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.rf-voice-credit-card.recommended {
  border-color: rgba(99, 102, 241, 0.42);
  background: linear-gradient(180deg, #fff, #f5f7ff);
}

.rf-voice-credit-card > b {
  font-size: 1.45rem;
}

.rf-voice-credit-card small {
  color: #64748b;
}

.rf-voice-active-number,
.rf-voice-summary-strip,
.rf-voice-review-card {
  display: grid;
  gap: 12px;
  margin-bottom: 20px;
}

.rf-voice-active-number {
  padding: 16px 18px;
  border-radius: 16px;
  background: #ecfdf5;
  color: #065f46;
}

.rf-voice-summary-strip,
.rf-voice-review-card {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.rf-voice-review-card {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.rf-voice-summary-strip > div,
.rf-voice-review-card > div {
  display: grid;
  gap: 4px;
  padding: 15px 16px;
  border-radius: 15px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
}

.rf-voice-summary-strip small,
.rf-voice-review-card small {
  color: #64748b;
}

.rf-voice-policy-check {
  display: flex;
  gap: 13px;
  align-items: flex-start;
  padding: 18px;
  margin-bottom: 12px;
  border: 1px solid rgba(99, 102, 241, 0.28);
  border-radius: 17px;
  background: rgba(238, 242, 255, 0.54);
  cursor: pointer;
}

.rf-voice-policy-check.secondary {
  border-color: #e2e8f0;
  background: #f8fafc;
}

.rf-voice-policy-check input {
  margin-top: 3px;
  width: 18px;
  height: 18px;
}

.rf-voice-policy-check span {
  display: grid;
  gap: 5px;
}

.rf-voice-policy-check small {
  color: #64748b;
  line-height: 1.5;
}

.rf-voice-inline-warning {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  padding: 14px 16px;
  margin-top: 18px;
  border: 1px solid #fed7aa;
  border-radius: 14px;
  background: #fff7ed;
  color: #9a3412;
}

.rf-voice-legal-note {
  display: block;
  margin-top: 20px;
  color: #94a3b8;
  line-height: 1.5;
}

.rf-voice-success-panel {
  display: flex;
  gap: 14px;
  align-items: center;
  padding: 24px;
  border-radius: 18px;
  background: #ecfdf5;
  color: #065f46;
}

.rf-voice-success-panel > span {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #22c55e;
  color: white;
  font-weight: 900;
}

.rf-voice-success-panel p {
  margin: 4px 0 0;
  color: #047857;
}

@media (max-width: 820px) {
  .rf-voice-wizard-top,
  .rf-voice-wizard-body {
    padding-left: 20px;
    padding-right: 20px;
  }

  .rf-voice-progress {
    padding-left: 20px;
    padding-right: 20px;
    overflow-x: auto;
  }

  .rf-voice-essential-grid,
  .rf-voice-essential-grid.two,
  .rf-voice-number-grid,
  .rf-voice-credit-grid,
  .rf-voice-summary-strip,
  .rf-voice-review-card {
    grid-template-columns: 1fr;
  }

  .rf-voice-wizard-top {
    align-items: flex-start;
  }

  .rf-voice-progress {
    min-width: 520px;
  }
}


/* ========================================================================== 
   ReachFly Voice Setup V2 — guided single-card experience
   ========================================================================== */

.rf-voice-setup-shell {
  --voice-ink: #11182f;
  --voice-muted: #6c7489;
  --voice-line: rgba(76, 68, 138, 0.12);
  --voice-purple: #6d4aff;
  --voice-violet: #8b5cf6;
  --voice-pink: #f449ad;
  --voice-blue: #3f7cff;
  --voice-green: #16a875;
  position: relative;
  overflow: hidden;
  width: 100%;
  border: 1px solid rgba(109, 74, 255, 0.12);
  border-radius: 30px;
  background:
    radial-gradient(circle at 92% 2%, rgba(109, 74, 255, 0.13), transparent 28rem),
    radial-gradient(circle at 4% 26%, rgba(244, 73, 173, 0.07), transparent 25rem),
    linear-gradient(180deg, rgba(255,255,255,.98), rgba(249,249,255,.98));
  box-shadow: 0 28px 80px rgba(35, 26, 78, 0.09);
}

.rf-voice-setup-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .35;
  background-image:
    linear-gradient(rgba(103, 89, 183, .035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(103, 89, 183, .035) 1px, transparent 1px);
  background-size: 34px 34px;
  mask-image: linear-gradient(to bottom, #000, transparent 58%);
}

.rf-voice-setup-hero {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 220px;
  gap: 28px;
  align-items: center;
  padding: 34px 38px 24px;
}

.rf-voice-setup-hero h2 {
  max-width: 720px;
  margin: 9px 0 8px;
  color: var(--voice-ink);
  font-size: clamp(1.65rem, 3vw, 2.55rem);
  line-height: 1.04;
  letter-spacing: -.045em;
}

.rf-voice-setup-hero p {
  max-width: 720px;
  margin: 0;
  color: var(--voice-muted);
  font-size: .94rem;
  line-height: 1.65;
}

.rf-voice-credit-orb {
  position: relative;
  overflow: hidden;
  display: grid;
  justify-items: end;
  min-height: 132px;
  padding: 21px 22px;
  border: 1px solid rgba(255,255,255,.2);
  border-radius: 23px;
  color: #fff;
  background:
    radial-gradient(circle at 15% 0%, rgba(255,255,255,.22), transparent 7rem),
    linear-gradient(135deg, #5c3df0, #894cf2 48%, #ec4bab 100%);
  box-shadow: 0 20px 44px rgba(109,74,255,.22);
}

.rf-voice-credit-orb::after {
  content: "";
  position: absolute;
  width: 120px;
  height: 120px;
  left: -32px;
  bottom: -56px;
  border: 22px solid rgba(255,255,255,.1);
  border-radius: 50%;
}

.rf-voice-credit-orb span,
.rf-voice-credit-orb small,
.rf-voice-credit-orb strong {
  position: relative;
  z-index: 1;
}

.rf-voice-credit-orb span {
  font-size: .68rem;
  font-weight: 850;
  letter-spacing: .095em;
  text-transform: uppercase;
  opacity: .82;
}

.rf-voice-credit-orb strong {
  margin-top: 4px;
  font-size: 2.6rem;
  line-height: 1;
  letter-spacing: -.06em;
}

.rf-voice-credit-orb small {
  max-width: 150px;
  margin-top: 6px;
  text-align: right;
  font-size: .72rem;
  line-height: 1.35;
  opacity: .78;
}

.rf-voice-setup-progress {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 9px;
  padding: 0 38px 26px;
}

.rf-voice-setup-progress button {
  appearance: none;
  min-width: 0;
  min-height: 74px;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  grid-template-rows: auto auto;
  column-gap: 10px;
  align-items: center;
  padding: 11px 12px;
  border: 1px solid var(--voice-line);
  border-radius: 16px;
  color: #72798b;
  background: rgba(255,255,255,.64);
  text-align: left;
  box-shadow: inset 0 1px rgba(255,255,255,.8);
  transition: transform .16s ease, border-color .16s ease, background .16s ease, box-shadow .16s ease;
}

.rf-voice-setup-progress button > span {
  grid-row: 1 / 3;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid #ddd9ef;
  border-radius: 11px;
  background: #fff;
  font-size: .72rem;
  font-weight: 900;
}

.rf-voice-setup-progress button b {
  align-self: end;
  color: #42495c;
  font-size: .78rem;
  line-height: 1.05;
}

.rf-voice-setup-progress button small {
  align-self: start;
  overflow: hidden;
  color: #9298a8;
  font-size: .61rem;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-voice-setup-progress button.current {
  border-color: rgba(109,74,255,.32);
  color: var(--voice-purple);
  background: linear-gradient(180deg, #fff, #f4f0ff);
  box-shadow: 0 11px 28px rgba(109,74,255,.10);
  transform: translateY(-2px);
}

.rf-voice-setup-progress button.current > span {
  border-color: transparent;
  color: #fff;
  background: linear-gradient(135deg, var(--voice-purple), var(--voice-pink));
  box-shadow: 0 8px 18px rgba(109,74,255,.22);
}

.rf-voice-setup-progress button.current b { color: #38279b; }

.rf-voice-setup-progress button.done {
  cursor: pointer;
  color: #087a55;
  background: rgba(236,253,245,.78);
  border-color: rgba(22,168,117,.18);
}

.rf-voice-setup-progress button.done > span {
  border-color: rgba(22,168,117,.2);
  color: #fff;
  background: #19ad79;
}

.rf-voice-setup-stage {
  position: relative;
  z-index: 1;
  margin: 0 22px 22px;
  border: 1px solid rgba(83,73,137,.11);
  border-radius: 24px;
  background: rgba(255,255,255,.92);
  box-shadow: 0 16px 48px rgba(35,26,78,.06);
}

.rf-voice-setup-stage-head {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding: 28px 30px 20px;
  border-bottom: 1px solid rgba(83,73,137,.08);
}

.rf-voice-setup-stage-head > div > span {
  color: var(--voice-purple);
  font-size: .66rem;
  font-weight: 900;
  letter-spacing: .095em;
  text-transform: uppercase;
}

.rf-voice-setup-stage-head h3 {
  max-width: 760px;
  margin: 7px 0 6px;
  color: var(--voice-ink);
  font-size: clamp(1.28rem, 2.4vw, 1.75rem);
  line-height: 1.15;
  letter-spacing: -.035em;
}

.rf-voice-setup-stage-head p {
  max-width: 760px;
  margin: 0;
  color: var(--voice-muted);
  font-size: .86rem;
  line-height: 1.58;
}

.rf-voice-setup-step-number {
  flex: 0 0 auto;
  color: rgba(109,74,255,.22);
  font-size: 2.2rem;
  font-weight: 950;
  line-height: 1;
  letter-spacing: -.06em;
}

.rf-voice-setup-pane {
  min-height: 330px;
  padding: 27px 30px 30px;
  animation: rfVoicePaneIn .22s ease both;
}

@keyframes rfVoicePaneIn {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: translateY(0); }
}

.rf-voice-auto-card {
  display: grid;
  grid-template-columns: 1.2fr 1fr auto;
  gap: 13px;
  align-items: center;
  margin-top: 18px;
  padding: 16px;
  border: 1px solid #e7e3f2;
  border-radius: 18px;
  background: linear-gradient(180deg, #faf9ff, #f6f5fb);
}

.rf-voice-auto-card > span {
  grid-column: 1 / -1;
  color: #8a8298;
  font-size: .66rem;
  font-weight: 850;
  letter-spacing: .075em;
  text-transform: uppercase;
}

.rf-voice-auto-card > div {
  display: grid;
  gap: 3px;
}

.rf-voice-auto-card b { color: #262c3e; font-size: .84rem; }
.rf-voice-auto-card small { color: #83899a; font-size: .69rem; }

.rf-voice-intel-summary,
.rf-voice-skip-card {
  display: grid;
  gap: 8px;
  margin-top: 20px;
  padding: 19px;
  border-radius: 18px;
}

.rf-voice-intel-summary {
  border: 1px solid rgba(22,168,117,.18);
  background: linear-gradient(180deg, #f3fff9, #f8fffb);
}

.rf-voice-intel-summary > span {
  width: fit-content;
  padding: 5px 8px;
  border-radius: 999px;
  color: #087652;
  background: rgba(22,168,117,.1);
  font-size: .65rem;
  font-weight: 900;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.rf-voice-intel-summary strong {
  color: #173d31;
  font-size: 1rem;
  line-height: 1.45;
}

.rf-voice-intel-summary small,
.rf-voice-skip-card span {
  color: #70798b;
  line-height: 1.55;
}

.rf-voice-skip-card {
  border: 1px dashed rgba(109,74,255,.20);
  background: #faf9ff;
}

.rf-voice-skip-card b { color: #40368a; }

.rf-voice-calling-identity {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: center;
  margin-bottom: 18px;
  padding: 18px 20px;
  border: 1px solid rgba(109,74,255,.14);
