.cu-problem-section {
  position: relative;
}

.cu-problem-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin-top: 40px;
}

.cu-problem-card {
  position: relative;
  min-height: 285px;
  overflow: hidden;
  padding: 24px;
  border: 1px solid rgba(31, 24, 51, 0.09);
  border-radius: 20px;
  background:
    radial-gradient(circle at 100% 100%, rgba(111, 66, 245, 0.09), transparent 14rem),
    #fff;
  box-shadow: 0 16px 45px rgba(31, 24, 51, 0.055);
}

.cu-problem-card::after {
  content: "";
  position: absolute;
  right: -52px;
  bottom: -72px;
  width: 150px;
  height: 150px;
  border-radius: 50%;
  border: 28px solid rgba(111, 66, 245, 0.045);
}

.cu-card-number {
  display: inline-flex;
  margin-bottom: 52px;
  color: #7b5ae9;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.cu-problem-card h3 {
  max-width: 240px;
  margin: 0 0 12px;
  color: #17131f;
  font-size: 20px;
  line-height: 1.12;
  letter-spacing: -0.035em;
}

.cu-problem-card p {
  position: relative;
  z-index: 2;
  margin: 0;
  color: #706b79;
  font-size: 13px;
  line-height: 1.62;
}

/* ---------------- Platform flow ---------------- */

.cu-platform-v2 {
  position: relative;
}

.cu-platform-flow {
  position: relative;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0;
  margin-top: 48px;
}

.cu-platform-flow-line {
  position: absolute;
  z-index: 0;
  top: 24px;
  left: 10%;
  right: 10%;
  height: 2px;
  background: linear-gradient(
    90deg,
    rgba(111, 66, 245, 0.20),
    #6f42f5,
    #e84eaa,
    rgba(255, 138, 92, 0.30)
  );
}

.cu-platform-flow article {
  position: relative;
  z-index: 1;
  display: grid;
  justify-items: center;
  gap: 13px;
  padding: 0 14px;
  text-align: center;
}

.cu-platform-flow article > span {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  color: #fff;
  background: linear-gradient(135deg, #6f42f5, #e84eaa);
  box-shadow: 0 10px 26px rgba(111, 66, 245, 0.22);
  font-size: 11px;
  font-weight: 850;
}

.cu-platform-flow h3 {
  margin: 0 0 5px;
  font-size: 15px;
}

.cu-platform-flow p {
  margin: 0;
  color: #77717f;
  font-size: 11px;
  line-height: 1.55;
}

/* ---------------- Voice comparison ---------------- */

.cu-voice-v2 {
  padding-top: clamp(84px, 9vw, 126px) !important;
  padding-bottom: clamp(84px, 9vw, 126px) !important;
}

.cu-voice-compare {
  width: min(1050px, 100%);
  margin: 44px auto 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.cu-voice-compare-card {
  min-height: 360px;
  padding: 30px;
  border-radius: 24px;
}

.cu-voice-compare-card.muted {
  border: 1px solid rgba(255, 255, 255, 0.07);
  color: rgba(255, 255, 255, 0.74);
  background: rgba(255, 255, 255, 0.035);
}

.cu-voice-compare-card.featured {
  color: #fff;
  border: 1px solid rgba(165, 129, 255, 0.32);
  background:
    radial-gradient(circle at 100% 0, rgba(232, 78, 170, 0.18), transparent 18rem),
    linear-gradient(145deg, rgba(111, 66, 245, 0.20), rgba(255, 255, 255, 0.055));
  box-shadow: 0 30px 70px rgba(0, 0, 0, 0.20);
}

.cu-compare-label {
  display: inline-flex;
  padding: 7px 10px;
  border-radius: 999px;
  color: #cdbdff;
  background: rgba(111, 66, 245, 0.14);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.cu-voice-compare-card h3 {
  max-width: 420px;
  margin: 26px 0;
  color: inherit;
  font-size: clamp(26px, 3vw, 38px);
  line-height: 1.04;
  letter-spacing: -0.055em;
}

.cu-voice-compare-card ul {
  display: grid;
  gap: 14px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.cu-voice-compare-card li {
  position: relative;
  padding-left: 25px;
  font-size: 13px;
  line-height: 1.5;
}

.cu-voice-compare-card li::before {
  content: "✓";
  position: absolute;
  left: 0;
  color: #a98cff;
  font-weight: 900;
}

/* ---------------- Process ---------------- */

.cu-process-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-top: 44px;
}

.cu-process-card {
  position: relative;
  min-height: 270px;
  padding: 24px;
  border: 1px solid rgba(31, 24, 51, 0.09);
  border-radius: 20px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(249, 248, 253, 0.96));
  box-shadow: 0 14px 40px rgba(31, 24, 51, 0.05);
}

.cu-process-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.cu-process-icon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  color: #633ce5;
  background: #f1edff;
}

.cu-process-top em {
  color: #c3b8e8;
  font-size: 20px;
  font-style: normal;
  font-weight: 800;
}

.cu-process-card h3 {
  margin: 54px 0 10px;
  font-size: 18px;
  line-height: 1.15;
  letter-spacing: -0.035em;
}

.cu-process-card p {
  margin: 0;
  color: #746e7d;
  font-size: 12px;
  line-height: 1.6;
}

.cu-process-arrow {
  position: absolute;
  right: -12px;
  top: 50%;
  z-index: 3;
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #fff;
  background: #6f42f5;
  box-shadow: 0 5px 16px rgba(111, 66, 245, 0.24);
}

/* ---------------- Outcomes ---------------- */

.cu-outcome-section {
  padding-top: clamp(84px, 9vw, 126px) !important;
  padding-bottom: clamp(84px, 9vw, 126px) !important;
}

.cu-outcome-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 13px;
  margin-top: 42px;
}

.cu-outcome-card {
  position: relative;
  min-height: 245px;
  padding: 22px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 18px;
  background:
    radial-gradient(circle at 100% 100%, rgba(111, 66, 245, 0.18), transparent 15rem),
    rgba(255, 255, 255, 0.035);
}

.cu-outcome-card > span {
  position: absolute;
  right: 18px;
  top: 18px;
  color: rgba(255, 255, 255, 0.22);
  font-size: 16px;
  font-weight: 850;
}

.cu-outcome-icon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  color: #d8ccff;
  background: rgba(111, 66, 245, 0.14);
}

.cu-outcome-card h3 {
  margin: 52px 0 9px;
  color: #fff;
  font-size: 17px;
}

.cu-outcome-card p {
  margin: 0;
  color: rgba(239, 235, 247, 0.61);
  font-size: 12px;
  line-height: 1.58;
}

/* ---------------- Operators ---------------- */

.cu-operator-grid {
  margin-top: 42px;
}

.cu-operator-card {
  min-height: 270px !important;
}

.cu-operator-card h3 {
  margin-top: 48px !important;
}

/* ---------------- Safeguards ---------------- */

.cu-safety-v2 {
  padding-top: clamp(82px, 9vw, 122px) !important;
  padding-bottom: clamp(82px, 9vw, 122px) !important;
}

.cu-safeguard-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-top: 42px;
}

.cu-safeguard-grid article {
  position: relative;
  min-height: 155px;
  padding: 20px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 17px;
  background: rgba(255, 255, 255, 0.035);
}

.cu-safeguard-grid article > span {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  color: #d3c4ff;
  background: rgba(111, 66, 245, 0.13);
}

.cu-safeguard-grid em {
  position: absolute;
  top: 20px;
  right: 20px;
  color: rgba(255, 255, 255, 0.20);
  font-style: normal;
  font-size: 12px;
}

.cu-safeguard-grid h3 {
  margin: 34px 0 0;
  color: #fff;
  font-size: 14px;
  line-height: 1.35;
}

/* ---------------- Pricing ---------------- */

.cu-pricing-v2 .cu-price-grid {
  align-items: stretch;
}

.cu-price-eyebrow {
  display: inline-flex;
  width: max-content;
  margin-bottom: 16px;
  color: #7251e5;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.cu-pricing-footnote {
  max-width: 760px;
  margin: 24px auto 0;
  color: #89838f;
  text-align: center;
  font-size: 10px;
  line-height: 1.55;
}

/* ---------------- Final CTA ---------------- */

.cu-final-v2 {
  margin-bottom: 0 !important;
}

.cu-final-v2 h2 {
  max-width: 980px !important;
}

.cu-final-v2 p {
  max-width: 800px !important;
}

/* ---------------- Footer ---------------- */

.cu-footer-v2 {
  margin-top: 56px;
  color: #d8d2e5;
  background:
    radial-gradient(circle at 8% 0, rgba(111, 66, 245, 0.17), transparent 26rem),
    linear-gradient(180deg, #111019, #09080d);
  border-top: 1px solid rgba(255, 255, 255, 0.07);
}

.cu-footer-v2-main {
  width: min(1240px, calc(100% - 44px));
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(280px, 1fr) minmax(480px, 1.3fr);
  gap: clamp(60px, 9vw, 140px);
  padding: 62px 0 50px;
}

.cu-footer-v2 .cu-brand {
  width: max-content;
  color: #fff;
}

.cu-footer-v2-brand > p {
  max-width: 450px;
  margin: 22px 0;
  color: rgba(230, 224, 238, 0.57);
  font-size: 13px;
  line-height: 1.65;
}

.cu-footer-trust {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 16px;
}

.cu-footer-trust span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #a9a2b4;
  font-size: 10px;
  font-weight: 650;
}

.cu-footer-v2-links {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 34px;
}

.cu-footer-v2-links > div {
  display: grid;
  align-content: start;
  gap: 10px;
}

.cu-footer-v2-links h4 {
  margin: 0 0 8px;
  color: #fff;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.11em;
}

.cu-footer-v2-links a {
  width: max-content;
  color: #a39cab;
  font-size: 12px;
  text-decoration: none;
  transition: color 160ms ease, transform 160ms ease;
}

.cu-footer-v2-links a:hover {
  color: #fff;
  transform: translateX(2px);
}

.cu-footer-v2-bottom {
  width: min(1240px, calc(100% - 44px));
  margin: 0 auto;
  padding: 18px 0 28px;
  display: flex;
  justify-content: space-between;
  gap: 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
  color: #817a89;
  font-size: 10px;
}

/* ---------------- Responsive ---------------- */

@media (max-width: 1180px) {
  .cu-hero-v2 .cu-hero-inner {
    grid-template-columns: 1fr !important;
    gap: 38px !important;
  }

  .cu-hero-v2 .cu-hero-copy {
    max-width: 850px;
    margin: 0 auto;
    text-align: center;
  }

  .cu-kicker-v2 {
    margin-left: auto;
    margin-right: auto;
  }

  .cu-hero-v2 h1,
  .cu-hero-v2 .cu-hero-lead {
    margin-left: auto !important;
    margin-right: auto !important;
  }

  .cu-proof-row-v2 {
    justify-content: center;
    grid-template-columns: repeat(2, max-content);
  }

  .cu-preview-v2 {
    max-width: 820px !important;
    margin: 0 auto !important;
  }

  .cu-problem-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .cu-platform-flow {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 28px 0;
  }

  .cu-platform-flow-line {
    display: none;
  }

  .cu-process-grid,
  .cu-outcome-grid,
  .cu-safeguard-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .cu-process-arrow {
    display: none;
  }
}

@media (max-width: 800px) {
  .cu-hero-v2 {
    padding-top: 38px !important;
  }

  .cu-hero-v2 h1 {
    font-size: clamp(44px, 11vw, 64px) !important;
  }

  .cu-hero-lead {
    font-size: 15px !important;
  }

  .cu-proof-row-v2 {
    grid-template-columns: 1fr;
    justify-items: start;
    width: min(520px, 100%);
    margin-left: auto;
    margin-right: auto;
  }

  .cu-chip-strip-after-hero {
    min-height: 52px;
  }

  .cu-problem-grid,
  .cu-voice-compare,
  .cu-process-grid,
  .cu-outcome-grid,
  .cu-safeguard-grid,
  .cu-footer-v2-main,
  .cu-footer-v2-links {
    grid-template-columns: 1fr;
  }

  .cu-platform-flow {
    grid-template-columns: 1fr;
  }

  .cu-platform-flow article {
    grid-template-columns: 48px 1fr;
    justify-items: start;
    text-align: left;
  }

  .cu-platform-flow article > div {
    align-self: center;
  }

  .cu-problem-card {
    min-height: 230px;
  }

  .cu-card-number {
    margin-bottom: 32px;
  }

  .cu-process-card,
  .cu-outcome-card {
    min-height: 220px;
  }

  .cu-footer-v2-main {
    gap: 42px;
    padding-top: 46px;
  }

  .cu-footer-v2-links {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .cu-footer-v2-bottom {
    flex-direction: column;
  }
}

@media (max-width: 540px) {
  .cu-story-section,
  .cu-process-section,
  .cu-operators-section {
    width: min(100% - 30px, 1240px);
    padding: 68px 0;
  }

  .cu-hero-v2 h1 {
    font-size: clamp(42px, 13vw, 56px) !important;
  }

  .cu-footer-v2-main,
  .cu-footer-v2-bottom {
    width: calc(100% - 30px);
  }

  .cu-footer-v2-links {
    grid-template-columns: 1fr 1fr;
  }
}
/* ReachFly guided Voice Agent onboarding */
.rf-voice-wizard {
  max-width: 980px;
  margin: 0 auto 28px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  border-radius: 28px;
  background:
    radial-gradient(circle at top right, rgba(99, 102, 241, 0.13), transparent 32%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.98));
  box-shadow: 0 24px 70px rgba(15, 23, 42, 0.10);
  overflow: hidden;
}

.rf-voice-wizard-top {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding: 34px 38px 24px;
}

.rf-voice-wizard-top h2 {
  margin: 7px 0 8px;
  font-size: clamp(1.6rem, 3vw, 2.35rem);
  line-height: 1.12;
  letter-spacing: -0.035em;
}

.rf-voice-wizard-top p {
  max-width: 650px;
  margin: 0;
  color: #64748b;
  line-height: 1.65;
}

.rf-voice-wizard-kicker {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 11px;
  border-radius: 999px;
  background: rgba(79, 70, 229, 0.09);
  color: #4338ca;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.rf-voice-wizard-step-count {
  flex: 0 0 auto;
  height: 38px;
  padding: 0 14px;
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  background: #0f172a;
  color: white;
  font-weight: 800;
}

.rf-voice-progress {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  padding: 0 38px 28px;
}

.rf-voice-progress-item {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 7px;
  color: #94a3b8;
}

.rf-voice-progress-item::before {
  content: "";
  position: absolute;
  top: 16px;
  left: calc(-50% + 22px);
  width: calc(100% - 12px);
  height: 2px;
  background: #e2e8f0;
}

.rf-voice-progress-item:first-child::before {
  display: none;
}

.rf-voice-progress-item span {
  position: relative;
  z-index: 1;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 2px solid #e2e8f0;
  background: white;
  font-size: 0.8rem;
  font-weight: 900;
}

.rf-voice-progress-item small {
  font-size: 0.72rem;
  font-weight: 800;
}

.rf-voice-progress-item.done,
.rf-voice-progress-item.current {
  color: #4338ca;
}

.rf-voice-progress-item.done span {
  border-color: #22c55e;
  background: #22c55e;
  color: white;
}

.rf-voice-progress-item.done::before,
.rf-voice-progress-item.current::before {
  background: linear-gradient(90deg, #22c55e, #6366f1);
}

.rf-voice-progress-item.current span {
  border-color: #6366f1;
  box-shadow: 0 0 0 5px rgba(99, 102, 241, 0.10);
}

.rf-voice-wizard-body {
  border-top: 1px solid #e2e8f0;
  padding: 30px 38px 38px;
}

.rf-voice-wizard-note {
  display: grid;
  gap: 5px;
  padding: 15px 17px;
  margin-bottom: 22px;
  border: 1px solid rgba(99, 102, 241, 0.16);
  border-radius: 16px;
  background: rgba(238, 242, 255, 0.72);
}

.rf-voice-wizard-note b {
  color: #312e81;
}

.rf-voice-wizard-note span {
  color: #64748b;
  line-height: 1.5;
}

.rf-voice-essential-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.rf-voice-essential-grid.two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.rf-voice-wizard-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 22px;
}

.rf-voice-wizard-actions.end {
  justify-content: flex-end;
}

.rf-voice-wizard-actions.split {
  justify-content: space-between;
}

.rf-voice-primary-action {
  min-width: 190px;
}

.rf-voice-number-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-top: 24px;
}

.rf-voice-number-card,
.rf-voice-credit-card {
  display: grid;
  gap: 16px;
  padding: 20px;
  border: 1px solid #e2e8f0;
  border-radius: 19px;
  background: white;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.05);
}

.rf-voice-number-card:hover,
.rf-voice-credit-card:hover {
  border-color: rgba(99, 102, 241, 0.42);
  transform: translateY(-1px);
}

.rf-voice-number-card h3,
.rf-voice-credit-card h3 {
  margin: 7px 0 3px;
  font-size: 1.18rem;
}

.rf-voice-number-card p,
.rf-voice-credit-card p {
  margin: 0;
  color: #64748b;
}

.rf-voice-number-badge {
  width: fit-content;
  padding: 5px 9px;
  border-radius: 999px;
  background: #ecfdf5;
  color: #047857;
  font-size: 0.7rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.rf-voice-number-price {
  display: grid;
  gap: 3px;
}

.rf-voice-number-price b {
  font-size: 1.35rem;
}

.rf-voice-number-price small,
.rf-voice-number-price span {
  color: #64748b;
}

.rf-voice-credit-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.rf-voice-credit-card.recommended {
  border-color: rgba(99, 102, 241, 0.42);
  background: linear-gradient(180deg, #fff, #f5f7ff);
}

.rf-voice-credit-card > b {
  font-size: 1.45rem;
}

.rf-voice-credit-card small {
  color: #64748b;
}

.rf-voice-active-number,
.rf-voice-summary-strip,
.rf-voice-review-card {
  display: grid;
  gap: 12px;
  margin-bottom: 20px;
}

.rf-voice-active-number {
  padding: 16px 18px;
  border-radius: 16px;
  background: #ecfdf5;
  color: #065f46;
}

.rf-voice-summary-strip,
.rf-voice-review-card {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.rf-voice-review-card {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.rf-voice-summary-strip > div,
.rf-voice-review-card > div {
  display: grid;
  gap: 4px;
  padding: 15px 16px;
  border-radius: 15px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
}

.rf-voice-summary-strip small,
.rf-voice-review-card small {
  color: #64748b;
}

.rf-voice-policy-check {
  display: flex;
  gap: 13px;
  align-items: flex-start;
  padding: 18px;
  margin-bottom: 12px;
  border: 1px solid rgba(99, 102, 241, 0.28);
  border-radius: 17px;
  background: rgba(238, 242, 255, 0.54);
  cursor: pointer;
}

.rf-voice-policy-check.secondary {
  border-color: #e2e8f0;
  background: #f8fafc;
}

.rf-voice-policy-check input {
  margin-top: 3px;
  width: 18px;
  height: 18px;
}

.rf-voice-policy-check span {
  display: grid;
  gap: 5px;
}

.rf-voice-policy-check small {
  color: #64748b;
  line-height: 1.5;
}

.rf-voice-inline-warning {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  padding: 14px 16px;
  margin-top: 18px;
  border: 1px solid #fed7aa;
  border-radius: 14px;
  background: #fff7ed;
  color: #9a3412;
}

.rf-voice-legal-note {
  display: block;
  margin-top: 20px;
  color: #94a3b8;
  line-height: 1.5;
}

.rf-voice-success-panel {
  display: flex;
  gap: 14px;
  align-items: center;
  padding: 24px;
  border-radius: 18px;
  background: #ecfdf5;
  color: #065f46;
}

.rf-voice-success-panel > span {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #22c55e;
  color: white;
  font-weight: 900;
}

.rf-voice-success-panel p {
  margin: 4px 0 0;
  color: #047857;
}

@media (max-width: 820px) {
  .rf-voice-wizard-top,
  .rf-voice-wizard-body {
    padding-left: 20px;
    padding-right: 20px;
  }

  .rf-voice-progress {
    padding-left: 20px;
    padding-right: 20px;
    overflow-x: auto;
  }

  .rf-voice-essential-grid,
  .rf-voice-essential-grid.two,
  .rf-voice-number-grid,
  .rf-voice-credit-grid,
  .rf-voice-summary-strip,
  .rf-voice-review-card {
    grid-template-columns: 1fr;
  }

  .rf-voice-wizard-top {
    align-items: flex-start;
  }

  .rf-voice-progress {
    min-width: 520px;
  }
}


/* ========================================================================== 
   ReachFly Voice Setup V2 — guided single-card experience
   ========================================================================== */

.rf-voice-setup-shell {
  --voice-ink: #11182f;
  --voice-muted: #6c7489;
  --voice-line: rgba(76, 68, 138, 0.12);
  --voice-purple: #6d4aff;
  --voice-violet: #8b5cf6;
  --voice-pink: #f449ad;
  --voice-blue: #3f7cff;
  --voice-green: #16a875;
  position: relative;
  overflow: hidden;
  width: 100%;
  border: 1px solid rgba(109, 74, 255, 0.12);
  border-radius: 30px;
  background:
    radial-gradient(circle at 92% 2%, rgba(109, 74, 255, 0.13), transparent 28rem),
    radial-gradient(circle at 4% 26%, rgba(244, 73, 173, 0.07), transparent 25rem),
    linear-gradient(180deg, rgba(255,255,255,.98), rgba(249,249,255,.98));
  box-shadow: 0 28px 80px rgba(35, 26, 78, 0.09);
}

.rf-voice-setup-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .35;
  background-image:
    linear-gradient(rgba(103, 89, 183, .035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(103, 89, 183, .035) 1px, transparent 1px);
  background-size: 34px 34px;
  mask-image: linear-gradient(to bottom, #000, transparent 58%);
}

.rf-voice-setup-hero {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 220px;
  gap: 28px;
  align-items: center;
  padding: 34px 38px 24px;
}

.rf-voice-setup-hero h2 {
  max-width: 720px;
  margin: 9px 0 8px;
  color: var(--voice-ink);
  font-size: clamp(1.65rem, 3vw, 2.55rem);
  line-height: 1.04;
  letter-spacing: -.045em;
}

.rf-voice-setup-hero p {
  max-width: 720px;
  margin: 0;
  color: var(--voice-muted);
  font-size: .94rem;
  line-height: 1.65;
}

.rf-voice-credit-orb {
  position: relative;
  overflow: hidden;
  display: grid;
  justify-items: end;
  min-height: 132px;
  padding: 21px 22px;
  border: 1px solid rgba(255,255,255,.2);
  border-radius: 23px;
  color: #fff;
  background:
    radial-gradient(circle at 15% 0%, rgba(255,255,255,.22), transparent 7rem),
    linear-gradient(135deg, #5c3df0, #894cf2 48%, #ec4bab 100%);
  box-shadow: 0 20px 44px rgba(109,74,255,.22);
}

.rf-voice-credit-orb::after {
  content: "";
  position: absolute;
  width: 120px;
  height: 120px;
  left: -32px;
  bottom: -56px;
  border: 22px solid rgba(255,255,255,.1);
  border-radius: 50%;
}

.rf-voice-credit-orb span,
.rf-voice-credit-orb small,
.rf-voice-credit-orb strong {
  position: relative;
  z-index: 1;
}

.rf-voice-credit-orb span {
  font-size: .68rem;
  font-weight: 850;
  letter-spacing: .095em;
  text-transform: uppercase;
  opacity: .82;
}

.rf-voice-credit-orb strong {
  margin-top: 4px;
  font-size: 2.6rem;
  line-height: 1;
  letter-spacing: -.06em;
}

.rf-voice-credit-orb small {
  max-width: 150px;
  margin-top: 6px;
  text-align: right;
  font-size: .72rem;
  line-height: 1.35;
  opacity: .78;
}

.rf-voice-setup-progress {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 9px;
  padding: 0 38px 26px;
}

.rf-voice-setup-progress button {
  appearance: none;
  min-width: 0;
  min-height: 74px;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  grid-template-rows: auto auto;
  column-gap: 10px;
  align-items: center;
  padding: 11px 12px;
  border: 1px solid var(--voice-line);
  border-radius: 16px;
  color: #72798b;
  background: rgba(255,255,255,.64);
  text-align: left;
  box-shadow: inset 0 1px rgba(255,255,255,.8);
  transition: transform .16s ease, border-color .16s ease, background .16s ease, box-shadow .16s ease;
}

.rf-voice-setup-progress button > span {
  grid-row: 1 / 3;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid #ddd9ef;
  border-radius: 11px;
  background: #fff;
  font-size: .72rem;
  font-weight: 900;
}

.rf-voice-setup-progress button b {
  align-self: end;
  color: #42495c;
  font-size: .78rem;
  line-height: 1.05;
}

.rf-voice-setup-progress button small {
  align-self: start;
  overflow: hidden;
  color: #9298a8;
  font-size: .61rem;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-voice-setup-progress button.current {
  border-color: rgba(109,74,255,.32);
  color: var(--voice-purple);
  background: linear-gradient(180deg, #fff, #f4f0ff);
  box-shadow: 0 11px 28px rgba(109,74,255,.10);
  transform: translateY(-2px);
}

.rf-voice-setup-progress button.current > span {
  border-color: transparent;
  color: #fff;
  background: linear-gradient(135deg, var(--voice-purple), var(--voice-pink));
  box-shadow: 0 8px 18px rgba(109,74,255,.22);
}

.rf-voice-setup-progress button.current b { color: #38279b; }

.rf-voice-setup-progress button.done {
  cursor: pointer;
  color: #087a55;
  background: rgba(236,253,245,.78);
  border-color: rgba(22,168,117,.18);
}

.rf-voice-setup-progress button.done > span {
  border-color: rgba(22,168,117,.2);
  color: #fff;
  background: #19ad79;
}

.rf-voice-setup-stage {
  position: relative;
  z-index: 1;
  margin: 0 22px 22px;
  border: 1px solid rgba(83,73,137,.11);
  border-radius: 24px;
  background: rgba(255,255,255,.92);
  box-shadow: 0 16px 48px rgba(35,26,78,.06);
}

.rf-voice-setup-stage-head {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding: 28px 30px 20px;
  border-bottom: 1px solid rgba(83,73,137,.08);
}

.rf-voice-setup-stage-head > div > span {
  color: var(--voice-purple);
  font-size: .66rem;
  font-weight: 900;
  letter-spacing: .095em;
  text-transform: uppercase;
}

.rf-voice-setup-stage-head h3 {
  max-width: 760px;
  margin: 7px 0 6px;
  color: var(--voice-ink);
  font-size: clamp(1.28rem, 2.4vw, 1.75rem);
  line-height: 1.15;
  letter-spacing: -.035em;
}

.rf-voice-setup-stage-head p {
  max-width: 760px;
  margin: 0;
  color: var(--voice-muted);
  font-size: .86rem;
  line-height: 1.58;
}

.rf-voice-setup-step-number {
  flex: 0 0 auto;
  color: rgba(109,74,255,.22);
  font-size: 2.2rem;
  font-weight: 950;
  line-height: 1;
  letter-spacing: -.06em;
}

.rf-voice-setup-pane {
  min-height: 330px;
  padding: 27px 30px 30px;
  animation: rfVoicePaneIn .22s ease both;
}

@keyframes rfVoicePaneIn {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: translateY(0); }
}

.rf-voice-auto-card {
  display: grid;
  grid-template-columns: 1.2fr 1fr auto;
  gap: 13px;
  align-items: center;
  margin-top: 18px;
  padding: 16px;
  border: 1px solid #e7e3f2;
  border-radius: 18px;
  background: linear-gradient(180deg, #faf9ff, #f6f5fb);
}

.rf-voice-auto-card > span {
  grid-column: 1 / -1;
  color: #8a8298;
  font-size: .66rem;
  font-weight: 850;
  letter-spacing: .075em;
  text-transform: uppercase;
}

.rf-voice-auto-card > div {
  display: grid;
  gap: 3px;
}

.rf-voice-auto-card b { color: #262c3e; font-size: .84rem; }
.rf-voice-auto-card small { color: #83899a; font-size: .69rem; }

.rf-voice-intel-summary,
.rf-voice-skip-card {
  display: grid;
  gap: 8px;
  margin-top: 20px;
  padding: 19px;
  border-radius: 18px;
}

.rf-voice-intel-summary {
  border: 1px solid rgba(22,168,117,.18);
  background: linear-gradient(180deg, #f3fff9, #f8fffb);
}

.rf-voice-intel-summary > span {
  width: fit-content;
  padding: 5px 8px;
  border-radius: 999px;
  color: #087652;
  background: rgba(22,168,117,.1);
  font-size: .65rem;
  font-weight: 900;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.rf-voice-intel-summary strong {
  color: #173d31;
  font-size: 1rem;
  line-height: 1.45;
}

.rf-voice-intel-summary small,
.rf-voice-skip-card span {
  color: #70798b;
  line-height: 1.55;
}

.rf-voice-skip-card {
  border: 1px dashed rgba(109,74,255,.20);
  background: #faf9ff;
}

.rf-voice-skip-card b { color: #40368a; }

.rf-voice-calling-identity {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: center;
  margin-bottom: 18px;
  padding: 18px 20px;
  border: 1px solid rgba(109,74,255,.14);
  border-radius: 19px;
  background:
    radial-gradient(circle at 100% 0%, rgba(109,74,255,.09), transparent 12rem),
    #faf9ff;
}

.rf-voice-calling-identity > div { display: grid; gap: 4px; }
.rf-voice-calling-identity span { color: #7f8596; font-size: .67rem; font-weight: 850; text-transform: uppercase; letter-spacing: .07em; }
.rf-voice-calling-identity strong { color: #171c31; font-size: 1.4rem; letter-spacing: -.035em; }
.rf-voice-calling-identity small { color: #777f92; line-height: 1.4; }
.rf-voice-calling-identity > b {
  flex: 0 0 auto;
  padding: 7px 10px;
  border-radius: 999px;
  color: #087652;
  background: #eafbf3;
  border: 1px solid #c9efdd;
  font-size: .66rem;
  letter-spacing: .08em;
}

.rf-voice-advanced {
  margin-top: 18px;
  border: 1px solid #e7e4ef;
  border-radius: 17px;
  background: #fbfbfd;
}

.rf-voice-advanced summary {
  padding: 14px 16px;
  color: #494f61;
  font-size: .78rem;
  font-weight: 850;
  cursor: pointer;
  user-select: none;
}

.rf-voice-advanced[open] summary {
  border-bottom: 1px solid #ebe8f2;
}

.rf-voice-advanced > :not(summary) {
  margin: 15px 16px;
}

.rf-voice-review-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 18px;
}

.rf-voice-review-grid article {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 15px;
  border: 1px solid #e8e5f0;
  border-radius: 16px;
  background: #fbfbfd;
}

.rf-voice-review-grid span {
  color: #8a91a3;
  font-size: .62rem;
  font-weight: 850;
  letter-spacing: .075em;
  text-transform: uppercase;
}

.rf-voice-review-grid strong {
  overflow: hidden;
  color: #202638;
  font-size: .85rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-voice-review-grid small {
  overflow: hidden;
  color: #878d9d;
  font-size: .67rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-voice-credit-wallet {
  position: relative;
  overflow: hidden;
  padding: 21px;
  border: 1px solid rgba(109,74,255,.15);
  border-radius: 20px;
  background:
    radial-gradient(circle at 100% 0%, rgba(109,74,255,.09), transparent 18rem),
    linear-gradient(180deg, #faf9ff, #fff);
}

.rf-voice-credit-wallet-head {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: end;
}

.rf-voice-credit-wallet-head > div:first-child { display: grid; gap: 3px; }
.rf-voice-credit-wallet-head span { color: #746a92; font-size: .67rem; font-weight: 900; letter-spacing: .08em; text-transform: uppercase; }
.rf-voice-credit-wallet-head strong { color: #211b42; font-size: 2.35rem; line-height: 1; letter-spacing: -.06em; }
.rf-voice-credit-wallet-head small { color: #7b8294; }
.rf-voice-credit-wallet-head > div:last-child { text-align: right; }
.rf-voice-credit-wallet-head > div:last-child b { display: block; color: #5b3cd5; font-size: 1.25rem; }

.rf-voice-credit-meter {
  height: 7px;
  margin: 17px 0 13px;
  overflow: hidden;
  border-radius: 999px;
  background: #ece9f6;
}

.rf-voice-credit-meter span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #6d4aff, #a34df0, #f449ad);
  box-shadow: 0 0 18px rgba(109,74,255,.28);
}

.rf-voice-credit-wallet p {
  margin: 0;
  color: #6f7689;
  font-size: .74rem;
  line-height: 1.55;
}

.rf-voice-credit-pack-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 16px;
}

.rf-voice-credit-pack-row button {
  appearance: none;
  display: grid;
  gap: 3px;
  padding: 13px 14px;
  border: 1px solid #e5e1ef;
  border-radius: 15px;
  color: #3d4050;
  background: #fff;
  text-align: left;
  cursor: pointer;
  transition: transform .15s ease, border-color .15s ease, box-shadow .15s ease;
}

.rf-voice-credit-pack-row button:hover:not(:disabled) {
  transform: translateY(-2px);
  border-color: rgba(109,74,255,.3);
  box-shadow: 0 10px 24px rgba(43,32,91,.08);
}

.rf-voice-credit-pack-row button:disabled { opacity: .55; cursor: not-allowed; }
.rf-voice-credit-pack-row button span { color: #6b7182; font-size: .69rem; font-weight: 800; }
.rf-voice-credit-pack-row button b { color: #2d235a; font-size: .95rem; }
.rf-voice-credit-pack-row button small { color: #8c92a1; font-size: .64rem; }

.rf-voice-activate-button {
  min-height: 52px !important;
  margin-top: 18px;
  border-radius: 15px !important;
}

.rf-voice-setup-nav {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 18px 30px 24px;
  border-top: 1px solid #ece9f3;
}

.rf-voice-arrow-button {
  appearance: none;
  min-width: 170px;
  min-height: 56px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 13px;
  border-radius: 16px;
  text-align: left;
  cursor: pointer;
  transition: transform .16s ease, box-shadow .16s ease, opacity .16s ease;
}

.rf-voice-arrow-button > span {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  font-size: 1.15rem;
  font-weight: 900;
}

.rf-voice-arrow-button > div { display: grid; gap: 1px; min-width: 0; }
.rf-voice-arrow-button small { font-size: .61rem; font-weight: 800; text-transform: uppercase; letter-spacing: .07em; }
.rf-voice-arrow-button b { font-size: .78rem; }

.rf-voice-arrow-button.primary {
  margin-left: auto;
  justify-content: flex-end;
  border: 1px solid transparent;
  color: #fff;
  background: linear-gradient(135deg, #6044ec, #8a4df0 50%, #ef4cae);
  box-shadow: 0 14px 30px rgba(109,74,255,.18);
}

.rf-voice-arrow-button.primary > div { text-align: right; }
.rf-voice-arrow-button.primary > span { background: rgba(255,255,255,.15); }
.rf-voice-arrow-button.primary small { color: rgba(255,255,255,.7); }

.rf-voice-arrow-button.secondary {
  border: 1px solid #e4e1ec;
  color: #454b5d;
  background: #fff;
}

.rf-voice-arrow-button.secondary > span { color: #6d4aff; background: #f3f0ff; }
.rf-voice-arrow-button.secondary small { color: #9095a3; }

.rf-voice-arrow-button:hover:not(:disabled) { transform: translateY(-2px); }
.rf-voice-arrow-button:disabled { opacity: .38; cursor: not-allowed; }

.rf-voice-starter-balance {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
  margin-bottom: 18px;
  padding: 17px 19px;
  border: 1px solid rgba(109,74,255,.14);
  border-radius: 18px;
  background: linear-gradient(135deg, #f7f4ff, #fff7fc);
}

.rf-voice-starter-balance > div { display: grid; gap: 3px; }
.rf-voice-starter-balance span { color: #766c8d; font-size: .65rem; font-weight: 850; letter-spacing: .075em; text-transform: uppercase; }
.rf-voice-starter-balance strong { color: #30236d; font-size: 1.15rem; }
.rf-voice-starter-balance small { color: #7d8495; }
.rf-voice-starter-balance > b {
  flex: 0 0 auto;
  padding: 7px 10px;
  border: 1px solid rgba(109,74,255,.16);
  border-radius: 999px;
  color: #6044d9;
  background: #fff;
  font-size: .63rem;
  letter-spacing: .08em;
}

/* Compact field treatment inside the guided setup. */
.rf-voice-setup-shell .rf-agent-field,
.rf-voice-setup-shell .rf-agent-field-grid,
.rf-voice-setup-shell .field {
  margin-bottom: 0;
}

.rf-voice-setup-shell .rf-agent-field > span,
.rf-voice-setup-shell .field > span {
  margin-bottom: 7px;
  color: #4d5365;
  font-size: .71rem;
  font-weight: 850;
}

.rf-voice-setup-shell input,
.rf-voice-setup-shell select,
.rf-voice-setup-shell textarea {
  border-color: #e1deeb;
  background: rgba(255,255,255,.95);
  box-shadow: inset 0 1px 2px rgba(32,27,62,.02);
}

.rf-voice-setup-shell input:focus,
.rf-voice-setup-shell select:focus,
.rf-voice-setup-shell textarea:focus {
  border-color: rgba(109,74,255,.45);
  box-shadow: 0 0 0 4px rgba(109,74,255,.08);
}

@media (max-width: 1100px) {
  .rf-voice-setup-hero { grid-template-columns: minmax(0, 1fr) 190px; }
  .rf-voice-setup-progress { grid-template-columns: repeat(5, minmax(110px, 1fr)); overflow-x: auto; }
  .rf-voice-review-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 760px) {
  .rf-voice-setup-shell { border-radius: 22px; }
  .rf-voice-setup-hero { grid-template-columns: 1fr; padding: 25px 20px 18px; }
  .rf-voice-credit-orb { min-height: 0; justify-items: start; }
  .rf-voice-credit-orb small { text-align: left; max-width: none; }
  .rf-voice-setup-progress { padding: 0 20px 20px; }
  .rf-voice-setup-stage { margin: 0 10px 10px; border-radius: 19px; }
  .rf-voice-setup-stage-head { padding: 22px 19px 17px; }
