  height: 56px !important;

  padding:
    0
    46px !important;

  border:
    1px solid rgba(52, 41, 75, 0.1) !important;

  border-radius: 14px !important;

  outline: none !important;

  color:
    #18151f !important;

  background:
    rgba(249, 249, 252, 0.88) !important;

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    0 8px 20px rgba(38, 27, 67, 0.025) !important;

  font-size: 13px !important;

  font-weight: 620 !important;

  letter-spacing: -0.01em;

  transition:
    border-color 160ms ease,
    background 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease !important;
}


.rf-auth-field input::placeholder,
.rf-auth-input input::placeholder {
  color:
    #aaa5b2 !important;

  font-weight: 500;
}


/* hover */

.rf-auth-field > div:hover input,
.rf-auth-input:hover input {
  background:
    #fff !important;

  border-color:
    rgba(111, 66, 245, 0.2) !important;
}


/* focus */

.rf-auth-field input:focus,
.rf-auth-input input:focus,
.rf-auth-card .auth-form label input:focus,
.auth-card .auth-form label input:focus {
  border-color:
    rgba(111, 66, 245, 0.52) !important;

  background:
    #fff !important;

  box-shadow:
    0 0 0 4px rgba(111, 66, 245, 0.075),
    0 13px 30px rgba(70, 48, 132, 0.07) !important;
}


.rf-auth-field > div:focus-within svg,
.rf-auth-input:focus-within > svg {
  color:
    #6037e7 !important;

  transform:
    translateY(-50%)
    scale(1.05);
}


/* disabled */

.rf-auth-field input:disabled {
  opacity: 0.58;

  cursor: not-allowed;
}


/* =========================================================
   Chrome Autofill
   ========================================================= */

.rf-auth-field input:-webkit-autofill,
.rf-auth-field input:-webkit-autofill:hover,
.rf-auth-field input:-webkit-autofill:focus,
.rf-auth-input input:-webkit-autofill,
.rf-auth-input input:-webkit-autofill:hover,
.rf-auth-input input:-webkit-autofill:focus {
  -webkit-text-fill-color:
    #18151f !important;

  -webkit-box-shadow:
    0
    0
    0
    1000px
    #fbfbfd
    inset !important;

  transition:
    background-color
    9999s
    ease-out;
}


/* =========================================================
   Password show/hide button
   ========================================================= */

.rf-password-toggle {
  position: absolute !important;

  z-index: 5;

  right: 8px !important;

  top: 50% !important;

  min-width: 54px;
  height: 36px;

  transform:
    translateY(-50%);

  display: inline-flex;
  align-items: center;
  justify-content: center;

  padding:
    0
    10px;

  border:
    1px solid rgba(111, 66, 245, 0.08) !important;

  border-radius: 10px !important;

  color:
    #655b70 !important;

  background:
    rgba(255, 255, 255, 0.8) !important;

  font-size: 10px !important;

  font-weight: 800 !important;

  transition:
    color 150ms ease,
    background 150ms ease,
    border-color 150ms ease !important;
}


.rf-password-toggle:hover {
  color:
    var(--auth-purple) !important;

  background:
    #f3efff !important;

  border-color:
    rgba(111, 66, 245, 0.16) !important;
}


/* password field needs room for button */

.rf-auth-input:has(.rf-password-toggle) input {
  padding-right:
    72px !important;
}


/* =========================================================
   Login helper row
   ========================================================= */

.rf-auth-row {
  display: flex !important;

  justify-content:
    flex-end !important;

  align-items:
    center !important;

  min-height: 28px;

  margin-top:
    -4px !important;
}


.rf-auth-row a {
  color:
    #6843da !important;

  font-size:
    11px !important;

  font-weight:
    800 !important;

  transition:
    color 150ms ease;
}


.rf-auth-row a:hover {
  color:
    #e14ca9 !important;
}


/* =========================================================
   Primary CTA
   ========================================================= */

.rf-auth-submit {
  position: relative;

  isolation: isolate;

  width: 100%;

  min-height: 56px !important;

  display: inline-flex !important;

  align-items: center !important;
  justify-content: center !important;

  gap: 9px !important;

  padding:
    0
    21px !important;

  overflow: hidden;

  border:
    1px solid rgba(255, 255, 255, 0.1) !important;

  border-radius:
    14px !important;

  color:
    #fff !important;

  background:
    linear-gradient(
      110deg,
      #623be8 0%,
      #7c48f4 42%,
      #df4cad 78%,
      #ff8960 100%
    ) !important;

  box-shadow:
    0 16px 34px rgba(102, 58, 225, 0.2),
    0 8px 20px rgba(234, 77, 171, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.18) !important;

  font-size:
    12px !important;

  font-weight:
    850 !important;

  letter-spacing:
    -0.005em;

  cursor:
    pointer;

  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    filter 180ms ease !important;
}


.rf-auth-submit::before {
  content: "";

  position: absolute;

  z-index: -1;

  width: 100px;
  height: 100px;

  left: -120px;
  top: -22px;

  transform:
    skewX(-18deg);

  background:
    rgba(255, 255, 255, 0.16);

  filter:
    blur(4px);

  transition:
    left 400ms ease;
}


.rf-auth-submit:hover:not(:disabled) {
  transform:
    translateY(-2px);

  filter:
    saturate(1.06);

  box-shadow:
    0 20px 46px rgba(102, 58, 225, 0.27),
    0 10px 28px rgba(234, 77, 171, 0.15) !important;
}


.rf-auth-submit:hover:not(:disabled)::before {
  left:
    calc(100% + 30px);
}


.rf-auth-submit:active:not(:disabled) {
  transform:
    translateY(0);
}


.rf-auth-submit:disabled {
  opacity:
    0.58 !important;

  cursor:
    not-allowed !important;

  box-shadow:
    none !important;
}


/* =========================================================
   Signup step bar
   ========================================================= */

.rf-auth-stepbar {
  display: grid !important;

  grid-template-columns:
    auto
    minmax(42px, 1fr)
    auto !important;

  align-items:
    center !important;

  gap:
    12px !important;

  margin-bottom:
    7px;
}


.rf-auth-stepbar > span {
  display: inline-flex !important;

  align-items:
    center !important;

  gap:
    8px !important;

  color:
    #aaa4b2 !important;

  font-size:
    9px !important;

  font-weight:
    750 !important;

  letter-spacing:
    0.015em;

  white-space:
    nowrap;
}


.rf-auth-stepbar > span b {
  width:
    28px;
  height:
    28px;

  display:
    grid;

  place-items:
    center;

  border:
    1px solid rgba(50, 42, 71, 0.09);

  border-radius:
    9px;

  color:
    #8a8394;

  background:
    #f4f3f7;

  font-size:
    9px;

  font-weight:
    850;

  transition:
    all 180ms ease;
}


.rf-auth-stepbar > span.active {
  color:
    #564c62 !important;
}


.rf-auth-stepbar > span.active b {
  color:
    #fff;

  border-color:
    transparent;

  background:
    linear-gradient(
      135deg,
      #6940ed,
      #a84bdc
    );

  box-shadow:
    0 8px 18px rgba(111, 66, 245, 0.18);
}


.rf-auth-stepbar > i {
  display:
    block !important;

  height:
    1px !important;

  min-width:
    30px;

  background:
    linear-gradient(
      90deg,
      rgba(111, 66, 245, 0.18),
      rgba(234, 77, 171, 0.18)
    ) !important;
}


/* =========================================================
   Signup account-type cards
   ========================================================= */

.rf-auth-type-grid {
  display: grid !important;

  grid-template-columns:
    repeat(2, minmax(0, 1fr)) !important;

  gap:
    12px !important;
}


.rf-auth-type-card {
  position:
    relative;

  min-height:
    155px !important;

  display:
    grid !important;

  grid-template-columns:
    50px
    minmax(0, 1fr) !important;

  align-items:
    start !important;

  gap:
    14px !important;

  padding:
    20px !important;

  text-align:
    left !important;

  overflow:
    hidden;

  border:
    1px solid rgba(50, 38, 75, 0.09) !important;

  border-radius:
    18px !important;

  color:
    var(--auth-ink) !important;

  background:
    linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.96),
      rgba(249, 248, 252, 0.96)
    ) !important;

  box-shadow:
    0 9px 24px rgba(44, 31, 75, 0.035) !important;

  cursor:
    pointer;

  transition:
    transform 170ms ease,
    border-color 170ms ease,
    box-shadow 170ms ease,
    background 170ms ease !important;
}


.rf-auth-type-card::after {
  content: "";

  position:
    absolute;

  width:
    140px;
  height:
    140px;

  right:
    -85px;
  bottom:
    -95px;

  border-radius:
    50%;

  border:
    24px solid rgba(111, 66, 245, 0.035);

  pointer-events:
    none;
}


.rf-auth-type-card:hover {
  transform:
    translateY(-2px);

  border-color:
    rgba(111, 66, 245, 0.25) !important;

  box-shadow:
    0 16px 36px rgba(54, 38, 99, 0.07) !important;
}


.rf-auth-type-card.active {
  padding:
    19px !important;

  border:
    2px solid rgba(111, 66, 245, 0.72) !important;

  background:
    radial-gradient(
      circle at 100% 0%,
      rgba(234, 77, 171, 0.075),
      transparent 12rem
    ),
    linear-gradient(
      180deg,
      #fff,
      #f7f4ff
    ) !important;

  box-shadow:
    0 0 0 4px rgba(111, 66, 245, 0.055),
    0 17px 40px rgba(67, 42, 139, 0.09) !important;
}


.rf-auth-type-icon {
  width:
    50px !important;

  height:
    50px !important;

  display:
    grid !important;

  place-items:
    center !important;

  border-radius:
    14px !important;

  color:
    #6740e6 !important;

  background:
    #f0ecff !important;

  transition:
    color 170ms ease,
    background 170ms ease,
    box-shadow 170ms ease !important;
}


.rf-auth-type-card.active
.rf-auth-type-icon {
  color:
    #fff !important;

  background:
    linear-gradient(
      135deg,
      #6c42f0,
      #ca4bc4
    ) !important;

  box-shadow:
    0 10px 23px rgba(111, 66, 245, 0.18);
}


.rf-auth-type-card > div {
  min-width:
    0;
}


.rf-auth-type-card b {
  display:
    block;

  margin-bottom:
    7px;

  color:
    #1c1822;

  font-family:
    "Manrope",
    "Inter",
    sans-serif;

  font-size:
    14px !important;

  line-height:
    1.25;

  letter-spacing:
    -0.028em;

  font-weight:
    820 !important;
}


.rf-auth-type-card small {
  display:
    block;

  color:
    #7b7582 !important;

  font-size:
    10.5px !important;

  line-height:
    1.55 !important;

  font-weight:
    520 !important;
}


.rf-auth-type-card > i {
  position:
    absolute;

  top:
    14px;
  right:
    14px;

  width:
    25px;
  height:
    25px;

  display:
    grid;

  place-items:
    center;

  border-radius:
    50%;

  color:
    #fff;

  background:
    linear-gradient(
      135deg,
      #6941ed,
      #df4dac
    );

  box-shadow:
    0 7px 18px rgba(111, 66, 245, 0.2);
}


/* =========================================================
   Signup information note
   ========================================================= */

.rf-auth-selected-note {
  display:
    grid !important;

  grid-template-columns:
    36px
    minmax(0, 1fr) !important;

  align-items:
    start !important;

  gap:
    11px !important;

  padding:
    13px 14px !important;

  border:
    1px solid rgba(111, 66, 245, 0.1) !important;

  border-radius:
    14px !important;

  background:
    linear-gradient(
      135deg,
      rgba(111, 66, 245, 0.045),
      rgba(234, 77, 171, 0.025)
    ) !important;
}


.rf-auth-selected-note > span {
  width:
    36px !important;

  height:
    36px !important;

  display:
    grid !important;

  place-items:
    center !important;

  border-radius:
    11px !important;

  color:
    #663ee3 !important;

  background:
    rgba(111, 66, 245, 0.08) !important;
}


.rf-auth-selected-note b {
  display:
    block;

  margin-bottom:
    3px;

  color:
    #322b3b;

  font-size:
    11px;

  font-weight:
    800;
}


.rf-auth-selected-note small {
  display:
    block;

  color:
    #797282;

  font-size:
    10px;

  line-height:
    1.5;
}


/* =========================================================
   Signup form actions
   ========================================================= */

.rf-auth-form-actions {
  display:
    grid !important;

  grid-template-columns:
    minmax(130px, 0.42fr)
    minmax(210px, 1fr) !important;

  gap:
    10px !important;
}


.rf-auth-back-btn {
  min-height:
    56px !important;

  display:
    inline-flex !important;

  align-items:
    center !important;
  justify-content:
    center !important;

  gap:
    8px !important;

  padding:
    0
    18px !important;

  border:
    1px solid rgba(43, 34, 65, 0.09) !important;

  border-radius:
    14px !important;

  color:
    #625b6c !important;

  background:
    rgba(249, 249, 252, 0.9) !important;

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85);

  font-size:
    11px !important;

  font-weight:
    800 !important;

  transition:
    background 160ms ease,
    border-color 160ms ease,
    color 160ms ease,
    transform 160ms ease !important;
}


.rf-auth-back-btn:hover:not(:disabled) {
  transform:
    translateY(-1px);

  color:
    var(--auth-purple) !important;

  border-color:
    rgba(111, 66, 245, 0.17) !important;

  background:
    #f5f2ff !important;
}


.rf-auth-back-btn:disabled {
  opacity:
    0.5;

  cursor:
    not-allowed;
}


/* =========================================================
   Error / success messages
   ========================================================= */

.rf-auth-error,
.rf-auth-success,
.rf-auth-dev-link {
  position:
    relative;

  margin:
    0 !important;

  padding:
    12px
    14px !important;

  border-radius:
    13px !important;

  font-size:
    10.5px !important;

  line-height:
    1.5 !important;

  font-weight:
    650 !important;
}


.rf-auth-error {
  color:
    #b42d48 !important;

  border:
    1px solid rgba(231, 76, 111, 0.17) !important;

  background:
    rgba(255, 239, 243, 0.86) !important;

  box-shadow:
    0 8px 18px rgba(192, 45, 76, 0.035);
}


.rf-auth-success {
  color:
    #087451 !important;

  border:
    1px solid rgba(31, 181, 127, 0.16) !important;

  background:
    rgba(235, 252, 245, 0.9) !important;
}


.rf-auth-dev-link {
  color:
    #72551d !important;

  border:
    1px solid rgba(207, 158, 58, 0.15) !important;

  background:
    rgba(255, 249, 233, 0.9) !important;
}


/* =========================================================
   Footer under auth card
   ========================================================= */

.rf-auth-footer,
.auth-footer {
  position:
    relative;

  z-index:
    2;

  margin-top:
    18px !important;

  text-align:
    center !important;

  color:
    #827b8c !important;

  font-size:
    11px !important;

  line-height:
    1.5;

  font-weight:
    600 !important;
}


.rf-auth-footer a,
.auth-footer a {
  color:
    #6740e2 !important;

  font-weight:
    820 !important;

  transition:
    color 150ms ease;
}


.rf-auth-footer a:hover,
.auth-footer a:hover {
  color:
    #db4fae !important;
}


/* =========================================================
   Keyboard accessibility
   ========================================================= */

.rf-auth-submit:focus-visible,
.rf-auth-back-btn:focus-visible,
.rf-auth-type-card:focus-visible,
.rf-password-toggle:focus-visible,
.rf-auth-footer a:focus-visible,
.rf-auth-row a:focus-visible {
  outline:
    3px solid rgba(111, 66, 245, 0.2) !important;

  outline-offset:
    3px !important;
}


/* =========================================================
   Desktop animation
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {
  .rf-auth-hero {
    animation:
      rf-auth-panel-enter
      520ms
      cubic-bezier(0.2, 0.8, 0.2, 1)
      both;
  }

  .rf-auth-card {
    animation:
      rf-auth-card-enter
      620ms
      70ms
      cubic-bezier(0.2, 0.8, 0.2, 1)
      both;
  }

  .rf-auth-hero::after {
    animation:
      rf-auth-orbit
      12s
      ease-in-out
      infinite
      alternate;
  }
}


@keyframes rf-auth-panel-enter {
  from {
    opacity: 0;
    transform:
      translateX(-14px)
      scale(0.992);
  }

  to {
    opacity: 1;
    transform:
      translateX(0)
      scale(1);
  }
}


@keyframes rf-auth-card-enter {
  from {
    opacity: 0;
    transform:
      translateY(16px)
      scale(0.992);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}


@keyframes rf-auth-orbit {
  from {
    transform:
      translate3d(0, 0, 0);
  }

  to {
    transform:
      translate3d(-18px, -14px, 0);
  }
}


/* =========================================================
   Laptop
   ========================================================= */

@media (max-width: 1180px) {
  .rf-auth-shell {
    width:
      min(1060px, 100%) !important;

    grid-template-columns:
      minmax(350px, 0.86fr)
      minmax(430px, 1.14fr) !important;
  }


  .rf-auth-hero,
  .auth-left {
    padding:
      34px !important;
  }


  .rf-auth-copy h1,
  .auth-left h1 {
    font-size:
      clamp(39px, 4.7vw, 54px) !important;
  }


  .rf-auth-card,
  .auth-card {
    padding:
      34px !important;
  }
}


/* =========================================================
   Tablet
   ========================================================= */

@media (max-width: 980px) {
  .rf-auth-page,
  .auth-page {
    padding:
      18px !important;

    overflow-y:
      auto;
  }


  .rf-auth-shell {
    width:
      min(720px, 100%) !important;

    min-height:
      auto !important;

    grid-template-columns:
      1fr !important;

    gap:
      18px !important;
  }


  .rf-auth-hero,
  .auth-left {
    min-height:
      350px !important;

    padding:
      32px !important;

    border-radius:
      28px !important;
  }


  .rf-auth-copy h1,
  .auth-left h1 {
    max-width:
      620px !important;

    margin-top:
      18px !important;

    font-size:
      clamp(38px, 7vw, 52px) !important;
  }


  .rf-auth-copy p,
  .auth-left p {
    max-width:
      620px !important;

    font-size:
      14px !important;
  }


  .rf-auth-proof,
  .auth-proof {
    margin-top:
      28px;
  }


  .rf-auth-panel,
  .auth-right {
    display:
      block !important;
  }


  .rf-auth-card,
  .auth-card {
    padding:
      34px !important;

    border-radius:
      28px !important;
  }
}


/* =========================================================
   Mobile
   ========================================================= */

@media (max-width: 640px) {
  .rf-auth-page,
  .auth-page {
    display:
      block !important;

    min-height:
      100svh !important;

    padding:
      10px !important;

    overflow-x:
      hidden;
