    gap:
      6px !important;

    margin-top:
      20px;
  }


  .rf-auth-proof span,
  .auth-proof span {
    min-height:
      31px !important;

    padding:
      0
      9px !important;

    border-radius:
      9px !important;

    font-size:
      8.5px !important;
  }


  .rf-auth-card,
  .auth-card {
    padding:
      24px 18px !important;

    border-radius:
      22px !important;
  }


  .rf-auth-card-head {
    margin-bottom:
      20px !important;
  }


  .rf-auth-card-head h2 {
    font-size:
