/* ========================================================================== 
   ReachFly Voice Setup V2 — guided single-card experience
   ========================================================================== */

.rf-voice-setup-shell {
  --voice-ink: #11182f;
  --voice-muted: #6c7489;
  --voice-line: rgba(76, 68, 138, 0.12);
  --voice-purple: #6d4aff;
  --voice-violet: #8b5cf6;
  --voice-pink: #f449ad;
  --voice-blue: #3f7cff;
  --voice-green: #16a875;
  position: relative;
  overflow: hidden;
  width: 100%;
  border: 1px solid rgba(109, 74, 255, 0.12);
  border-radius: 30px;
  background:
    radial-gradient(circle at 92% 2%, rgba(109, 74, 255, 0.13), transparent 28rem),
    radial-gradient(circle at 4% 26%, rgba(244, 73, 173, 0.07), transparent 25rem),
    linear-gradient(180deg, rgba(255,255,255,.98), rgba(249,249,255,.98));
  box-shadow: 0 28px 80px rgba(35, 26, 78, 0.09);
}

.rf-voice-setup-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: .35;
  background-image:
    linear-gradient(rgba(103, 89, 183, .035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(103, 89, 183, .035) 1px, transparent 1px);
  background-size: 34px 34px;
  mask-image: linear-gradient(to bottom, #000, transparent 58%);
}

.rf-voice-setup-hero {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 220px;
  gap: 28px;
  align-items: center;
  padding: 34px 38px 24px;
}

.rf-voice-setup-hero h2 {
  max-width: 720px;
  margin: 9px 0 8px;
  color: var(--voice-ink);
  font-size: clamp(1.65rem, 3vw, 2.55rem);
  line-height: 1.04;
  letter-spacing: -.045em;
}

.rf-voice-setup-hero p {
  max-width: 720px;
  margin: 0;
  color: var(--voice-muted);
  font-size: .94rem;
  line-height: 1.65;
}

.rf-voice-credit-orb {
  position: relative;
  overflow: hidden;
  display: grid;
  justify-items: end;
  min-height: 132px;
  padding: 21px 22px;
  border: 1px solid rgba(255,255,255,.2);
  border-radius: 23px;
  color: #fff;
  background:
    radial-gradient(circle at 15% 0%, rgba(255,255,255,.22), transparent 7rem),
    linear-gradient(135deg, #5c3df0, #894cf2 48%, #ec4bab 100%);
  box-shadow: 0 20px 44px rgba(109,74,255,.22);
}

.rf-voice-credit-orb::after {
  content: "";
  position: absolute;
  width: 120px;
  height: 120px;
  left: -32px;
  bottom: -56px;
  border: 22px solid rgba(255,255,255,.1);
  border-radius: 50%;
}

.rf-voice-credit-orb span,
.rf-voice-credit-orb small,
.rf-voice-credit-orb strong {
  position: relative;
  z-index: 1;
}

.rf-voice-credit-orb span {
  font-size: .68rem;
  font-weight: 850;
  letter-spacing: .095em;
  text-transform: uppercase;
  opacity: .82;
}

.rf-voice-credit-orb strong {
  margin-top: 4px;
  font-size: 2.6rem;
  line-height: 1;
  letter-spacing: -.06em;
}

.rf-voice-credit-orb small {
  max-width: 150px;
  margin-top: 6px;
  text-align: right;
  font-size: .72rem;
  line-height: 1.35;
  opacity: .78;
}

.rf-voice-setup-progress {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 9px;
  padding: 0 38px 26px;
}

.rf-voice-setup-progress button {
  appearance: none;
  min-width: 0;
  min-height: 74px;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  grid-template-rows: auto auto;
  column-gap: 10px;
  align-items: center;
  padding: 11px 12px;
  border: 1px solid var(--voice-line);
  border-radius: 16px;
  color: #72798b;
  background: rgba(255,255,255,.64);
  text-align: left;
  box-shadow: inset 0 1px rgba(255,255,255,.8);
  transition: transform .16s ease, border-color .16s ease, background .16s ease, box-shadow .16s ease;
}

.rf-voice-setup-progress button > span {
  grid-row: 1 / 3;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid #ddd9ef;
  border-radius: 11px;
  background: #fff;
  font-size: .72rem;
  font-weight: 900;
}

.rf-voice-setup-progress button b {
  align-self: end;
  color: #42495c;
  font-size: .78rem;
  line-height: 1.05;
}

.rf-voice-setup-progress button small {
  align-self: start;
  overflow: hidden;
  color: #9298a8;
  font-size: .61rem;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-voice-setup-progress button.current {
  border-color: rgba(109,74,255,.32);
  color: var(--voice-purple);
  background: linear-gradient(180deg, #fff, #f4f0ff);
  box-shadow: 0 11px 28px rgba(109,74,255,.10);
  transform: translateY(-2px);
}

.rf-voice-setup-progress button.current > span {
  border-color: transparent;
  color: #fff;
  background: linear-gradient(135deg, var(--voice-purple), var(--voice-pink));
  box-shadow: 0 8px 18px rgba(109,74,255,.22);
}

.rf-voice-setup-progress button.current b { color: #38279b; }

.rf-voice-setup-progress button.done {
  cursor: pointer;
  color: #087a55;
  background: rgba(236,253,245,.78);
  border-color: rgba(22,168,117,.18);
}

.rf-voice-setup-progress button.done > span {
  border-color: rgba(22,168,117,.2);
  color: #fff;
  background: #19ad79;
}

.rf-voice-setup-stage {
  position: relative;
  z-index: 1;
  margin: 0 22px 22px;
  border: 1px solid rgba(83,73,137,.11);
  border-radius: 24px;
  background: rgba(255,255,255,.92);
  box-shadow: 0 16px 48px rgba(35,26,78,.06);
}

.rf-voice-setup-stage-head {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding: 28px 30px 20px;
  border-bottom: 1px solid rgba(83,73,137,.08);
}

.rf-voice-setup-stage-head > div > span {
  color: var(--voice-purple);
  font-size: .66rem;
  font-weight: 900;
  letter-spacing: .095em;
  text-transform: uppercase;
}

.rf-voice-setup-stage-head h3 {
  max-width: 760px;
  margin: 7px 0 6px;
  color: var(--voice-ink);
  font-size: clamp(1.28rem, 2.4vw, 1.75rem);
  line-height: 1.15;
  letter-spacing: -.035em;
}

.rf-voice-setup-stage-head p {
  max-width: 760px;
  margin: 0;
  color: var(--voice-muted);
  font-size: .86rem;
  line-height: 1.58;
}

.rf-voice-setup-step-number {
  flex: 0 0 auto;
  color: rgba(109,74,255,.22);
  font-size: 2.2rem;
  font-weight: 950;
  line-height: 1;
  letter-spacing: -.06em;
}

.rf-voice-setup-pane {
  min-height: 330px;
  padding: 27px 30px 30px;
  animation: rfVoicePaneIn .22s ease both;
}

@keyframes rfVoicePaneIn {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: translateY(0); }
}

.rf-voice-auto-card {
  display: grid;
  grid-template-columns: 1.2fr 1fr auto;
  gap: 13px;
  align-items: center;
  margin-top: 18px;
  padding: 16px;
  border: 1px solid #e7e3f2;
  border-radius: 18px;
  background: linear-gradient(180deg, #faf9ff, #f6f5fb);
}

.rf-voice-auto-card > span {
  grid-column: 1 / -1;
  color: #8a8298;
  font-size: .66rem;
  font-weight: 850;
  letter-spacing: .075em;
  text-transform: uppercase;
}

.rf-voice-auto-card > div {
  display: grid;
  gap: 3px;
}

.rf-voice-auto-card b { color: #262c3e; font-size: .84rem; }
.rf-voice-auto-card small { color: #83899a; font-size: .69rem; }

.rf-voice-intel-summary,
.rf-voice-skip-card {
  display: grid;
  gap: 8px;
  margin-top: 20px;
  padding: 19px;
  border-radius: 18px;
}

.rf-voice-intel-summary {
  border: 1px solid rgba(22,168,117,.18);
  background: linear-gradient(180deg, #f3fff9, #f8fffb);
}

.rf-voice-intel-summary > span {
  width: fit-content;
  padding: 5px 8px;
  border-radius: 999px;
  color: #087652;
  background: rgba(22,168,117,.1);
  font-size: .65rem;
  font-weight: 900;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.rf-voice-intel-summary strong {
  color: #173d31;
  font-size: 1rem;
  line-height: 1.45;
}

.rf-voice-intel-summary small,
.rf-voice-skip-card span {
  color: #70798b;
  line-height: 1.55;
}

.rf-voice-skip-card {
  border: 1px dashed rgba(109,74,255,.20);
  background: #faf9ff;
}

.rf-voice-skip-card b { color: #40368a; }

.rf-voice-calling-identity {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: center;
  margin-bottom: 18px;
  padding: 18px 20px;
  border: 1px solid rgba(109,74,255,.14);
  border-radius: 19px;
  background:
    radial-gradient(circle at 100% 0%, rgba(109,74,255,.09), transparent 12rem),
    #faf9ff;
}

.rf-voice-calling-identity > div { display: grid; gap: 4px; }
.rf-voice-calling-identity span { color: #7f8596; font-size: .67rem; font-weight: 850; text-transform: uppercase; letter-spacing: .07em; }
.rf-voice-calling-identity strong { color: #171c31; font-size: 1.4rem; letter-spacing: -.035em; }
.rf-voice-calling-identity small { color: #777f92; line-height: 1.4; }
.rf-voice-calling-identity > b {
  flex: 0 0 auto;
  padding: 7px 10px;
  border-radius: 999px;
  color: #087652;
  background: #eafbf3;
  border: 1px solid #c9efdd;
  font-size: .66rem;
  letter-spacing: .08em;
}

.rf-voice-advanced {
  margin-top: 18px;
  border: 1px solid #e7e4ef;
  border-radius: 17px;
  background: #fbfbfd;
}

.rf-voice-advanced summary {
  padding: 14px 16px;
  color: #494f61;
  font-size: .78rem;
  font-weight: 850;
  cursor: pointer;
  user-select: none;
}

.rf-voice-advanced[open] summary {
  border-bottom: 1px solid #ebe8f2;
}

.rf-voice-advanced > :not(summary) {
  margin: 15px 16px;
}

.rf-voice-review-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 18px;
}

.rf-voice-review-grid article {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 15px;
  border: 1px solid #e8e5f0;
  border-radius: 16px;
  background: #fbfbfd;
}

.rf-voice-review-grid span {
  color: #8a91a3;
  font-size: .62rem;
  font-weight: 850;
  letter-spacing: .075em;
  text-transform: uppercase;
}

.rf-voice-review-grid strong {
  overflow: hidden;
  color: #202638;
  font-size: .85rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-voice-review-grid small {
  overflow: hidden;
  color: #878d9d;
  font-size: .67rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-voice-credit-wallet {
  position: relative;
  overflow: hidden;
  padding: 21px;
  border: 1px solid rgba(109,74,255,.15);
  border-radius: 20px;
  background:
    radial-gradient(circle at 100% 0%, rgba(109,74,255,.09), transparent 18rem),
    linear-gradient(180deg, #faf9ff, #fff);
}

.rf-voice-credit-wallet-head {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: end;
}

.rf-voice-credit-wallet-head > div:first-child { display: grid; gap: 3px; }
.rf-voice-credit-wallet-head span { color: #746a92; font-size: .67rem; font-weight: 900; letter-spacing: .08em; text-transform: uppercase; }
.rf-voice-credit-wallet-head strong { color: #211b42; font-size: 2.35rem; line-height: 1; letter-spacing: -.06em; }
.rf-voice-credit-wallet-head small { color: #7b8294; }
.rf-voice-credit-wallet-head > div:last-child { text-align: right; }
.rf-voice-credit-wallet-head > div:last-child b { display: block; color: #5b3cd5; font-size: 1.25rem; }

.rf-voice-credit-meter {
  height: 7px;
  margin: 17px 0 13px;
  overflow: hidden;
  border-radius: 999px;
  background: #ece9f6;
}

.rf-voice-credit-meter span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #6d4aff, #a34df0, #f449ad);
  box-shadow: 0 0 18px rgba(109,74,255,.28);
}

.rf-voice-credit-wallet p {
  margin: 0;
  color: #6f7689;
  font-size: .74rem;
  line-height: 1.55;
}

.rf-voice-credit-pack-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 16px;
}

.rf-voice-credit-pack-row button {
  appearance: none;
  display: grid;
  gap: 3px;
  padding: 13px 14px;
  border: 1px solid #e5e1ef;
  border-radius: 15px;
  color: #3d4050;
  background: #fff;
  text-align: left;
  cursor: pointer;
  transition: transform .15s ease, border-color .15s ease, box-shadow .15s ease;
}

.rf-voice-credit-pack-row button:hover:not(:disabled) {
  transform: translateY(-2px);
  border-color: rgba(109,74,255,.3);
  box-shadow: 0 10px 24px rgba(43,32,91,.08);
}

.rf-voice-credit-pack-row button:disabled { opacity: .55; cursor: not-allowed; }
.rf-voice-credit-pack-row button span { color: #6b7182; font-size: .69rem; font-weight: 800; }
.rf-voice-credit-pack-row button b { color: #2d235a; font-size: .95rem; }
.rf-voice-credit-pack-row button small { color: #8c92a1; font-size: .64rem; }

.rf-voice-activate-button {
  min-height: 52px !important;
  margin-top: 18px;
  border-radius: 15px !important;
}

.rf-voice-setup-nav {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 18px 30px 24px;
  border-top: 1px solid #ece9f3;
}

.rf-voice-arrow-button {
  appearance: none;
  min-width: 170px;
  min-height: 56px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 13px;
  border-radius: 16px;
  text-align: left;
  cursor: pointer;
  transition: transform .16s ease, box-shadow .16s ease, opacity .16s ease;
}

.rf-voice-arrow-button > span {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  font-size: 1.15rem;
  font-weight: 900;
}

.rf-voice-arrow-button > div { display: grid; gap: 1px; min-width: 0; }
.rf-voice-arrow-button small { font-size: .61rem; font-weight: 800; text-transform: uppercase; letter-spacing: .07em; }
.rf-voice-arrow-button b { font-size: .78rem; }

.rf-voice-arrow-button.primary {
  margin-left: auto;
  justify-content: flex-end;
  border: 1px solid transparent;
  color: #fff;
  background: linear-gradient(135deg, #6044ec, #8a4df0 50%, #ef4cae);
  box-shadow: 0 14px 30px rgba(109,74,255,.18);
}

.rf-voice-arrow-button.primary > div { text-align: right; }
.rf-voice-arrow-button.primary > span { background: rgba(255,255,255,.15); }
.rf-voice-arrow-button.primary small { color: rgba(255,255,255,.7); }

.rf-voice-arrow-button.secondary {
  border: 1px solid #e4e1ec;
  color: #454b5d;
  background: #fff;
}

.rf-voice-arrow-button.secondary > span { color: #6d4aff; background: #f3f0ff; }
.rf-voice-arrow-button.secondary small { color: #9095a3; }

.rf-voice-arrow-button:hover:not(:disabled) { transform: translateY(-2px); }
.rf-voice-arrow-button:disabled { opacity: .38; cursor: not-allowed; }

.rf-voice-starter-balance {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
  margin-bottom: 18px;
  padding: 17px 19px;
  border: 1px solid rgba(109,74,255,.14);
  border-radius: 18px;
  background: linear-gradient(135deg, #f7f4ff, #fff7fc);
}

.rf-voice-starter-balance > div { display: grid; gap: 3px; }
.rf-voice-starter-balance span { color: #766c8d; font-size: .65rem; font-weight: 850; letter-spacing: .075em; text-transform: uppercase; }
.rf-voice-starter-balance strong { color: #30236d; font-size: 1.15rem; }
.rf-voice-starter-balance small { color: #7d8495; }
.rf-voice-starter-balance > b {
  flex: 0 0 auto;
  padding: 7px 10px;
  border: 1px solid rgba(109,74,255,.16);
  border-radius: 999px;
  color: #6044d9;
  background: #fff;
  font-size: .63rem;
  letter-spacing: .08em;
}

/* Compact field treatment inside the guided setup. */
.rf-voice-setup-shell .rf-agent-field,
.rf-voice-setup-shell .rf-agent-field-grid,
.rf-voice-setup-shell .field {
  margin-bottom: 0;
}

.rf-voice-setup-shell .rf-agent-field > span,
.rf-voice-setup-shell .field > span {
  margin-bottom: 7px;
  color: #4d5365;
  font-size: .71rem;
  font-weight: 850;
}

.rf-voice-setup-shell input,
.rf-voice-setup-shell select,
.rf-voice-setup-shell textarea {
  border-color: #e1deeb;
  background: rgba(255,255,255,.95);
  box-shadow: inset 0 1px 2px rgba(32,27,62,.02);
}

.rf-voice-setup-shell input:focus,
.rf-voice-setup-shell select:focus,
.rf-voice-setup-shell textarea:focus {
  border-color: rgba(109,74,255,.45);
  box-shadow: 0 0 0 4px rgba(109,74,255,.08);
}

@media (max-width: 1100px) {
  .rf-voice-setup-hero { grid-template-columns: minmax(0, 1fr) 190px; }
  .rf-voice-setup-progress { grid-template-columns: repeat(5, minmax(110px, 1fr)); overflow-x: auto; }
  .rf-voice-review-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 760px) {
  .rf-voice-setup-shell { border-radius: 22px; }
  .rf-voice-setup-hero { grid-template-columns: 1fr; padding: 25px 20px 18px; }
  .rf-voice-credit-orb { min-height: 0; justify-items: start; }
  .rf-voice-credit-orb small { text-align: left; max-width: none; }
  .rf-voice-setup-progress { padding: 0 20px 20px; }
  .rf-voice-setup-stage { margin: 0 10px 10px; border-radius: 19px; }
  .rf-voice-setup-stage-head { padding: 22px 19px 17px; }
  .rf-voice-setup-pane { min-height: 0; padding: 20px 19px 23px; }
  .rf-voice-auto-card { grid-template-columns: 1fr; }
  .rf-voice-auto-card > span { grid-column: auto; }
  .rf-voice-review-grid { grid-template-columns: 1fr; }
  .rf-voice-credit-wallet-head { align-items: start; }
  .rf-voice-credit-pack-row { grid-template-columns: 1fr; }
  .rf-voice-setup-nav { padding: 15px 19px 20px; }
  .rf-voice-arrow-button { min-width: 0; flex: 1; }
  .rf-voice-calling-identity { align-items: flex-start; }
}

@media (max-width: 520px) {
  .rf-voice-setup-step-number { display: none; }
  .rf-voice-setup-progress button { min-height: 62px; grid-template-columns: 30px minmax(0,1fr); padding: 9px; }
  .rf-voice-setup-progress button > span { width: 30px; height: 30px; }
  .rf-voice-setup-nav { gap: 8px; }
  .rf-voice-arrow-button { min-height: 50px; padding: 6px 9px; }
  .rf-voice-arrow-button > span { width: 34px; height: 34px; }
  .rf-voice-arrow-button b { font-size: .72rem; }
}

@media (prefers-reduced-motion: reduce) {
  .rf-voice-setup-pane,
  .rf-voice-setup-progress button,
  .rf-voice-arrow-button,
  .rf-voice-credit-pack-row button {
    animation: none !important;
    transition: none !important;
  }
}


/* =========================================================
   ReachFly Voice Setup V4 — inbound / outbound / BYON
   ========================================================= */

.rf-voice-setup-progress.six {
  grid-template-columns: repeat(6, minmax(0, 1fr));
}

.rf-voice-mode-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 22px;
}

.rf-voice-mode-card {
  min-height: 220px;
  padding: 22px;
  text-align: left;
  border: 1px solid #e3e5ee;
  border-radius: 20px;
  background:
    radial-gradient(circle at 100% 100%, rgba(111, 66, 245, 0.08), transparent 12rem),
