  box-shadow:
    0 0 0 3px rgba(111, 66, 245, 0.08),
    0 18px 44px rgba(74, 48, 156, 0.10);
}

.rf-voice-mode-card > span {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  color: #6441df;
  background: #f0ecff;
  font-size: 20px;
  font-weight: 900;
}

.rf-voice-mode-card h4 {
  margin: 34px 0 8px;
  font-size: 18px;
