.rf-voice-verification-card > span {
  color: #6441df;
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.rf-voice-verification-card > strong {
  font-size: 18px;
}

.rf-voice-verification-card > p {
  margin: 0;
  color: #6b6575;
  font-size: 12px;
  line-height: 1.5;
}

.rf-voice-verification-code {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: end;
  margin-top: 8px;
}

.rf-voice-workflow-block {
  padding: 22px;
  margin-bottom: 16px;
  border: 1px solid #e2e3eb;
  border-radius: 20px;
