.rf-lead-flow-progress > button > div {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.rf-lead-flow-progress b,
.rf-lead-flow-progress small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-lead-flow-progress b {
  color: #3c3444;
  font-size: 12px;
  line-height: 1.25;
  font-weight: 800;
}

.rf-lead-flow-progress small {
  color: #908895;
  font-size: 10px;
  line-height: 1.25;
  font-weight: 600;
