  color: #087849;
  background: #e7f8ef;
}

.rf-lead-flow-progress > button.done b {
  color: #366c52;
}


/* Active */

.rf-lead-flow-progress > button.active {
  transform: none;
  border-color: rgba(111, 66, 245, 0.43);
  background:
    radial-gradient(
      circle at 100% 0,
      rgba(111, 66, 245, 0.08),
      transparent 8rem
    ),
    linear-gradient(
      135deg,
      #ffffff,
      #f7f4ff
    );
  box-shadow:
    0 0 0 3px rgba(111, 66, 245, 0.055),
    0 9px 22px rgba(79, 53, 150, 0.08);
}

.rf-lead-flow-progress > button.active > span {
  color: #ffffff;
  background:
    linear-gradient(
      135deg,
      #7044f4 0%,
      #8753ef 48%,
      #e74ba9 100%
    );
  box-shadow:
    0 8px 18px rgba(111, 66, 245, 0.22);
}

.rf-lead-flow-progress > button.active b {
  color: #5f39d9;
}

.rf-lead-flow-progress > button.active small {
  color: #7665aa;
}


/* ==========================================================================
   Active stage
   ========================================================================== */

.rf-lead-flow-stage {
  width: 100%;
  min-width: 0;
}

.rf-lead-flow-stage > .rf-agent-card {
  min-width: 0;
  margin: 0;
