    opacity: 0;
    transform: translateY(5px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}


/* ==========================================================================
   Queue activity
   ========================================================================== */

.rf-lead-flow-activity-card {
  min-width: 0;
}

.rf-lead-flow-activity-card .rf-agent-queue-list {
  max-height: min(660px, 62vh);
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding-right: 5px;
  scrollbar-width: thin;
  scrollbar-color: #cdc7d5 transparent;
}

.rf-lead-flow-activity-card
