  width: 7px;
}

.rf-lead-flow-activity-card
  .rf-agent-queue-list::-webkit-scrollbar-track {
  background: transparent;
}

.rf-lead-flow-activity-card
  .rf-agent-queue-list::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: #d0cad8;
}

.rf-lead-flow-activity-card
  .rf-agent-queue-list::-webkit-scrollbar-thumb:hover {
  background: #bdb5c9;
}


/* ==========================================================================
   Queue activity toolbar
   ========================================================================== */

.rf-lead-activity-toolbar {
  min-width: 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 14px;
  margin-bottom: 16px;
  padding: 14px;
  border: 1px solid #e7e4ec;
  border-radius: 15px;
  background:
    linear-gradient(
      180deg,
      #fbfafd,
      #f9f8fc
    );
}

.rf-lead-activity-toolbar > label {
  min-width: 210px;
  display: grid;
  gap: 6px;
}

.rf-lead-activity-toolbar > label > span,
.rf-lead-activity-toolbar > div > span {
  color: #827a89;
  font-size: 10px;
  line-height: 1.2;
  font-weight: 850;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.rf-lead-activity-toolbar select {
  width: 100%;
  height: 41px;
  padding: 0 34px 0 11px;
  border: 1px solid #ddd9e3;
