}

.rf-lead-activity-toolbar select:hover {
  border-color: #cbc4d4;
}

.rf-lead-activity-toolbar select:focus {
  border-color: rgba(111, 66, 245, 0.5);
  box-shadow:
    0 0 0 3px rgba(111, 66, 245, 0.08);
}

.rf-lead-activity-toolbar > div {
  min-width: 110px;
  display: grid;
  justify-items: end;
  gap: 4px;
}

.rf-lead-activity-toolbar > div > b {
  color: #5f3ad8;
  font-size: 22px;
  line-height: 1;
  font-weight: 850;
  letter-spacing: -0.04em;
}


/* ==========================================================================
   Launch stage
   ========================================================================== */

.rf-lead-launch-note {
  position: relative;
  display: grid;
  gap: 6px;
  margin-top: 16px;
  padding: 15px 16px 15px 18px;
  overflow: hidden;
  border: 1px solid rgba(111, 66, 245, 0.14);
  border-radius: 15px;
  background:
    radial-gradient(
      circle at 100% 0,
      rgba(111, 66, 245, 0.07),
      transparent 12rem
    ),
    #f8f6ff;
}

.rf-lead-launch-note::before {
  content: "";
  position: absolute;
  top: 10px;
  bottom: 10px;
  left: 0;
  width: 3px;
  border-radius: 0 999px 999px 0;
  background:
    linear-gradient(
      180deg,
      #7145f4,
      #e74ba9
    );
}

.rf-lead-launch-note b {
  color: #5f3bd7;
  font-size: 12px;
  line-height: 1.3;
  font-weight: 850;
}

.rf-lead-launch-note p {
  max-width: 760px;
  margin: 0;
  color: #716978;
  font-size: 12px;
  line-height: 1.6;
}


/* ==========================================================================
   Previous / Next footer
   ========================================================================== */

.rf-lead-flow-footer {
  position: relative;
  z-index: 18;
  min-width: 0;
  min-height: 72px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 16px;
  align-items: center;
  padding: 13px 15px;
  border: 1px solid #e4e1e9;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow:
