    0 2px 7px rgba(40, 27, 70, 0.025);
}

.rf-lead-flow-footer > div {
  min-width: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 11px;
}

.rf-lead-flow-footer > div > span {
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border: 1px solid rgba(101, 64, 221, 0.06);
  border-radius: 11px;
  color: #6540dd;
  background:
    linear-gradient(
      135deg,
      #f1edff,
      #ebe5ff
    );
  font-size: 11px;
  line-height: 1;
  font-weight: 900;
}

.rf-lead-flow-footer > div > div {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.rf-lead-flow-footer b {
  color: #332b3a;
  font-size: 12px;
  line-height: 1.3;
  font-weight: 800;
}

.rf-lead-flow-footer small {
  min-width: 0;
  overflow: hidden;
  color: #877f8e;
  font-size: 10px;
  line-height: 1.25;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.rf-lead-flow-footer > button {
  min-height: 40px;
}

.rf-lead-flow-footer > button:focus-visible {
  outline: 3px solid rgba(111, 66, 245, 0.18);
  outline-offset: 2px;
}


/* Sticky wizard navigation on desktop */

@media (min-width: 721px) {
  .rf-lead-flow-footer {
    position: sticky;
    bottom: 14px;
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
