  }
}


/* ==========================================================================
   Improve common content inside guided stages
   ========================================================================== */

.rf-lead-flow-stage input,
.rf-lead-flow-stage select,
.rf-lead-flow-stage textarea,
.rf-lead-flow-stage button {
