}


/* Keep wide lead tables usable */

.rf-lead-flow-stage .rf-agent-table-wrap {
  max-width: 100%;
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  scrollbar-width: thin;
}


/* Prevent long lead/company/context values from breaking layout */

.rf-lead-flow-stage td,
.rf-lead-flow-stage th,
.rf-lead-flow-stage .rf-agent-queue-item {
  overflow-wrap: anywhere;
}


/* ==========================================================================
   Tablet
   ========================================================================== */

@media (max-width: 1180px) {
  .rf-lead-flow-header {
    padding: 18px;
  }

  .rf-lead-flow-progress {
    grid-template-columns: repeat(
      auto-fit,
      minmax(170px, 1fr)
