  }
}


/* ==========================================================================
   Mobile
   ========================================================================== */

@media (max-width: 720px) {
  .rf-lead-flow-shell {
    gap: 15px;
  }

  .rf-lead-flow-header {
    gap: 15px;
    padding: 15px;
    border-radius: 18px;
  }

  .rf-lead-flow-heading {
    display: grid;
    gap: 12px;
  }

  .rf-lead-flow-heading > strong {
    justify-self: start;
  }

  .rf-lead-flow-heading h2 {
    font-size: 21px;
  }

  .rf-lead-flow-heading p {
    font-size: 12px;
    line-height: 1.55;
  }

  .rf-lead-flow-progress {
    grid-template-columns: 1fr;
    gap: 7px;
  }

  .rf-lead-flow-progress > button {
    min-height: 56px;
    padding: 9px 10px;
    border-radius: 13px;
  }

  .rf-lead-flow-progress > button > span {
    width: 31px;
    height: 31px;
  }

  .rf-lead-flow-progress b {
    font-size: 11px;
  }

  .rf-lead-flow-progress small {
    font-size: 9px;
  }

  .rf-lead-activity-toolbar {
    align-items: stretch;
    flex-direction: column;
    gap: 11px;
    padding: 12px;
  }

  .rf-lead-activity-toolbar > label {
    min-width: 0;
  }

  .rf-lead-activity-toolbar > div {
    min-width: 0;
    justify-items: start;
  }

  .rf-lead-flow-activity-card .rf-agent-queue-list {
    max-height: 58vh;
  }

  .rf-lead-flow-footer {
    position: relative;
    bottom: auto;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    min-height: 0;
    padding: 12px;
    border-radius: 16px;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }

  .rf-lead-flow-footer > div {
    grid-column: 1 / -1;
    grid-row: 1;
    justify-content: flex-start;
    padding-bottom: 3px;
  }

  .rf-lead-flow-footer > button {
    width: 100%;
    min-width: 0;
  }

  .rf-lead-flow-footer > button:last-child {
    justify-self: stretch;
  }

  .rf-lead-launch-note {
    padding: 13px 13px 13px 16px;
  }
}


/* ==========================================================================
   Small mobile
   ========================================================================== */

@media (max-width: 460px) {
  .rf-lead-flow-header {
    padding: 13px;
  }

  .rf-lead-flow-heading h2 {
    font-size: 19px;
  }

  .rf-lead-flow-heading > strong {
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .rf-lead-flow-progress > button {
    grid-template-columns: 30px minmax(0, 1fr);
  }

  .rf-lead-flow-progress > button > span {
    width: 30px;
    height: 30px;
  }

  .rf-lead-flow-footer {
    grid-template-columns: 1fr;
  }

  .rf-lead-flow-footer > div {
    grid-column: 1;
  }

  .rf-lead-flow-footer > button {
    grid-column: 1;
  }
}


/* ==========================================================================
   Reduced motion
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .rf-lead-flow-stage > .rf-agent-card,
  .rf-lead-flow-progress > button,
  .rf-lead-flow-progress > button > span,
  .rf-lead-activity-toolbar select {
    animation: none !important;
    transition: none !important;
  }
}


/* ==========================================================================
   High contrast / forced colors
   ========================================================================== */

@media (forced-colors: active) {
  .rf-lead-flow-header,
  .rf-lead-flow-progress > button,
  .rf-lead-flow-footer,
  .rf-lead-activity-toolbar,
  .rf-lead-launch-note {
    border: 1px solid CanvasText;
  }

  .rf-lead-flow-progress > button.active {
    outline: 2px solid Highlight;
  }
}
