.rf-v6-metric-grid { display: grid; grid-template-columns: repeat(5,minmax(0,1fr)); gap: 10px; }
.rf-v6-metric { position: relative; display: grid; gap: 4px; padding: 16px; overflow: hidden; border: 1px solid var(--rf6-line); border-radius: 17px; background: #fff; box-shadow: 0 10px 28px rgba(42,25,77,.045); }
.rf-v6-metric.live { border-color: rgba(47,140,255,.22); background: linear-gradient(145deg,#fff,#f5faff); }
.rf-v6-metric > span { color: #867b91; font-size: 8.5px; font-weight: 850; text-transform: uppercase; letter-spacing: .06em; }
.rf-v6-metric > strong { color: #2b2234; font-size: 29px; line-height: 1; letter-spacing: -.05em; }
.rf-v6-metric > small { color: var(--rf6-muted); font-size: 8.5px; }
.rf-v6-dashboard-grid { display: grid; grid-template-columns: minmax(0,1.55fr) minmax(280px,.65fr); gap: 15px; }
