.rf-v6-dashboard-agent strong { overflow: hidden; font-size: 10.5px; text-overflow: ellipsis; white-space: nowrap; }
.rf-v6-dashboard-agent small { color: var(--rf6-muted); font-size: 8.5px; }
.rf-v6-agent-live { display: grid; grid-template-columns: auto auto; gap: 2px 6px; align-items: baseline; text-align: right; }
