.rf-v6-attention.critical i { background: #dd4a63; }
.rf-v6-attention.info i { background: #4c95ec; }
.rf-v6-attention.good i { background: #23b87d; }
.rf-v6-attention b { color: var(--rf6-purple); }
.rf-v6-channel-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 8px; margin-top: 16px; }
.rf-v6-channel { min-width: 0; display: grid; grid-template-columns: auto minmax(0,1fr) auto; gap: 9px; align-items: center; padding: 11px; border: 1px solid var(--rf6-line); border-radius: 13px; color: inherit; text-decoration: none; }
.rf-v6-channel i { width: 28px; height: 28px; display: grid; place-items: center; border-radius: 9px; color: #a16614; background: #fff3dc; font-size: 10px; font-style: normal; font-weight: 900; }
.rf-v6-channel i.good { color: #08724c; background: #e9f9f1; }
.rf-v6-channel > div { min-width: 0; display: grid; gap: 2px; }
.rf-v6-channel strong { color: #403448; font-size: 10px; }
.rf-v6-channel span { overflow: hidden; color: var(--rf6-muted); font-size: 8.5px; text-overflow: ellipsis; white-space: nowrap; text-transform: none; letter-spacing: 0; }
.rf-v6-channel > b { color: var(--rf6-purple); font-size: 12px; }
.rf-v6-flow-line { display: grid; grid-template-columns: repeat(4,1fr); gap: 7px; margin-top: 16px; }
.rf-v6-flow-line > div { position: relative; display: grid; gap: 2px; padding: 12px 8px; border-radius: 12px; text-align: center; background: #f8f6fb; }
.rf-v6-flow-line > div:not(:last-child)::after { content: "→"; position: absolute; top: 50%; right: -8px; z-index: 2; transform: translateY(-50%); color: #b7adbf; font-size: 10px; }
